async function handlePrompt(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  await sendMessage(chat.id, tSession(session, "prompt_title"), {
    reply_to_message_id: msg.message_id,
    reply_markup: JSON.stringify({ inline_keyboard: [[btn(tSession(session, "prompt_manage"), "custom_prompt_menu")]] }),
  });
}

async function handleSetPrompt(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;

  if (args.length < 2) {
    await sendMessage(chat.id, t(lang, "err_format") + "\n\nUse: `/setprompt [engine] text`", { reply_to_message_id: msg.message_id });
    return;
  }

  const alias = args[0].toLowerCase();
  const text = args.slice(1).join(" ").trim();
  const map: Record<string, AIEngine> = {
    "نوا": "gemini", nova: "gemini",
  };
  const engine = map[alias];

  if (!engine) { await sendMessage(chat.id, t(lang, "err_engine_invalid"), { reply_to_message_id: msg.message_id }); return; }
  if (!text) { await sendMessage(chat.id, t(lang, "err_empty_prompt"), { reply_to_message_id: msg.message_id }); return; }
  if (text.length > cfg.MAX_PROMPT_LENGTH) { await sendMessage(chat.id, t(lang, "err_prompt_toolong"), { reply_to_message_id: msg.message_id }); return; }

  session.customPromptSource = "manual";
  session.customPrompts[engine] = text;

  // در گروه → فقط پرامپت این کاربر
  if (chat.type !== "private") {
    session.userCustomPrompts = session.userCustomPrompts ?? new Map();
    session.userCustomPromptSource = session.userCustomPromptSource ?? new Map();
    session.userCustomPrompts.set(from.id, text);
    session.userCustomPromptSource.set(from.id, "manual");
    // یک تنظیم عمدی و کم‌تکرار است؛ فوراً و بدون کوالسینگ ذخیره شود تا روی
    // ایزوله‌ی بعدی برنگردد (هم‌مسیر با اصلاح پایداری پرسونا).
    await saveSession(session, env, { force: true });
    await saveIdentitySnapshot(session, from.id, true, env);
    await sendMessage(chat.id,
      lang === "fa"
        ? `✅ **پرامپت شخصی شما تنظیم شد!**\n\nفقط برای گفتگوهای شما اعمال می‌شه.`
        : `✅ **Your personal prompt set!**\n\nApplies only to your conversations.`,
      { reply_to_message_id: msg.message_id }
    );
    return;
  }

  // در پیوی → پرامپت کلی سشن
  session.customPrompts[engine] = text;
  await saveSession(session, env, { force: true });
  await saveIdentitySnapshot(session, from.id, false, env);
  const engName = engineDisplayName(engine, lang);
  await sendMessage(chat.id,
    lang === "fa"
      ? `✅ **پرامپت ${engName} تنظیم شد**\n\nبدون نیاز به /new از الان فعال است!`
      : `✅ **${engName} prompt set**\n\nActive immediately!`,
    { reply_to_message_id: msg.message_id }
  );
}

async function handleImg(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;

  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;

  if (!cfg.CF_ACCOUNTS.length) {
    await sendMessage(chat.id, t(lang, "err_config_missing"), { reply_to_message_id: msg.message_id }); return;
  }
  if (!args.length) { await sendMessage(chat.id, t(lang, "img_help"), { reply_to_message_id: msg.message_id }); return; }

  const limitCheck = await checkDailyLimitWithUser(session, from, "image", env);
  if (!limitCheck.allowed) { await sendMessage(chat.id, limitCheck.message!, { reply_to_message_id: msg.message_id }); return; }

  let prompt = args.join(" ").trim();
  let translated = false;

  if (/[\u0600-\u06FF]/.test(prompt)) {
    const transMsg = await sendMessage(chat.id, t(lang, "img_translating"), { reply_to_message_id: msg.message_id });
    try {
      const tr = await enhanceImagePrompt(prompt, env);
      if (tr && !/[\u0600-\u06FF]/.test(tr)) { prompt = tr; translated = true; }
    } finally { await deleteMessage(chat.id, transMsg.message_id); }
  } else {
    const enhanced = await enhanceImagePrompt(prompt, env).catch(() => prompt);
    if (enhanced && enhanced.trim() && enhanced !== prompt) { prompt = enhanced; translated = true; }
  }

  let statusText = t(lang, "img_start") + "\n";
  statusText += translated ? `📝 \`${args.join(" ")}\`\n🇬🇧 \`${prompt}\`\n` : `📝 \`${prompt}\`\n`;
  statusText += t(lang, "img_processing", { count: String(cfg.AI_IMAGE_MODELS.length) });
  const procMsg = await sendMessage(chat.id, statusText, { reply_to_message_id: msg.message_id });

  let success = 0;
  const errors: string[] = [];

  for (let i = 0; i < cfg.AI_IMAGE_MODELS.length; i++) {
    const model = cfg.AI_IMAGE_MODELS[i];
    await editMessageText(chat.id, procMsg.message_id,
      `${statusText}\n\n🎨 ${getShortModelName(model)} (${i + 1}/${cfg.AI_IMAGE_MODELS.length})...`,
    ).catch(() => {});

    try {
      const img = await withTimeout(generateImageCF(prompt, model, env), 45_000, "Timeout");
      if (!img) { errors.push(`• **${getShortModelName(model)}**: ❌ internal error`); continue; }
  
      const modelName = getShortModelName(model);
  
      // ساخت محتوای تاشو برای پرامپت (نمایش هر دو زبان در صورت وجود ترجمه)
      let promptContent = "";
      if (translated) {
        promptContent = `🇬🇧 ${prompt}\n\n🇮🇷 ${args.join(" ")}`;
      } else {
        promptContent = prompt;
      }

      const caption = `<blockquote expandable>${promptContent}</blockquote>\n\n<b>Model:</b> <code>${modelName}</code>`;
  
      await sendImageFile(chat.id, img, caption, { 
        reply_to_message_id: msg.message_id,
        parse_mode: "HTML"
      }, `nova_img_${generateId()}.png`);
      success++;
    } catch (e) {
      const m = e instanceof Error ? e.message : String(e);
      errors.push(`• **${getShortModelName(model)}**: ${m.includes("Timeout") ? "⏱️" : "❌"} ${m.substring(0, 40)}`);
      if (m.includes("FLAGGED_PROMPT")) {
        break;
      }
    }

    if (Date.now() - msg.date * 1000 > 27_000) break;
  }

  let final = success > 0 ? t(lang, "img_success") : t(lang, "img_failed");
  if (translated) final += `\n\nPrompt: \`${prompt}\``;

  const hasFlagged = errors.some(err => err.includes("FLAGGED_PROMPT"));
  const isOwner = from.id === cfg.BOT_OWNER_ID;
  if (hasFlagged) {
    final = lang === "fa"
      ? `🛡️ **ساخت تصویر متوقف شد:** پرامپت ارسالی شما قوانین اخلاقی/امنیتی سرور را نقض کرده است.`
      : `🛡️ **Generation stopped:** Your prompt violated safety filters.`;
  } else if (errors.length) {
    if (isOwner) {
      final += `\n\n⚠️ **جزئیات کامل خطاها (فقط برای مالک):**\n${errors.join("\n")}`;
    } else if (success === 0) {
      final += lang === "fa"
        ? `\n\n⚠️ متأسفانه ساخت تصویر با مشکل مواجه شد. لطفاً دوباره امتحان کن.`
        : `\n\n⚠️ Image generation ran into a problem. Please try again.`;
    }
  } else if (success > 0) {
    final += `\n\n🎉 ${success} ${lang === "fa" ? "تصویر ساخته شد" : "images generated"}`;
  }

  await editMessageText(chat.id, procMsg.message_id, final);

  if (success > 0) {
    await incrementUsageWithUser(session, from, "image", env);
    session.statistics.totalMessages++;
    saveSession(session, env).catch(() => {});
  }
}

async function handleSearch(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;

  if (!args.length) { await sendMessage(chat.id, t(lang, "search_usage"), { reply_to_message_id: msg.message_id }); return; }
  const query = args.join(" ").trim();
  if (query.length > 100) { await sendMessage(chat.id, t(lang, "search_long_query"), { reply_to_message_id: msg.message_id }); return; }

  const searching = await sendMessage(chat.id, t(lang, "search_searching", { query }), { reply_to_message_id: msg.message_id });

  try {
    const images = await searchGoogleImages(query, 5);
    await deleteMessage(chat.id, searching.message_id);
    await sendImageResults(chat.id, msg.message_id, images, query, lang);
  } catch (e) {
    const em = e instanceof Error ? e.message : "";
    const err = em === "NO_RESULTS" ? t(lang, "search_no_results") : em.substring(0, 100);
    await editMessageText(chat.id, searching.message_id, `${t(lang, "search_failed")}\n\n${err}\n\n${t(lang, "search_guide")}`);
  }
}

/**
 * `/deepsearch <topic>` — the explicit maximum-effort research command.
 *
 * There is no second synthesis stage here any more. The engine already plans,
 * retrieves in parallel, fills its own gaps, cross-checks and writes the report
 * under one budget, so this handler only has to deliver it (plus a PDF copy).
 * That also means a run which hits a safety limit arrives as a shorter report
 * rather than as a failure.
 */
async function handleSuperSearch(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isOwner = from.id === cfg.BOT_OWNER_ID;

  if (!args.length) {
    await sendMessage(chat.id,
      lang === "fa" ? "استفاده: `/deepsearch [موضوع]`\n\nمثال: `/deepsearch آینده انرژی هسته‌ای در ایران`" : "Usage: `/deepsearch [topic]`",
      { reply_to_message_id: msg.message_id });
    return;
  }
  if (!cfg.GOOGLE_SEARCH_API_KEY || !cfg.GOOGLE_SEARCH_ENGINE_ID) {
    await sendMessage(chat.id, t(lang, "err_config_missing"), { reply_to_message_id: msg.message_id });
    return;
  }

  const topic = args.join(" ").trim().slice(0, 300);
  const progress = await sendMessage(chat.id,
    lang === "fa" ? `🔬 **تحقیق عمیق درباره:** \`${topic}\`\n\n⏳ در حال طرح‌ریزی…` : `🔬 **Deep research on:** \`${topic}\`\n\n⏳ Planning…`,
    { reply_to_message_id: msg.message_id });

  // Progress is echoed into the same message, so the user sees movement without
  // seeing any search mechanics (no queries, no URLs, no result counts).
  let lastLabel = "";
  const onLabel = (label: string) => {
    if (!label || label === lastLabel) return;
    lastLabel = label;
    void editMessageText(chat.id, progress.message_id,
      lang === "fa" ? `🔬 **تحقیق عمیق درباره:** \`${topic}\`\n\n${label}` : `🔬 **Deep research on:** \`${topic}\`\n\n${label}`,
    ).catch(() => {});
  };

  try {
    const deps = makeSearchDeps(lang, env);
    const outcome = await runSearch(topic, "super", { ...deps, onProgress: onLabel });
    logger.info(`${describeSearchRun(outcome)} (/deepsearch)`);

    if (!outcome.sources.length) {
      await editMessageText(chat.id, progress.message_id, outcome.answer);
      return;
    }

    const report = outcome.answer + formatSourceFooter(outcome, lang);
    await deleteMessage(chat.id, progress.message_id).catch(() => {});
    await sendStreamingResponse(chat.id, msg.message_id, report, undefined, undefined, lang);

    await sendNovaExport(chat.id, report, {
      format: "pdf",
      theme: "professional",
      title: topic,
      lang,
      baseName: "deepsearch",
      caption: lang === "fa" ? "📑 نسخه‌ی سند گزارش" : "📑 Document version of the report",
    });

    session.messageCount++;
    session.statistics.totalMessages++;
    await incrementUsageWithUser(session, from, "message", env);
    await saveSession(session, env);
  } catch (e) {
    logger.error("handleSuperSearch failed", e);
    const errMsg = e instanceof Error ? e.message : String(e);
    if (errMsg === "CANCELLED_BY_USER") return;
    const debugSuffix = isOwner ? `\n\n🔧 \`\`\`\n${errMsg.slice(0, 900)}\n\`\`\`` : "";
    const userErr = (lang === "fa"
      ? "❌ تحقیق ناتمام ماند. یک‌بار دیگر امتحان کن یا موضوع را کمی محدودتر کن."
      : "❌ The research could not be completed. Try again, or narrow the topic a little.") + debugSuffix;
    await editMessageText(chat.id, progress.message_id, userErr).catch(() => {
      sendMessage(chat.id, userErr, { reply_to_message_id: msg.message_id }).catch(() => {});
    });
  }
}
// SECTION: UTILITY COMMANDS (/tr /tts /ocr /read /summarize /remember /stats /id /now)
/** یک تماس سبک Gemini با متن — برای خلاصه/ترجمه/پاسخ کوتاه. */
async function geminiQuick(
  systemPrompt: string,
  userText: string,
  timeoutMs = 14_000,
  maxTokens = 1200,
  maxChars = 6000,
): Promise<string> {
  const keyInfo = getGeminiKey();
  if (!keyInfo) throw new Error("No Gemini key available");
  const res = await withTimeout(
    callGeminiWithTools([{ text: userText.slice(0, maxChars) }], cfg.GEMINI_MODEL, keyInfo.key, [], false, systemPrompt, "user", true, timeoutMs, maxTokens),
    timeoutMs + 1000,
    "gemini quick timeout",
  );
  return (res.text ?? "").trim();
}

async function handleTranslate(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  let target = isFa ? "en" : "fa";
  let text = "";
  const joined = args.join(" ").trim();
  const explicit = joined.match(/^(fa|en|ar|de|fr|es|ru|tr|it|pt)\s*(?:\u2192|->|\u27a1|to)?\s+(.+)$/i);
  if (explicit) {
    target = explicit[1].toLowerCase();
    text = explicit[2];
  } else if (joined) {
    text = joined;
  } else if (msg.reply_to_message) {
    const r = msg.reply_to_message;
    text = r.text ?? r.caption ?? "";
    if (!text) {
      await sendMessage(chat.id, isFa ? "⚠️ پیام ریپلای‌شده متن ندارد." : "⚠️ The replied message has no text.", { reply_to_message_id: msg.message_id });
      return;
    }
  } else {
    await sendMessage(chat.id, isFa
      ? "استفاده: `/tr [متن]` یا `/tr fa:en <متن>` یا ریپلای به پیام\nمثال: `/tr en سلام دنیا`"
      : "Usage: `/tr [text]` or `/tr fa:en <text>` or reply to a message\nExample: `/tr fa hello world`", { reply_to_message_id: msg.message_id });
    return;
  }

  const targetName: Record<string, string> = { fa: "Persian", en: "English", ar: "Arabic", de: "German", fr: "French", es: "Spanish", ru: "Russian", tr: "Turkish", it: "Italian", pt: "Portuguese" };
  try {
    const translated = await geminiQuick(
      `You are a precise professional translator. Translate the user's text into ${targetName[target] ?? target}. Preserve tone, emoji, code blocks and numbers. Output ONLY the translation with no explanations.`,
      text,
      14_000,
      1500,
    );
    await sendStreamingResponse(chat.id, msg.message_id,
      `🌐 <b>${isFa ? "ترجمه" : "Translation"}:</b> <code>${target}</code>\n\n${translated}`, undefined, undefined, lang);
  } catch (e) {
    logger.error("handleTranslate failed", e);
    await sendMessage(chat.id, isFa ? "❌ ترجمه ناموفق بود." : "❌ Translation failed.", { reply_to_message_id: msg.message_id });
  }
}

async function handleTTS(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  let text = args.join(" ").trim();
  if (!text && msg.reply_to_message) {
    text = (msg.reply_to_message.text ?? msg.reply_to_message.caption ?? "").trim();
  }
  if (!text) {
    await sendMessage(chat.id, isFa ? "استفاده: `/tts <متن>` یا ریپلای به یک پیام" : "Usage: `/tts <text>` or reply to a message", { reply_to_message_id: msg.message_id });
    return;
  }
  if (text.length > 400) {
    await sendMessage(chat.id, isFa ? "⚠️ متن خیلی طولانی است (حداکثر ۴۰۰ کاراکتر)." : "⚠️ Text too long (max 400 chars).", { reply_to_message_id: msg.message_id });
    return;
  }

  const limitCheck = await checkDailyLimitWithUser(session, from, "voice_sent", env);
  if (!limitCheck.allowed) { await sendMessage(chat.id, limitCheck.message!, { reply_to_message_id: msg.message_id }); return; }

  const loading = await sendMessage(chat.id, isFa ? "🎙️ در حال ساخت صدا..." : "🎙️ Synthesizing voice...", { reply_to_message_id: msg.message_id });
  try {
    const ok = await sendVoiceResponse(chat.id, msg.message_id, text, env);
    await deleteMessage(chat.id, loading.message_id).catch(() => {});
    if (ok) {
      await incrementUsageWithUser(session, from, "voice_sent", env);
    } else {
      await sendMessage(chat.id, isFa ? "❌ ساخت صدا ناموفق بود." : "❌ Voice synthesis failed.", { reply_to_message_id: msg.message_id });
    }
  } catch (e) {
    logger.error("handleTTS failed", e);
    await editMessageText(chat.id, loading.message_id, isFa ? "❌ ساخت صدا ناموفق بود." : "❌ Voice synthesis failed.").catch(() => {});
  }
}

async function handleOCR(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from, reply_to_message } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  const photo = reply_to_message?.photo;
  const doc = reply_to_message?.document;
  const isImageDoc = doc && (doc.mime_type?.startsWith("image/") || /\.(png|jpe?g|webp)$/i.test(doc.file_name ?? ""));
  if (!photo && !isImageDoc) {
    await sendMessage(chat.id, isFa ? "⚠️ روی یک عکس ریپلای کن تا متن آن استخراج شود." : "⚠️ Reply to an image to extract its text (OCR).", { reply_to_message_id: msg.message_id });
    return;
  }

  const fileId = photo ? photo[photo.length - 1].file_id : doc!.file_id;
  const mime = isImageDoc ? (doc!.mime_type ?? "image/jpeg") : "image/jpeg";
  const loading = await sendMessage(chat.id, isFa ? "🔍 در حال استخراج متن از تصویر..." : "🔍 Extracting text from image...", { reply_to_message_id: msg.message_id });
  try {
    const fileUrl = await getFileUrl(fileId);
    const res = await fetchWithTimeout(fileUrl, {}, 25_000);
    const buf = await res.arrayBuffer();
    const b64 = arrayBufferToBase64(buf);
    const sys = isFa
      ? "You are an OCR engine. Extract ALL text from the image verbatim, preserving line breaks, numbers and punctuation. Output ONLY the extracted text with no commentary."
      : "You are an OCR engine. Extract ALL text from the image verbatim, preserving line breaks, numbers and punctuation. Output ONLY the extracted text with no commentary.";
    const keyInfo = getGeminiKey();
    if (!keyInfo) throw new Error("No Gemini key");
    const resp = await withTimeout(
      callGeminiWithTools(
        [{ inline_data: { mime_type: mime, data: b64 } }, { text: "Extract all text from this image verbatim." }],
        cfg.GEMINI_MODEL, keyInfo.key, [], false, sys, "user", true, 18_000, 2000,
      ),
      19_000,
      "ocr timeout",
    );
    const extracted = (resp.text ?? "").trim();
    if (!extracted) {
      await editMessageText(chat.id, loading.message_id, isFa ? "🔍 متنی در تصویر پیدا نشد." : "🔍 No text found in the image.").catch(() => {});
      return;
    }
    await deleteMessage(chat.id, loading.message_id).catch(() => {});
    await sendStreamingResponse(chat.id, msg.message_id,
      `📄 <b>${isFa ? "متن استخراج‌شده" : "Extracted text"}:</b>\n\n${escapeHTML(extracted)}`, undefined, undefined, lang);
  } catch (e) {
    logger.error("handleOCR failed", e);
    await editMessageText(chat.id, loading.message_id, isFa ? "❌ استخراج متن ناموفق بود." : "❌ OCR failed.").catch(() => {});
  }
}

async function handleReadURL(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  let url = args[0] ?? "";
  if (!url && msg.reply_to_message) url = msg.reply_to_message.text ?? "";
  url = url.trim();
  if (!/^https?:\/\//i.test(url)) {
    await sendMessage(chat.id, isFa ? "⚠️ لینک معتبر بفرست: `/read https://example.com`" : "⚠️ Send a valid link: `/read https://example.com`", { reply_to_message_id: msg.message_id });
    return;
  }

  const loading = await sendMessage(chat.id, isFa ? "📖 در حال خواندن صفحه..." : "📖 Reading page...", { reply_to_message_id: msg.message_id });
  try {
    const res = await fetchExternalSafe(url, { headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" } }, 10_000, 512 * 1024);
    const rawText = normalizeWebPageText(await readResponseTextLimited(res, 512 * 1024), 6000);
    if (rawText.length < 60) {
      await editMessageText(chat.id, loading.message_id, isFa ? "⚠️ محتوای قابل‌خواندی در این صفحه پیدا نشد." : "⚠️ No readable content found on this page.").catch(() => {});
      return;
    }
    const summary = await geminiQuick(
      isFa
        ? `You are a careful page summarizer. Summarize the following page content in Persian, in 5-8 clear sentences or bullets. Include key numbers, dates and names exactly as stated. If content is missing or unreadable say so honestly. Then list the 3 most important points.`
        : `You are a careful page summarizer. Summarize the following page content in English, in 5-8 clear sentences or bullets. Include key numbers, dates and names exactly as stated. If content is missing or unreadable say so honestly. Then list the 3 most important points.`,
      rawText,
      18_000,
      1600,
    );
    await deleteMessage(chat.id, loading.message_id).catch(() => {});
    await sendStreamingResponse(chat.id, msg.message_id,
      `📖 <b>${isFa ? "خلاصه صفحه" : "Page summary"}:</b> <code>${escapeHTML(url.slice(0, 60))}</code>\n\n${escapeHTML(summary)}\n\n🔗 <a href="${escapeHTML(url)}">${isFa ? "مشاهده منبع" : "View source"}</a>`, undefined, undefined, lang);
  } catch (e) {
    logger.error("handleReadURL failed", e);
    await editMessageText(chat.id, loading.message_id, isFa ? "❌ خواندن صفحه ناموفق بود." : "❌ Failed to read the page.").catch(() => {});
  }
}

async function handleSummarizeGroup(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  const groupCtx = groupContextCache.get(chat.id);
  const recentMessages = (groupCtx?.messages ?? []).slice(-30);
  if (recentMessages.length < 2) {
    await sendMessage(chat.id, isFa ? "⚠️ هنوز گفتگوی کافی در این گروه ثبت نشده است." : "⚠️ Not enough conversation recorded in this group yet.", { reply_to_message_id: msg.message_id });
    return;
  }
  const transcript = recentMessages.map(m => `${m.userName}: ${m.text}`).join("\n");
  const loading = await sendMessage(chat.id, isFa ? "🧠 در حال خلاصه‌سازی گفتگوی گروه..." : "🧠 Summarizing group conversation...", { reply_to_message_id: msg.message_id });
  try {
    const summary = await geminiQuick(
      isFa
        ? `You summarize group chats. Summarize this conversation in Persian: main topics, decisions, open questions, mood, and who said what. Keep it under 10 short lines.`
        : `You summarize group chats. Summarize this conversation in English: main topics, decisions, open questions, mood, and who said what. Keep it under 10 short lines.`,
      transcript,
      18_000,
      1500,
    );
    await deleteMessage(chat.id, loading.message_id).catch(() => {});
    await sendStreamingResponse(chat.id, msg.message_id,
      `📊 <b>${isFa ? "خلاصه گفتگوی اخیر گروه" : "Recent group chat summary"}</b>\n\n${escapeHTML(summary)}`, undefined, undefined, lang);
  } catch (e) {
    logger.error("handleSummarizeGroup failed", e);
    await editMessageText(chat.id, loading.message_id, isFa ? "❌ خلاصه‌سازی ناموفق بود." : "❌ Summarization failed.").catch(() => {});
  }
}

async function handleRemember(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const note = args.join(" ").trim();
  if (!note) {
    await sendMessage(chat.id, isFa ? "استفاده: `/remember <متن>` — مثلاً `/remember تولدم ۱۵ مهره`" : "Usage: `/remember <text>` — e.g. `/remember my birthday is Jan 1`", { reply_to_message_id: msg.message_id });
    return;
  }

  let mem = session.userMemories.get(from.id);
  if (!mem) {
    mem = {
      userId: from.id,
      userName: from.username ?? from.first_name,
      firstName: from.first_name,
      lastSeen: Date.now(),
      messageCount: 0,
      topics: [],
      personality: "",
      preferences: [],
      interactionStyle: "",
      entities: [],
      ongoingProjects: [],
      keyFacts: [],
      moodTrend: "",
      relationshipGraph: [],
    };
  }
  const clean = note.slice(0, 300);
  // ذخیره‌ی یادداشت به‌صورت ساختاریافته — بدون تکرار
  if (!mem.keyFacts.some(f => f.toLowerCase() === clean.toLowerCase())) {
    mem.keyFacts.unshift(clean);
    if (mem.keyFacts.length > 40) mem.keyFacts.length = 40;
  }
  mem.lastSeen = Date.now();
  session.userMemories.set(from.id, mem);
  await saveSession(session, env, { force: true });
  _sharedMemCache.delete(from.id);
  await saveIdentitySnapshot(session, from.id, false, env);
  await sendMessage(chat.id, isFa ? `✅ یادم ماند: «${clean}»` : `✅ Remembered: "${clean}"`, { reply_to_message_id: msg.message_id });
}

async function handleMyMemory(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const mem = session.userMemories.get(from.id) ?? (await loadSharedUserMemory(from.id, env) ?? undefined);
  if (!mem || (!mem.keyFacts?.length && !mem.preferences?.length && !mem.topics?.length && !mem.personality)) {
    await sendMessage(chat.id, isFa
      ? "🧠 هنوز چیزی درباره‌ی تو ذخیره نکرده‌ام. با `/remember <متن>` چیزی به من یاد بده."
      : "🧠 I haven't stored anything about you yet. Teach me with `/remember <text>`.", { reply_to_message_id: msg.message_id });
    return;
  }
  const profile = formatMemoryProfile(mem, from.first_name, lang);
  await sendStreamingResponse(chat.id, msg.message_id,
    `🧠 <b>${isFa ? "حافظه‌ی من درباره‌ی تو" : "My memory about you"}:</b>\n${escapeHTML(profile)}`, undefined, undefined, lang);
}

async function handleForgetMemory(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const prior = session.userMemories.get(from.id);
  const cleared =
    (prior?.keyFacts?.length ?? 0) + (prior?.preferences?.length ?? 0) +
    (prior?.topics?.length ?? 0) + (prior?.entities?.length ?? 0) +
    (prior?.ongoingProjects?.length ?? 0) + (session.groupMembers?.get(from.id)?.facts?.length ?? 0);
  // Deleting the entry outright left no `clearedAt`, so in a group the profile
  // was rehydrated from the private session on the next message. Store a
  // tombstone instead of removing the key.
  session.userMemories.set(from.id, {
    userId: from.id, userName: from.username ?? from.first_name, firstName: from.first_name,
    lastSeen: Date.now(), messageCount: prior?.messageCount ?? 0,
    topics: [], personality: "", preferences: [], interactionStyle: "",
    entities: [], ongoingProjects: [], keyFacts: [], moodTrend: "",
    relationshipGraph: [], lastProfileUpdate: 0, clearedAt: Date.now(),
  });
  const roster = session.groupMembers?.get(from.id);
  if (roster) roster.facts = [];
  // Otherwise the next prompt build reads the profile straight back out of the
  // 5-minute shared-memory cache.
  _sharedMemCache.delete(from.id);
  await saveSession(session, env, { force: true });
  await sendMessage(chat.id,
 isFa
      ? `🗑️ <b>حافظه‌ی من درباره‌ی تو پاک شد.</b>\n\n${cleared} نکته‌ای که ازت یاد گرفته بودم حذف شد. تاریخچه‌ی گفتگو دست‌نخورده مونده — برای پاک‌کردن اون از /new استفاده کن.`
      : `🗑️ <b>My memory about you was cleared.</b>\n\nDeleted ${cleared} learned note(s). Your conversation history is untouched — use /new to clear that too.`,
    { parse_mode: "HTML", reply_to_message_id: msg.message_id });
}

async function handleStatsMe(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const d = session.dailyLimits;
  const bar = (used: number, total: number): string => {
    const pct = total > 0 ? Math.min(100, Math.round((used / total) * 100)) : 0;
    const filled = Math.round((pct / 100) * 10);
    return "█".repeat(filled) + "░".repeat(10 - filled) + ` ${pct}%`;
  };
  const isVip = session.vipStatus || from.id === cfg.BOT_OWNER_ID;
  const imgLimit = isVip ? cfg.VIP_IMAGE_LIMIT : cfg.IMAGE_LIMIT;
  const msgLimit = isVip ? cfg.VIP_MESSAGE_LIMIT : cfg.MESSAGE_LIMIT;
  const voiceLimit = isVip ? cfg.VIP_VOICE_LIMIT : cfg.VOICE_LIMIT;
  const editLimit = isVip ? cfg.VIP_EDIT_LIMIT : cfg.EDIT_LIMIT;
  await sendMessage(chat.id,
    `📊 <b>${isFa ? "آمار استفاده‌ی شما" : "Your usage stats"}</b> ${isVip ? "👑" : ""}\n\n` +
    `💬 ${isFa ? "پیام" : "Messages"}: <code>${bar(d.messages, msgLimit)}</code> (${d.messages}/${msgLimit})\n` +
    `🎨 ${isFa ? "تصویر" : "Images"}: <code>${bar(d.imagesGenerated, imgLimit)}</code> (${d.imagesGenerated}/${imgLimit})\n` +
    `🎙️ ${isFa ? "صدا" : "Voice"}: <code>${bar(d.voicesSent, voiceLimit)}</code> (${d.voicesSent}/${voiceLimit})\n` +
    `🖌️ ${isFa ? "ویرایش" : "Edits"}: <code>${bar(d.imagesEdited, editLimit)}</code> (${d.imagesEdited}/${editLimit})\n` +
    `⏱️ ${isFa ? "آخرین ریست" : "Last reset"}: <code>${formatDate(d.lastReset, lang, "short")}</code>`,
    { reply_to_message_id: msg.message_id, parse_mode: "HTML" });
}

/**
 * ── /id : context-aware identifier inspector ─────────────────────────────────
 *
 * The old version printed five fixed lines and, when used as a reply, silently
 * swapped the sender for the replied-to user — so you could not tell whose id
 * you were looking at, and every media identifier (the thing people actually
 * run `/id` for) was missing. These helpers report the whole context instead:
 * chat, sender, this message, the replied-to message, and the file identifiers
 * of whatever media either one carries.
 */

/** `label: value`, with the value wrapped so Telegram makes it tap-to-copy. */
function idLine(label: string, value: string | number | null | undefined, copy = true): string | null {
  if (value === null || value === undefined) return null;
  const raw = String(value).trim();
  if (!raw) return null;
  return `• ${escapeHTML(label)}: ${copy ? `<code>${escapeHTML(raw)}</code>` : escapeHTML(raw)}`;
}

/** Render the structured fields core.ts produced through the same formatter. */
function idFieldLines(fields: IdField[]): Array<string | null> {
  return fields.map(f => idLine(f.label, f.value, f.copy));
}

/** A titled group of lines; empty groups disappear instead of printing a header. */
function idSection(icon: string, title: string, lines: Array<string | null>): string {
  const body = lines.filter(Boolean).join("\n");
  return body ? `${icon} <b>${escapeHTML(title)}</b>\n${body}` : "";
}

/** Telegram membership status, or null when it cannot be determined. */
async function chatMemberStatus(chatId: number, userId: number): Promise<string | null> {
  try {
    const m = await withTimeout(
      tg("getChatMember", { chat_id: chatId, user_id: userId }) as Promise<{ status?: string }>,
      6_000, "getChatMember timeout",
    );
    return m?.status ?? null;
  } catch {
    // Left the group, never joined, or the bot lacks the right to ask. Not an
    // error worth surfacing — the section just omits the role line.
    return null;
  }
}

/**
 * Pack already-escaped text into at most `maxParts` chunks of `maxLen`,
 * breaking only on newlines so an HTML entity is never split across a message.
 */
function packEscapedLines(escaped: string, maxLen: number, maxParts: number): string[] {
  const parts: string[] = [];
  let current = "";
  for (const line of escaped.split("\n")) {
    const piece = line.length > maxLen ? line.slice(0, maxLen) : line;
    if (current && current.length + piece.length + 1 > maxLen) {
      parts.push(current);
      if (parts.length >= maxParts) return parts;
      current = piece;
    } else {
      current = current ? `${current}\n${piece}` : piece;
    }
  }
  if (current) parts.push(current);
  return parts.slice(0, maxParts);
}

/** A one-line hint of what a message contains, for identifying which one it is. */
function idContentPreview(m: TgMessage, isFa: boolean): string | null {
  const text = (m.text ?? m.caption ?? "").replace(/\s+/g, " ").trim();
  if (!text) return null;
  const clipped = text.length > 70 ? `${text.slice(0, 70)}…` : text;
  return idLine(isFa ? "متن" : "Text", clipped, false);
}

async function handleIdInfo(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;

  const session = await getOrCreateSession(chat, from, env);
  const isFa = session.language === "fa";
  const isPrivate = chat.type === "private";
  const isOwner = from.id === cfg.BOT_OWNER_ID;
  const reply = msg.reply_to_message;

  // Owner-only escape hatch: the exact update Telegram delivered. Useful when a
  // field matters that this report does not model yet, and it is gated because
  // a raw dump can contain anything the message contained.
  if (isOwner && /^(raw|json)$/i.test((args?.[0] ?? "").trim())) {
    let dump: string;
    try {
      dump = JSON.stringify(msg, null, 2);
    } catch {
      dump = String(msg);
    }
    // Escape first, then pack: escaping can triple a chunk's length, and
    // `sendMessage` truncates rather than splitting — so chunking the raw text
    // would silently cut the tail off. Packing on line boundaries also means a
    // chunk can never end mid-entity, which would break HTML parsing.
    const chunks = packEscapedLines(escapeHTML(dump), 3_500, 3);
    for (const [i, part] of chunks.entries()) {
      await sendMessage(chat.id, `🧾 <b>raw update ${i + 1}/${chunks.length}</b>\n<pre>${part}</pre>`,
        { reply_to_message_id: i === 0 ? msg.message_id : undefined, parse_mode: "HTML" });
    }
    return;
  }

  const sections: string[] = [];

  sections.push(idSection("💬", isFa ? "چت" : "Chat", [
    idLine(isFa ? "نام" : "Title", chat.title ?? (isPrivate ? (isFa ? "گفتگوی خصوصی" : "Private chat") : null), false),
    idLine("chat_id", chat.id),
    idLine(isFa ? "نوع" : "Type", chat.type, false),
    chat.username ? idLine(isFa ? "یوزرنیم" : "Username", `@${chat.username}`, false) : null,
    idLine(isFa ? "تاپیک (thread)" : "Topic thread", msg.message_thread_id),
    (!isPrivate && session.vipStatus) ? idLine(isFa ? "وضعیت چت" : "Chat status", "VIP", false) : null,
  ]));

  // Telegram membership is a live fact and costs a round trip, so it is only
  // asked for where it exists — a private chat has no membership.
  const senderStatus = isPrivate ? null : await chatMemberStatus(chat.id, from.id);

  // VIP and block state live on the person's own session. In a group `session`
  // belongs to the *chat*, so reading `session.vipStatus` here would report the
  // group's VIP status as if it were the person's. One lookup covers both flags
  // and costs no more than `isUserBlocked` did, since that resolves the same
  // private session internally.
  const personalSession = isPrivate ? session : await getOrCreateSession({ id: from.id, type: "private" }, from, env);
  const novaFlags = [
    isOwner ? (isFa ? "مالک ربات" : "bot owner") : null,
    personalSession.vipStatus ? "VIP" : null,
    (!isOwner && personalSession.blocked === true) ? (isFa ? "مسدود" : "blocked") : null,
  ].filter(Boolean).join(" · ");

  sections.push(idSection("🙋", isFa ? "شما" : "You", [
    idLine(isFa ? "نام" : "Name", describeUserLabel(from), false),
    idLine("user_id", from.id),
    idLine(isFa ? "زبان تلگرام" : "Telegram language", from.language_code, false),
    from.is_premium ? idLine(isFa ? "اشتراک" : "Account", "Telegram Premium", false) : null,
    senderStatus ? idLine(isFa ? "نقش در چت" : "Role in chat", senderStatus, false) : null,
    novaFlags ? idLine(isFa ? "وضعیت نزد نوا" : "Status with Nova", novaFlags, false) : null,
  ]));

  const thisMedia = describeMessageMedia(msg, isFa);
  sections.push(idSection("📨", isFa ? "این پیام" : "This message", [
    idLine("message_id", msg.message_id),
    idLine(isFa ? "زمان" : "Sent", formatDate(msg.date * 1000, session.language), false),
    msg.edit_date ? idLine(isFa ? "ویرایش" : "Edited", formatDate(msg.edit_date * 1000, session.language), false) : null,
    idLine("media_group_id", msg.media_group_id),
    msg.via_bot ? idLine(isFa ? "از طریق ربات" : "Via bot", describeUserLabel(msg.via_bot), false) : null,
    msg.business_connection_id ? idLine("business_connection_id", msg.business_connection_id) : null,
    ...idFieldLines(describeForwardOrigin(msg.forward_origin, isFa)),
    thisMedia ? idLine(isFa ? "محتوا" : "Content", `${thisMedia.icon} ${thisMedia.label}`, false) : null,
    ...idFieldLines(thisMedia?.fields ?? []),
  ]));

  if (reply) {
    const author = reply.from
      ? describeUserLabel(reply.from)
      : reply.sender_chat
        ? `${reply.sender_chat.title ?? reply.sender_chat.type}${reply.author_signature ? ` — ${reply.author_signature}` : ""}`
        : null;
    const replyMedia = describeMessageMedia(reply, isFa);
    sections.push(idSection("↩️", isFa ? "پیام ریپلای‌شده" : "Replied message", [
      idLine(isFa ? "فرستنده" : "Author", author, false),
      reply.from ? idLine("user_id", reply.from.id) : null,
      reply.sender_chat ? idLine(isFa ? "شناسه فرستنده (چت)" : "Sender chat ID", reply.sender_chat.id) : null,
      reply.from?.is_bot ? idLine(isFa ? "نوع فرستنده" : "Sender type", isFa ? "ربات" : "bot", false) : null,
      idLine("message_id", reply.message_id),
      idLine(isFa ? "زمان" : "Sent", formatDate(reply.date * 1000, session.language), false),
      idLine("media_group_id", reply.media_group_id),
      ...idFieldLines(describeForwardOrigin(reply.forward_origin, isFa)),
      idContentPreview(reply, isFa),
      replyMedia ? idLine(isFa ? "محتوا" : "Content", `${replyMedia.icon} ${replyMedia.label}`, false) : null,
      ...idFieldLines(replyMedia?.fields ?? []),
    ]));
  }

  sections.push(idSection("🤖", isFa ? "ربات" : "Bot", [
    idLine(isFa ? "نام" : "Name", describeUserLabel(BOT_INFO), false),
    idLine("bot_id", BOT_SELF_ID ?? BOT_INFO?.id),
  ]));

  const hint = reply
    ? (isFa ? "<i>روی هر مقدار بزنید تا کپی شود.</i>" : "<i>Tap any value to copy it.</i>")
    : (isFa
        ? "<i>روی هر مقدار بزنید تا کپی شود. برای بررسی یک پیام دیگر، روی آن ریپلای کنید و /id بزنید.</i>"
        : "<i>Tap any value to copy it. Reply to a message with /id to inspect that message instead.</i>");

  // `&amp;` deliberately, not a bare `&`: this is HTML parse mode, and a stray
  // ampersand can make Telegram reject the whole message — which `sendMessage`
  // then retries as plain text, showing the user raw <b> tags.
  const header = `🪪 <b>${isFa ? "شناسه‌ها و اطلاعات زمینه" : "Identifiers &amp; context"}</b>`;
  const body = [header, ...sections.filter(Boolean), hint].join("\n\n");

  // The report is normally well under one message, but a reply carrying media
  // plus a long forward chain can push past Telegram's 4096 limit — and
  // `sendMessage` truncates rather than splitting, which would silently cut a
  // file_id in half. Split on section boundaries instead.
  const parts = splitMessage(body, 3_800);
  for (const [i, part] of parts.entries()) {
    await sendMessage(chat.id, part, {
      reply_to_message_id: i === 0 ? msg.message_id : undefined,
      parse_mode: "HTML",
    });
  }
}

async function handleNow(msg: TgMessage): Promise<void> {
  const now = new Date();
  const fa = now.toLocaleString("fa-IR", { timeZone: "Asia/Tehran", dateStyle: "full", timeStyle: "medium" });
  const en = now.toLocaleString("en-US", { timeZone: "Asia/Tehran", dateStyle: "full", timeStyle: "medium" });
  await sendMessage(msg.chat.id,
    `🕰️ <b>${msg.from?.language_code === "fa" ? "هم‌اکنون در تهران" : "Now in Tehran"}</b>\n\n` +
    `<code>${escapeHTML(fa)}</code>\n<code>${escapeHTML(en)}</code>\n\n` +
    `🕒 UTC: <code>${now.toUTCString()}</code>`,
    { reply_to_message_id: msg.message_id, parse_mode: "HTML" });
}

/** دستورات سرگرمی/خلاقیت — یک تماس سبک Gemini و ارسال نتیجه */
async function handleFunCommand(
  msg: TgMessage,
  kind: "mood" | "joke" | "idea" | "plan" | "quote",
  extraText: string,
  env: Env,
): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";

  const sys: Record<string, string> = {
    mood: isFa
      ? "You analyze the emotional tone of conversations. Given the recent messages, describe the overall mood, emotional trend, and dominant feelings — in Persian, 3-5 short lines, warm and insightful. Use emoji tastefully."
      : "You analyze the emotional tone of conversations. Given the recent messages, describe the overall mood, emotional trend, and dominant feelings — in English, 3-5 short lines, warm and insightful.",
    joke: isFa
      ? "Tell a genuinely funny, original Persian joke (لطیفه). Keep it 2-4 sentences, clean, and actually clever. No offensive content."
      : "Tell a genuinely funny, original joke. Keep it 2-4 sentences, clean, and actually clever.",
    idea: isFa
      ? "Generate one creative, specific, actionable idea in Persian (2-4 sentences). Make it surprising but realistic. If the user gave a topic, build on it."
      : "Generate one creative, specific, actionable idea (2-4 sentences). Make it surprising but realistic. If the user gave a topic, build on it.",
    plan: isFa
      ? `You are a sharp productivity coach. For the user's goal, output a concrete step-by-step plan in Persian: max 6 numbered steps, each one short and actionable, with rough time estimates. No fluff.`
      : `You are a sharp productivity coach. For the user's goal, output a concrete step-by-step plan: max 6 numbered steps, each short and actionable, with rough time estimates. No fluff.`,
    quote: isFa
      ? "Share one powerful, original motivational quote in Persian, plus one sentence explaining why it matters. If the user gave a theme, match it."
      : "Share one powerful, original motivational quote, plus one sentence explaining why it matters. If the user gave a theme, match it.",
  };
  const labels: Record<string, { icon: string; fa: string; en: string }> = {
    mood: { icon: "🌡️", fa: "حال‌وهوای گفتگو", en: "Conversation mood" },
    joke: { icon: "😂", fa: "جوک", en: "Joke" },
    idea: { icon: "💡", fa: "ایده", en: "Idea" },
    plan: { icon: "🗺️", fa: "برنامه گام‌به‌گام", en: "Step-by-step plan" },
    quote: { icon: "✨", fa: "جملات انگیزشی", en: "Quote" },
  };
  const label = labels[kind];
  const icon = label.icon;
  const title = isFa ? label.fa : label.en;

  let input = extraText || "";
  if (kind === "mood" && !input) {
    const engine = session.engines.gemini;
    const recent = (engine.history ?? []).slice(-10).map(h =>
      h.parts.map(p => p.text ?? "").filter(Boolean).join(" ")
    ).filter(t => t.trim()).join("\n");
    input = recent || "No prior conversation available.";
  }
  if (kind === "mood" && !input) {
    await sendMessage(chat.id, isFa ? "⚠️ هنوز گفتگویی برای تحلیل وجود ندارد." : "⚠️ No conversation to analyze yet.", { reply_to_message_id: msg.message_id });
    return;
  }
  if (!input) input = isFa ? "یک موضوع عمومی" : "a general topic";

  const loading = await sendMessage(chat.id, `${icon} ${isFa ? "در حال آماده‌سازی..." : "Working..."}`, { reply_to_message_id: msg.message_id });
  try {
    const out = await geminiQuick(sys[kind], input, 16_000, 1200);
    await deleteMessage(chat.id, loading.message_id).catch(() => {});
    await sendStreamingResponse(chat.id, msg.message_id,
      `${icon} <b>${escapeHTML(title)}</b>\n\n${escapeHTML(out)}`, undefined, undefined, lang);
  } catch (e) {
    logger.error(`handleFunCommand(${kind}) failed`, e);
    await editMessageText(chat.id, loading.message_id, isFa ? "❌ ناموفق بود." : "❌ Failed.").catch(() => {});
  }
}

/** فهرست Assetهای میزبانی‌شده‌ی کاربر (عکس‌ها/تصاویر تولیدی) در چت. */
async function handleMyAssets(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const assets = await listUserAssets(env, from.id, 12);
  if (!assets.length) {
    await sendMessage(chat.id, isFa
      ? "🗂️ هنوز Assetی نداری. با `/img` تصویر بساز یا عکسی بفرست تا به‌صورت خودکار ذخیره شود (۷ روز)."
      : "🗂️ You have no assets yet. Generate an image with `/img` or send a photo — it's stored automatically for 7 days.", { reply_to_message_id: msg.message_id });
    return;
  }
  const lines = assets.map((a, i) =>
    `#${i + 1} — ${a.kind === "gif" ? "🎞️" : a.kind === "voice" ? "🎙️" : "🖼️"} <code>${escapeHTML(a.id.slice(0, 22))}</code> · ${a.source ?? "ai"} · ${formatDate(a.createdAt, lang, "short")}`
  ).join("\n");
  await sendMessage(chat.id,
    `🗂️ <b>${isFa ? "Assetهای شما" : "Your assets"}</b> (${assets.length})\n\n${lines}\n\n` +
    `${isFa ? "برای دریافت یکی: روی آن ریپلای کن و `/get` بفرست" : "To fetch one: reply to a numbered message with /get"}`,
    { reply_to_message_id: msg.message_id, parse_mode: "HTML" });
}

/** دریافت یک Asset میزبانی‌شده به‌صورت فایل در چت (ریپلای به پیام /assets). */
async function handleGetAsset(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const isFa = lang === "fa";
  const assets = await listUserAssets(env, from.id, 12);
  if (!assets.length) {
    await sendMessage(chat.id, isFa ? "🗂️ Assetی نداری." : "🗂️ You have no assets.", { reply_to_message_id: msg.message_id });
    return;
  }
  // انتخاب: آرگومان عددی → همان ایندکس؛ ریپلای به پیام /assets → اولین Asset
  let pick = assets[0];
  const idxArg = Number(args[0]);
  if (Number.isFinite(idxArg) && idxArg >= 1 && idxArg <= assets.length) pick = assets[idxArg - 1];
  if (!pick) return;
  // Assetهای خارجی (جستجوی وب) بلاب میزبانی‌شده ندارند — فقط لینک را بفرست
  if (pick.source === "search") {
    await sendMessage(chat.id, isFa ? `🔗 لینک: ${pick.url}` : `🔗 Link: ${pick.url}`, { reply_to_message_id: msg.message_id });
    return;
  }
  const buf = await getMediaBlob(env, pick.id);
  if (!buf) {
    await sendMessage(chat.id, isFa ? "❌ این Asset منقضی شده (۷ روز)." : "❌ This asset has expired (7 days).", { reply_to_message_id: msg.message_id });
    return;
  }
  await sendImageFile(chat.id, new Uint8Array(buf),
    isFa ? `🗂️ ${pick.prompt ?? "Asset"}` : `🗂️ ${pick.prompt ?? "Asset"}`,
    { reply_to_message_id: msg.message_id, parse_mode: "HTML" }, `nova_asset_${generateId()}.png`);
}

async function handleMyApps(msg: TgMessage, env: Env, page = 0, editId?: number): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  // Own projects only, plus the draft/live distinction: a project whose source
  // was delivered but never deployed has no public URL, and listing it as if it
  // did is how a "link" ends up in front of a user pointing at nothing.
  const myApps = await listDeployments(env, { ownerId: from.id, limit: 60 });
  const perPage = 5;
  const totalPages = Math.max(1, Math.ceil(myApps.length / perPage));
  const safePage = Math.max(0, Math.min(page, totalPages - 1));
  const slice = myApps.slice(safePage * perPage, (safePage + 1) * perPage);

  let text = lang === "fa" ? `🌐 <b>پروژه‌های من (${myApps.length})</b>\n\n` : `🌐 <b>My projects (${myApps.length})</b>\n\n`;
  if (!myApps.length) text += lang === "fa" ? "هنوز پروژه‌ای نساختی." : "You haven't built anything yet.";
  slice.forEach((app, i) => {
    const idx = safePage * perPage + i + 1;
    const facts = factsFromMeta(app);
    const state = facts.servable
      ? (lang === "fa" ? `فعال · ⏳ باقی‌مانده ${formatRemaining(facts.remainingMs, lang)}` : `live · ⏳ ${formatRemaining(facts.remainingMs, lang)} left`)
      : app.status === "draft"
        ? (lang === "fa" ? "منتشر نشده (میزبانی اختیاری)" : "not deployed yet (hosting is optional)")
        : (lang === "fa" ? "میزبانی منقضی شده" : "hosting expired");
    const exp = facts.expiresAt ? formatDate(facts.expiresAt, lang, "short") : (lang === "fa" ? "—" : "—");
    text += `<b>${idx}.</b> <code>${escapeHTML(app.name)}</code>\n   ╰┈➤ 📅 ${formatDate(app.createdAt, lang, "short")} · ${escapeHTML(state)}\n\n`;
  });

  const rows: InlineBtn[][] = [
    // The dashboard gathers everything this list shows (and reminders, assets,
    // memory controls on top) — always offer the jump, even on an empty list.
    [userDashboardButton(lang, chat.type === "private")],
  ];
  slice.forEach(app => {
    const facts = factsFromMeta(app);
    // A `web_app` button needs an absolute https url; without one Telegram rejects
    // the entire keyboard, so /myapps would fail wholesale in an isolate that has
    // not learned its origin. Fall back to a plain link row in that case.
    const appUrl = facts.servable && requestOrigin.startsWith("https://") ? `${requestOrigin}/app/${app.name}` : "";
    if (appUrl) {
      rows.push([{ text: `🎮 ${app.name}`, web_app: { url: appUrl } }]);
      rows.push([
        btn(lang === "fa" ? "🗑️ حذف میزبانی" : "🗑️ Delete hosting", `appdel:${app.name}`),
        ...(facts.canExtend ? [btn(lang === "fa" ? "⏳ تمدید" : "⏳ Extend", `appext:${app.name}`)] : []),
      ]);
    } else if (app.status === "draft") {
      rows.push([
        btn(lang === "fa" ? `🚀 اجرا روی سرور — ${app.name}` : `🚀 Run on Server — ${app.name}`, `deploy:${app.name}`),
        btn(lang === "fa" ? "🗑️ حذف" : "🗑️ Delete", `myapp_del_${app.name}_${safePage}`),
      ]);
    } else {
      rows.push([
        btn(lang === "fa" ? `🚀 اجرای مجدد — ${app.name}` : `🚀 Deploy again — ${app.name}`, `deploy:${app.name}`),
        btn(lang === "fa" ? "🗑️ حذف" : "🗑️ Delete", `myapp_del_${app.name}_${safePage}`),
      ]);
    }
  });
  if (totalPages > 1) rows.push([
    ...(safePage > 0 ? [btn("◀️", `myapps_page_${safePage - 1}`)] : []),
    btn(`${safePage + 1}/${totalPages}`, "noop"),
    ...(safePage < totalPages - 1 ? [btn("▶️", `myapps_page_${safePage + 1}`)] : []),
  ]);

  const opts = { parse_mode: "HTML" as const, reply_markup: JSON.stringify(validateKeyboard({ inline_keyboard: rows })) };
  if (editId) await editMessageText(chat.id, editId, text, opts);
  else await sendMessage(chat.id, text, { ...opts, reply_to_message_id: msg.message_id });
}

async function handlePdfCommand(msg: TgMessage, args: string[], env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const content = args.join(" ").trim();

  if (!content) {
    await sendMessage(chat.id, lang === "fa" ? "استفاده: `/pdf متن شما`" : "Usage: `/pdf your text`", { reply_to_message_id: msg.message_id });
    return;
  }

  const status = await sendMessage(
    chat.id,
    lang === "fa" ? "📑 **در حال ساخت سند...**" : "📑 **Generating document...**",
    { reply_to_message_id: msg.message_id },
  );

  const delivered = await sendNovaExport(chat.id, content, {
    format: "pdf",
    theme: "professional",
    lang,
    caption: lang === "fa" ? "📑 سند شما آماده است." : "📑 Your document is ready.",
    replyTo: msg.message_id,
  });
  await deleteMessage(chat.id, status.message_id).catch(() => {});
  if (delivered) return;

  await sendTelegramTextDocument(
    chat.id,
    content,
    `nova_${Date.now()}.txt`,
    lang === "fa" ? "⚠️ ساخت سند ناموفق بود. فایل متنی ارسال شد." : "⚠️ Document generation failed. Text file sent instead.",
    msg.message_id,
  );
}

async function handleRebuild(msg: TgMessage, env: Env): Promise<void> {
  const { chat } = msg;
  const proc = await sendMessage(chat.id, "🔧 **در حال بازسازی و پاکسازی کامل پایگاه داده...**\n\n⏳ این فرآیند ممکن است چند دقیقه طول بکشد، لطفا صبور باشید.", { reply_to_message_id: msg.message_id });

  let allKeys: Array<{ name: string }> = [];
  let list = await env.SESSIONS.list({ prefix: "session:" });
  allKeys.push(...list.keys);
  while (!list.list_complete && list.cursor) {
    list = await env.SESSIONS.list({ prefix: "session:", cursor: list.cursor });
    allKeys.push(...list.keys);
  }

  let fixed = 0;
  let skipped = 0;

  // مرحله ۱: بهینه‌سازی و اصلاح ساختار سشن‌های معتبر
  for (const item of allKeys) {
    try {
      const raw = await env.SESSIONS.get(item.name, "json") as Record<string, unknown> | null;
      if (!raw) { skipped++; continue; }

      let changed = false;
      if (!raw.statistics) { 
        raw.statistics = { 
          totalMessages: raw.messageCount ?? 0, 
          geminiMessages: 0, 
          voicesReceived: 0, 
          firstUsed: raw.lastSeen ?? Date.now() 
        }; 
        changed = true; 
      }
      if (!raw.dailyLimits) { 
        raw.dailyLimits = { 
          messages: 0, 
          voicesSent: 0, 
          voicesReceived: 0, 
          imagesGenerated: 0, 
          imagesEdited: 0, 
          webapps: 0, 
          lastReset: Date.now() 
        }; 
        changed = true; 
      } else if (typeof (raw.dailyLimits as Record<string, unknown>).imagesEdited !== "number") {
        (raw.dailyLimits as Record<string, unknown>).imagesEdited = 0;
        (raw.dailyLimits as Record<string, unknown>).webapps = 0;
        changed = true;
      }

      if (changed) { 
        await env.SESSIONS.put(item.name, JSON.stringify(raw)); 
        fixed++; 
      }
    } catch { 
      skipped++; 
    }
  }

  // مرحله ۲: تشخیص چت‌های مرده با حفظ حریم سقف کلاودفلر
  async function isChatDead(chatId: number): Promise<boolean> {
    try {
      await tg("sendChatAction", { chat_id: chatId, action: "typing" });
      return false;
    } catch (e) {
      const m = e instanceof Error ? e.message.toLowerCase() : "";
      return (
        m.includes("forbidden") ||
        m.includes("chat not found") ||
        m.includes("bot was kicked") ||
        m.includes("user is deactivated") ||
        m.includes("blocked") ||
        m.includes("kicked")
      );
    }
  }

  const MAX_SUBREQUESTS = 25; // سقف ایمن برای جلوگیری از خطای Worker Subrequest Limit کلاودفلر

  // ۱. اسکن گروه‌ها
  const allGroups = await listGroups(env);
  let purgedGroups = 0;
  let groupChecks = 0;
  
  const GROUP_CHUNK = 5;
  for (let i = 0; i < allGroups.length && groupChecks < MAX_SUBREQUESTS; i += GROUP_CHUNK) {
    const slice = allGroups.slice(i, i + GROUP_CHUNK);
    await Promise.all(slice.map(async (g) => {
      if (groupChecks >= MAX_SUBREQUESTS) return;
      groupChecks++;
      const dead = await isChatDead(g.chatId);
      if (dead) {
        await env.SESSIONS.delete(`group_info:${g.chatId}`).catch(() => {});
        await env.SESSIONS.delete(`session:${g.chatId}`).catch(() => {});
        await env.SESSIONS.delete(`groupcfg:${g.chatId}`).catch(() => {});
        await env.SESSIONS.delete(`group_vip:${g.chatId}`).catch(() => {});
        _groupInfoCache.delete(g.chatId);
        _groupInfoLastPersistTs.delete(g.chatId);
        dropSessionMemory(g.chatId);
        purgedGroups++;
      }
    }));
    await sleep(150);
  }

  // ۲. اسکن کاربران با ظرفیت باقیمانده
  const allPrivateUsers = await getAllUserStats(env);
  let purgedUsers = 0;
  let userChecks = 0;
  const remainingBudget = MAX_SUBREQUESTS - groupChecks;

  const USER_CHUNK = 5;
  if (remainingBudget > 0) {
    for (let i = 0; i < allPrivateUsers.length && userChecks < remainingBudget; i += USER_CHUNK) {
      const slice = allPrivateUsers.slice(i, i + USER_CHUNK);
      await Promise.all(slice.map(async (u) => {
        if (userChecks >= remainingBudget) return;
        userChecks++;
        const dead = await isChatDead(u.userId);
        if (dead) {
          await env.SESSIONS.delete(`session:${u.userId}`).catch(() => {});
          await env.SESSIONS.delete(`user_blocked:${u.userId}`).catch(() => {});
          dropSessionMemory(u.userId);
          purgedUsers++;
        }
      }));
      await sleep(150);
    }
  }

  sessionCache.clear();

  // ۳. مهاجرت متادیتا وب‌اپ‌ها
  const appList = await env.SESSIONS.list({ prefix: "app:" });
  let migratedApps = 0;
  for (const key of appList.keys) {
    const appName = key.name.replace("app:", "");
    const existing = await env.SESSIONS.get(`app_meta:${appName}`, "json");
    if (!existing) {
      const code = await env.SESSIONS.get(key.name, "text") ?? "";
      // Legacy `app:` KV blobs with no metadata get a real deployment row under
      // the migration policy (one final Pro-length window), so they keep working
      // and are still guaranteed to expire like everything else.
      const now = Date.now();
      await upsertDeploymentRecord(env, migrateLegacyMeta({
        name: appName,
        createdAt: now,
        createdBy: cfg.BOT_OWNER_ID,
        createdByName: "Admin",
        size: new TextEncoder().encode(code).length,
        viewCount: 0,
        expiresAt: null,
      }, now));
      migratedApps++;
    }
  }

  const resultText = `✅ **عملیات پاکسازی و بازسازی پایگاه داده پایان یافت!**\n\n` +
    `🛠️ سشن‌های اصلاح‌شده: \`${fixed}\` مورد\n` +
    `👥 گروه‌های مرده حذف‌شده در این دور: \`${purgedGroups}\` گروه\n` +
    `👤 کاربران بلاک کرده حذف‌شده در این دور: \`${purgedUsers}\` کاربر\n` +
    `🌐 وب‌اپ‌های مهاجرت داده شده: \`${migratedApps}\` وب‌اپ\n` +
    `⏭️ کل رکوردهای باقی‌مانده (برای اجراهای بعد): \`${Math.max(0, (allGroups.length + allPrivateUsers.length) - (groupChecks + userChecks))}\` مورد\n\n` +
    `💡 _نکته: به دلیل محدودیت‌های سخت‌گیرانه شبکه‌ای کلاودفلر (محدودیت ۵۰ ساب‌ریکوئست)، در هر اجرا تعداد مشخصی بررسی می‌شوند. همچنین سیستم برادکست فعال ربات نیز به طور هوشمند و خودکار کاربران بلاک کرده را در زمان ارسال پاکسازی می‌کند._`;

  await editMessageText(chat.id, proc.message_id, resultText);
}

interface PartsWithMedia {
  parts: Part[];
  pendingImageBytes?: ArrayBuffer;
}

async function buildPartsWithReplyContext(msg: TgMessage, env: Env, lang: Language): Promise<PartsWithMedia> {
  const parts: Part[] = [];
  let pendingImageBytes: ArrayBuffer | undefined;
  const userText = msg.text ?? msg.caption ?? "";
  const senderName = msg.from?.first_name ?? (lang === "fa" ? "کاربر" : "User");
  const isGroup = msg.chat.type !== "private";

  const prefix = isGroup
    ? (lang === "fa" ? `[فرستنده: ${senderName}]: ` : `[Sender: ${senderName}]: `)
    : "";

  if (msg.reply_to_message) {
    const reply = msg.reply_to_message;
    logger.info(
    `[reply-media-debug] ` +
    `chat=${msg.chat.id} ` +
    `replyId=${reply.message_id} ` +
    `text=${Boolean(reply.text)} ` +
    `photo=${Boolean(reply.photo?.length)} ` +
    `voice=${Boolean(reply.voice)} ` +
    `audio=${Boolean(reply.audio)} ` +
    `video=${Boolean(reply.video)} ` +
    `animation=${Boolean(reply.animation)} ` +
    `document=${Boolean(reply.document)} ` +
    `documentMime=${reply.document?.mime_type ?? ""} ` +
    `documentName=${reply.document?.file_name ?? ""}`,
    );
    const replierName = reply.from?.first_name ?? (lang === "fa" ? "کاربر" : "User");
    
    // ۱. ریپلای روی متن
    if (reply.text) {
      const contextPrompt = lang === "fa"
        ? `[کاربر ${senderName} به این پیام از ${replierName} ریپلای کرده است:\n"${reply.text}"]\n\nپیام کاربر: ${userText}`
        : `[User ${senderName} replied to this message from ${replierName}:\n"${reply.text}"]\n\nUser message: ${userText}`;
      parts.push({ text: contextPrompt });
    }
    // ۲. ریپلای روی عکس (با قابلیت هاستینگ زنده + امکان ویرایش توسط ایجنت)
    else if (reply.photo && reply.photo.length > 0) {
      const photoFileId = reply.photo[reply.photo.length - 1].file_id;
      try {
        const fileUrl = await getFileUrl(photoFileId);
        const fileRes = await fetchWithTimeout(fileUrl, {}, 25_000);
        const arrayBuf = await fileRes.arrayBuffer();
        const b64 = arrayBufferToBase64(arrayBuf);
        pendingImageBytes = arrayBuf;

        // The image itself has to travel with the request. This base64 was
        // computed and then dropped, while the text below claimed "the replied
        // image is attached to this message" — so the model was reasoning about
        // an image it had never been shown, which is why replying to a photo
        // with "ادیتش کن" wandered off into text or a fresh generation. Every
        // other media branch pushes `inline_data`; the photo branch now does too.
        parts.push({ inline_data: { mime_type: "image/jpeg", data: b64 } });
        recordRecentMedia(msg.chat.id, { fileId: photoFileId, type: "photo", ts: Date.now() });

// Photo reply: always push REPLY_CONTEXT with image context for edit/describe.
const hasEditIntent = looksLikeImageEdit(userText);
const contextPrompt = lang === "fa"
  ? `[REPLY_CONTEXT — تصویر ریپلای شده]
کاربر ${senderName} روی یک تصویر ریپلای کرده و نوشته:
"${userText}"

تصویر ریپلای شده در پیام فعلی پیوست شده است.
${hasEditIntent ? 'کاربر ظاهراً می‌خواهد این تصویر را ویرایش کند. ابزار "edit_image" را با یک دستور دقیق انگلیسی فراخوانی کن. هرگز "generate_image" را برای این تصویر صدا نزن.' : ''}

قوانین:
- تصویر ریپلای شده بخشی از ورودی فعلی است.
- اگر کاربر عباراتی مثل «این»، «ادیتش کن»، «تغییرش بده» دارد، منظور را از تصویر استخراج کن.
[/REPLY_CONTEXT]`
  : `[REPLY_CONTEXT — replied image]
User ${senderName} replied to an image and wrote:
"${userText}"

The replied image is attached to this message.
${hasEditIntent ? 'The user appears to want to edit this image. Call the "edit_image" tool with a precise English instruction. Never call "generate_image" for this image.' : ''}

Rules:
- The replied image is part of the current input.
- If the user uses references like "this", "edit it", "change it", resolve them from the image.
[/REPLY_CONTEXT]`;

parts.push({ text: contextPrompt });
      } catch (e) {
        logger.error("Failed to fetch replied photo", e);
        parts.push({ text: `[کاربر ${senderName} روی یک تصویر ریپلای کرده اما دریافت آن ناموفق بود.]\n\nپیام کاربر: ${userText}` });
      }
    }
    else if (reply.voice) {
      try {
        // ۱. دریافت آدرس و دانلود فایل صوتی از سرور تلگرام
        const fileUrl = await getFileUrl(reply.voice.file_id);
        const fileRes = await fetchWithTimeout(fileUrl, {}, 25_000);
        const arrayBuf = await fileRes.arrayBuffer();
        
        // ۲. ذخیره ویس ریپلای شده در دیتابیس جهت هاست و دسترسی وب‌اپلیکیشن
        const voiceId = `voice_${generateId()}`;
        const voicePut = await putMediaBlob(env, voiceId, arrayBuf, "audio/ogg");
        // Hosting is a convenience; transcription below is the part that matters,
        // so an oversized voice note degrades to "no public URL" rather than failing.
        const publicVoiceUrl = voicePut.ok ? `${requestOrigin}/app/${voiceId}.ogg` : "";

        // ۳. تبدیل صوت ویس ریپلای شده به متن (جهت فهم هوش مصنوعی)
        let transcriptText = "";
        try {
          transcriptText = await transcribeVoice(fileUrl);
        } catch {
          transcriptText = "خطا در استخراج متن صوت";
        }

        const contextPrompt = lang === "fa"
          ? `[کاربر ${senderName} به یک پیام صوتی (ویس) از ${replierName} ریپلای کرده است.\n` +
            `🎙️ **متن ویس ریپلای شده:** "${transcriptText}"\n` +
            `🔗 **لینک مستقیم ویس:** ${publicVoiceUrl}\n\n` +
            `شما می‌توانید از این لینک صوتی به طور زنده در کدهای وب‌اپ (مثلاً تگ <audio src="${publicVoiceUrl}">) استفاده کنید یا طبق محتوای آن پاسخ دهید.]\n\nپیام کاربر: ${userText}`
          : `[User ${senderName} replied to a voice note from ${replierName}.\n` +
            `🎙️ **Voice Transcript:** "${transcriptText}"\n` +
            `🔗 **Direct Audio URL:** ${publicVoiceUrl}\n\n` +
            `You can use this direct link in the web app code (e.g. <audio src="${publicVoiceUrl}">) or reply based on its content.]\n\nUser message: ${userText}`;

        parts.push({ text: contextPrompt });
      } catch (e) {
        logger.error("Failed to fetch/process replied voice", e);
        parts.push({ text: `[کاربر ${senderName} روی یک پیام صوتی ریپلای کرده اما پردازش آن ناموفق بود.]\n\nپیام کاربر: ${userText}` });
      }
    } 
else if (reply.audio) {
  try {
    const fileUrl = await getFileUrl(reply.audio.file_id);

    const fileRes = await fetchExternalSafe(
      fileUrl,
      {},
      25_000,
      15 * 1024 * 1024,
    );

    const audioBytes = await readResponseBytesLimited(
      fileRes,
      15 * 1024 * 1024,
    );

    if (audioBytes.byteLength < 100) {
      throw new Error("replied audio is empty");
    }

    const mime =
      reply.audio.mime_type?.startsWith("audio/")
        ? reply.audio.mime_type
        : "audio/mpeg";

    parts.push({
      inline_data: {
        mime_type: mime,
        data: arrayBufferToBase64(
          bytesToArrayBuffer(audioBytes),
        ),
      },
    });

    parts.push({
      text:
        lang === "fa"
          ? `[REPLY_MEDIA_CONTEXT — AUDIO]
کاربر ${senderName} روی فایل صوتی ${replierName} ریپلای کرده است.

فایل صوتی واقعی پیوست شده.
خود صوت را بررسی کن.

پیام کاربر:
"${userText}"`
          : `[REPLY_MEDIA_CONTEXT — AUDIO]
User ${senderName} replied to audio from ${replierName}.

The actual audio is attached.
Analyze the audio itself.

User message:
"${userText}"`,
    });

  } catch (e) {
    logger.error("Failed to fetch replied audio", e);

    parts.push({
      text:
        lang === "fa"
          ? `[REPLY_MEDIA_ERROR] دریافت فایل صوتی موفق نشد.\n\nپیام کاربر: ${userText}`
          : `[REPLY_MEDIA_ERROR] Failed to fetch replied audio.\n\nUser message: ${userText}`,
    });
  }
}
else if (reply.document) {
  const doc = reply.document;
  const mime = String(doc.mime_type ?? "").toLowerCase();
  const fileName = String(doc.file_name ?? "").toLowerCase();

  // Telegram may represent a GIF/video sent as "document" instead of
  // message.animation. Therefore NEVER treat every non-PDF document as
  // an opaque file. Inspect MIME + extension first.

  const isPdf =
    mime === "application/pdf" ||
    fileName.endsWith(".pdf");

  const isVideo =
    mime.startsWith("video/") ||
    /\.(mp4|webm|mov|m4v|mpeg|mpg)$/i.test(fileName);

  const isGif =
    mime === "image/gif" ||
    fileName.endsWith(".gif");

  const isAudio =
    mime.startsWith("audio/") ||
    /\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(fileName);

  const isImage =
    mime.startsWith("image/") &&
    !isGif;

  try {
    const fileUrl = await getFileUrl(doc.file_id);

    const fileRes = await fetchExternalSafe(
      fileUrl,
      {},
      30_000,
      18 * 1024 * 1024,
    );

    const fileBytes = await readResponseBytesLimited(
      fileRes,
      18 * 1024 * 1024,
    );

    if (fileBytes.byteLength < 100) {
      throw new Error("replied document is empty or too small");
    }

    const b64 = arrayBufferToBase64(
      bytesToArrayBuffer(fileBytes),
    );

    // ------------------------------------------------------------
    // PDF
    // ------------------------------------------------------------
    if (isPdf) {
      parts.push({
        inline_data: {
          mime_type: "application/pdf",
          data: b64,
        },
      });

      parts.push({
        text:
          lang === "fa"
            ? `[REPLY_MEDIA_CONTEXT — PDF]
کاربر ${senderName} روی یک سند PDF از ${replierName} ریپلای کرده است.

فایل PDF واقعی پیوست شده است.
محتوای واقعی سند را بخوان و پاسخ بده.
از نام فایل برای حدس زدن محتوا استفاده نکن.

پیام کاربر:
"${userText}"`
            : `[REPLY_MEDIA_CONTEXT — PDF]
User ${senderName} replied to a PDF from ${replierName}.

The real PDF file is attached.
Read the actual document contents and answer from them.
Do not infer anything from the filename.

User message:
"${userText}"`,
      });

    // ------------------------------------------------------------
    // VIDEO / GIF-AS-DOCUMENT
    // ------------------------------------------------------------
    } else if (isVideo || isGif) {

      let videoMime = "video/mp4";

      if (mime === "video/webm" || fileName.endsWith(".webm")) {
        videoMime = "video/webm";
      } else if (
        mime === "video/quicktime" ||
        fileName.endsWith(".mov")
      ) {
        videoMime = "video/quicktime";
      } else if (
        mime === "video/mp4" ||
        fileName.endsWith(".mp4") ||
        fileName.endsWith(".m4v")
      ) {
        videoMime = "video/mp4";
      }

      // For GIF documents Telegram may expose image/gif.
      // We intentionally use a representative visual payload when possible,
      // but if it is actually an MP4-backed GIF, send it as video.
      const effectiveMime =
        isGif && mime === "image/gif"
          ? "image/gif"
          : videoMime;

      parts.push({
        inline_data: {
          mime_type: effectiveMime,
          data: b64,
        },
      });

      parts.push({
        text:
          lang === "fa"
            ? `[REPLY_MEDIA_CONTEXT — GIF/VIDEO]
کاربر ${senderName} روی یک رسانه متحرک از ${replierName} ریپلای کرده است.

رسانه واقعی به‌صورت binary به‌عنوان ورودی پیوست شده است.
خود محتوای بصری/ویدیویی را بررسی کن.

قوانین بسیار مهم:
- هرگز از نام فایل، file_id، پسوند فایل یا placeholderهایی مثل "[GIF]" محتوا را حدس نزن.
- ادعا نکن فایل به دستت نرسیده، مگر واقعاً هیچ payloadای در این درخواست وجود نداشته باشد.
- اگر محتوای قابل مشاهده است، بر اساس همان محتوا توضیح بده.
- اگر چیزی از رسانه قابل تشخیص نیست، فقط همان بخش را صریحاً نامشخص اعلام کن.

نوع رسانه:
${isGif ? "GIF" : "VIDEO"}

نام فایل فقط برای metadata:
${fileName || "unknown"}

پیام کاربر:
"${userText}"`
            : `[REPLY_MEDIA_CONTEXT — GIF/VIDEO]
User ${senderName} replied to an animated media item from ${replierName}.

The real binary media is attached as input.
Analyze the actual visual/video content.

Critical rules:
- NEVER infer content from filename, file_id, extension, or placeholders such as "[GIF]".
- NEVER claim the file was not received when a binary payload is present.
- Describe only what is supported by the actual media.
- If something is genuinely not visible/determinable, say so explicitly.

Media type:
${isGif ? "GIF" : "VIDEO"}

Filename metadata only:
${fileName || "unknown"}

User message:
"${userText}"`,
      });

    // ------------------------------------------------------------
    // AUDIO
    // ------------------------------------------------------------
    } else if (isAudio) {

      const audioMime =
        mime.startsWith("audio/")
          ? mime
          : /\.(mp3)$/i.test(fileName)
            ? "audio/mpeg"
            : "audio/ogg";

      parts.push({
        inline_data: {
          mime_type: audioMime,
          data: b64,
        },
      });

      parts.push({
        text:
          lang === "fa"
            ? `[REPLY_MEDIA_CONTEXT — AUDIO]
کاربر ${senderName} روی یک فایل صوتی از ${replierName} ریپلای کرده است.

خود فایل صوتی واقعی پیوست شده.
در صورت امکان محتوای صوت، گفتار و صداهای قابل تشخیص را بررسی کن.

پیام کاربر:
"${userText}"`
            : `[REPLY_MEDIA_CONTEXT — AUDIO]
User ${senderName} replied to an audio file from ${replierName}.

The actual audio file is attached.
Analyze speech and other audible content when possible.

User message:
"${userText}"`,
      });

    // ------------------------------------------------------------
    // IMAGE
    // ------------------------------------------------------------
    } else if (isImage) {

      const imageMime =
        mime === "image/png"
          ? "image/png"
          : mime === "image/webp"
            ? "image/webp"
            : mime === "image/jpeg"
              ? "image/jpeg"
              : "image/jpeg";

      parts.push({
        inline_data: {
          mime_type: imageMime,
          data: b64,
        },
      });

      parts.push({
        text:
          lang === "fa"
            ? `[REPLY_MEDIA_CONTEXT — IMAGE]
کاربر ${senderName} روی یک تصویر از ${replierName} ریپلای کرده است.

تصویر واقعی پیوست شده.
خود تصویر را بررسی کن و فقط بر اساس محتوای واقعی آن پاسخ بده.

پیام کاربر:
"${userText}"`
            : `[REPLY_MEDIA_CONTEXT — IMAGE]
User ${senderName} replied to an image from ${replierName}.

The actual image is attached.
Analyze the image itself and answer from its real contents.

User message:
"${userText}"`,
      });

    // ------------------------------------------------------------
    // UNKNOWN DOCUMENT
    // ------------------------------------------------------------
    } else {

      // Even for an unknown document, attach the actual binary instead
      // of sending only the filename to Gemini.
      parts.push({
        inline_data: {
          mime_type:
            mime ||
            "application/octet-stream",
          data: b64,
        },
      });

      parts.push({
        text:
          lang === "fa"
            ? `[REPLY_MEDIA_CONTEXT — DOCUMENT]
کاربر ${senderName} روی یک فایل از ${replierName} ریپلای کرده است.

فایل واقعی پیوست شده است.
اگر این نوع فایل قابل خواندن/تحلیل است، محتوای واقعی آن را بررسی کن.
هرگز از نام فایل به‌تنهایی برای حدس زدن محتوا استفاده نکن.

نام فایل:
"${doc.file_name ?? "نامشخص"}"

پیام کاربر:
"${userText}"`
            : `[REPLY_MEDIA_CONTEXT — DOCUMENT]
User ${senderName} replied to a file from ${replierName}.

The actual file is attached.
Analyze its real contents if supported.
Never infer its contents from the filename alone.

Filename:
"${doc.file_name ?? "unknown"}"

User message:
"${userText}"`,
      });
    }

    logger.info(
      `[reply-media] document resolved: ` +
      `mime=${mime || "unknown"} ` +
      `name=${fileName || "unknown"} ` +
      `bytes=${fileBytes.byteLength} ` +
      `type=${
        isPdf ? "pdf" :
        isVideo ? "video" :
        isGif ? "gif" :
        isAudio ? "audio" :
        isImage ? "image" :
        "document"
      }`,
    );

  } catch (e) {

    logger.error(
      "Failed to fetch/process replied document media",
      e,
    );

    parts.push({
      text:
        lang === "fa"
          ? `[REPLY_MEDIA_ERROR]
کاربر ${senderName} روی یک فایل ریپلای کرده است، اما دریافت باینری فایل با خطا مواجه شد.

هرگز از نام فایل حدس نزن.
پیام کاربر:
"${userText}"`
          : `[REPLY_MEDIA_ERROR]
User ${senderName} replied to a file, but fetching its binary failed.

Never infer the file contents from its filename.
User message:
"${userText}"`,
    });
  }
}
else if (reply.animation) {
  try {
    const animation = reply.animation;
    const prompt = lang === "fa"
      ? `[REPLY_MEDIA_CONTEXT — GIF/ANIMATION]
کاربر ${senderName} روی یک GIF/انیمیشن از ${replierName} ریپلای کرده و نوشته:
"${userText}"

این پیام واقعاً به یک GIF/انیمیشن پیوست شده است.
محتوای رسانه را از داده‌ی تصویری/ویدیویی پیوست‌شده بررسی کن.
هرگز درباره‌ی محتوای GIF از روی نام فایل، شناسه فایل، پسوند فایل یا متن‌هایی مثل "[GIF]" حدس نزن.
اگر فریم نماینده/thumbnail پیوست شده، حتماً آن را به‌عنوان شاهد بصری بررسی کن.
اگر فایل متحرک قابل تحلیل بود، حرکت و رویدادهای قابل مشاهده را نیز بررسی کن.
اگر چیزی واقعاً قابل تشخیص نیست، همان را صریح بگو.

پیام فعلی کاربر:
"${userText}"`
      : `[REPLY_MEDIA_CONTEXT — GIF/ANIMATION]
User ${senderName} replied to a GIF/animation from ${replierName} saying:
"${userText}"

This message genuinely contains an attached GIF/animation.
Analyze the attached visual/video data itself.
NEVER infer the GIF's content from its filename, file ID, extension, or placeholders such as "[GIF]".
If a representative thumbnail/frame is attached, inspect it as visual evidence.
If the animated file is analyzable, also inspect the visible motion/events.
If something cannot actually be determined, say so explicitly.

Current user message:
"${userText}"`;

    let attached = false;

    // ------------------------------------------------------------
    // 1) اول thumbnail واقعی را بفرست.
    // این مهم‌ترین fallback است چون بعضی مدل/فرمت‌ها ممکن است
    // فایل animation خام را به‌صورت بصری پردازش نکنند.
    // ------------------------------------------------------------
    const thumb = animation.thumbnail;

    if (thumb?.file_id) {
      try {
        const thumbUrl = await getFileUrl(thumb.file_id);
        const thumbRes = await fetchExternalSafe(
          thumbUrl,
          {},
          10_000,
          5 * 1024 * 1024,
        );

        const thumbBytes = await readResponseBytesLimited(
          thumbRes,
          5 * 1024 * 1024,
        );

        if (thumbBytes.byteLength >= 100) {
          parts.push({
            inline_data: {
              mime_type: "image/jpeg",
              data: arrayBufferToBase64(bytesToArrayBuffer(thumbBytes)),
            },
          });

          attached = true;
        }
      } catch (thumbErr) {
        logger.warn(
          `Failed to fetch replied GIF thumbnail: ${
            thumbErr instanceof Error ? thumbErr.message : String(thumbErr)
          }`,
        );
      }
    }

    // ------------------------------------------------------------
    // 2) سپس خود فایل Animation را هم بده.
    // MP4/WebM را به‌عنوان video بفرست.
    // GIF خام را مستقیماً به Gemini تحمیل نکن؛ چون ممکن است
    // در بعضی مسیرها به‌صورت visual input معتبر تفسیر نشود.
    // ------------------------------------------------------------
    try {
      const fileUrl = await getFileUrl(animation.file_id);

      const fileRes = await fetchExternalSafe(
        fileUrl,
        {},
        25_000,
        18 * 1024 * 1024,
      );

      const fileBytes = await readResponseBytesLimited(
        fileRes,
        18 * 1024 * 1024,
      );

      if (fileBytes.byteLength >= 100) {
        const rawMime = String(animation.mime_type || "").toLowerCase();

        // فقط MIMEهای ویدیویی معتبر را به مدل می‌دهیم.
        // برای GIF خام، thumbnail کافی است و از ارسال image/gif
        // که در بعضی مسیرها ممکن است unsupported شود جلوگیری می‌کنیم.
        let videoMime = "";

        if (rawMime === "video/mp4") {
          videoMime = "video/mp4";
        } else if (rawMime === "video/webm") {
          videoMime = "video/webm";
        } else if (rawMime === "video/quicktime") {
          videoMime = "video/quicktime";
        } else {
          // اگر Telegram MIME درست گزارش نکرد، از file path کمک بگیر.
          const lowerUrl = fileUrl.toLowerCase();

          if (
            lowerUrl.includes(".mp4") ||
            rawMime.includes("mp4")
          ) {
            videoMime = "video/mp4";
          } else if (
            lowerUrl.includes(".webm") ||
            rawMime.includes("webm")
          ) {
            videoMime = "video/webm";
          }
        }

        if (videoMime) {
          parts.push({
            inline_data: {
              mime_type: videoMime,
              data: arrayBufferToBase64(bytesToArrayBuffer(fileBytes)),
            },
          });

          attached = true;
        }
      }
    } catch (fileErr) {
      logger.warn(
        `Failed to fetch replied GIF binary: ${
          fileErr instanceof Error ? fileErr.message : String(fileErr)
        }`,
      );
    }

    // ------------------------------------------------------------
    // 3) اگر هیچ باینری‌ای قابل دریافت نبود، مدل نباید شروع به
    // حدس‌زدن از روی filename کند.
    // ------------------------------------------------------------
    if (!attached) {
      logger.warn(
        `Replied GIF had no readable visual payload. file_id=${animation.file_id}`,
      );
    }

    parts.push({
      text:
        prompt +
        (
          attached
            ? `\n\n[رسانه واقعی GIF/Animation به‌عنوان ورودی همین پیام پیوست شده است. فقط از همان ورودی بصری نتیجه‌گیری کن.]`
            : `\n\n[هشدار: محتوای باینری GIF در این درخواست قابل دریافت نشد. درباره محتوای GIF یا نام فایل حدس نزن.]`
        ),
    });
  } catch (e) {
    logger.error("Failed to fetch replied animation", e);

    parts.push({
      text:
        lang === "fa"
          ? `[کاربر ${senderName} روی یک GIF/انیمیشن ریپلای کرده است، اما دریافت رسانه موفق نشد. درباره محتوای آن از روی نام فایل یا "[GIF]" حدس نزن.\n\nپیام کاربر: ${userText}]`
          : `[User ${senderName} replied to a GIF/animation, but fetching the media failed. Do not infer its content from the filename or "[GIF]".\n\nUser message: ${userText}]`,
    });
  }
}
    else if (reply.video) {
      try {
        const fileUrl = await getFileUrl(reply.video.file_id);
        const fileRes = await fetchWithTimeout(fileUrl, {}, 28_000);
        const arrayBuf = await fileRes.arrayBuffer();
        if (arrayBuf.byteLength > 18 * 1024 * 1024) {
          parts.push({ text: lang === "fa"
            ? `[کاربر ${senderName} روی یک ویدیوی حجیم ریپلای کرده؛ برای تحلیل کامل خیلی بزرگ است.]\n\nپیام کاربر: ${userText}`
            : `[User ${senderName} replied to a large video; too big to analyze in full.]\n\nUser message: ${userText}` });
        } else {
          const b64 = arrayBufferToBase64(arrayBuf);
          const mime = reply.video.mime_type || "video/mp4";
          const contextPrompt = lang === "fa"
            ? `[کاربر ${senderName} به یک ویدیو از ${replierName} ریپلای کرده و نوشته: "${userText}". محتوای ویدیو پیوست شده؛ آن را ببین و بر اساسش پاسخ بده.]`
            : `[User ${senderName} replied to a video from ${replierName} saying: "${userText}". The video content is attached; view it and respond accordingly.]`;
          parts.push({ inline_data: { mime_type: mime, data: b64 } });
          parts.push({ text: contextPrompt });
        }
      } catch (e) {
        logger.error("Failed to fetch replied video", e);
        parts.push({ text: `[کاربر ${senderName} روی یک ویدیو ریپلای کرده اما دریافت آن ناموفق بود.]\n\nپیام کاربر: ${userText}` });
      }
    }
    else {
      const mediaType = reply.voice ? "ویس" : reply.video ? "ویدیو" : reply.animation ? "گیف" : "رسانه";
      parts.push({ text: `[کاربر ${senderName} روی یک پیام از نوع ${mediaType} ریپلای کرده است.]\n\nپیام کاربر: ${userText}` });
    }
  } else {
    parts.push({ text: prefix + sanitizeInput(userText) });
  }
  return { parts, pendingImageBytes };
}
// SECTION: MESSAGE HANDLERS
/** What an inline result stores for its "Run in private chat" deep link. */
interface InlineHandoff {
  prompt: string;
  kind: InlineKind;
  lang?: string;
  userId: number;
  ts?: number;
}

async function handleTextMessage(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  let { text } = msg;
  if (!text || !from) return;

  if (chat.type !== "private") saveGroupInfo(chat, env).catch(() => {});
  const reqId = generateId();
  const reqStart = Date.now();
  let reqFailed = false;
  let reqError: string | undefined;

  try {
    const [mc, session] = await Promise.all([
      checkMaintenance(env, from.id),
      getOrCreateSession(chat, from, env),
    ]);
    if (mc.blocked) { await sendMessage(chat.id, mc.message!, { reply_to_message_id: msg.message_id }); return; }

    // ── Group activation gate: disabled groups are completely silent. /start is the only exception.
    if (chat.type !== "private" && !await isGroupEnabled(chat.id, chat.type, env)) {
      const commandProbe = (text.trim().split(/\s+/)[0] ?? "").toLowerCase().split("@")[0];
      if (!["/start","/settings"].includes(commandProbe)||!await isUserAdmin(from.id,chat.id)) return;
    }

    const isGroup = chat.type !== "private";
    const lang = session.language;
    
    if (isGroup) {
      // A chat-scoped block means Nova ignores this person here. It used to
      // mean `deleteMessage`, so "block them" silently turned into a message
      // shredder — destructive, needs admin rights it may not have, and not
      // remotely what was asked. Ignoring is the honest implementation;
      // deleting a message is its own explicit action (`delete_message`).
      const banData = await readChatBan(chat.id, from.id, env);
      if (banData?.until && banData.until > Date.now()) return;

      // 🧠 هوش جمعی: ثبت حضور و پیام کاربر در حافظه گروه، حتی اگر نوا را صدا نزده باشد
      touchGroupMember(session, from);
      const groupCtx = groupContextCache.get(chat.id) ?? { messages: [], lastCleanup: Date.now() };
      groupCtx.messages.push({
        messageId: msg.message_id,
        userId: from.id,
        userName: from.first_name,
        text: text.slice(0, 300),
        timestamp: Date.now()
      });
      if (groupCtx.messages.length > 25) groupCtx.messages.shift();
      groupContextCache.set(chat.id, groupCtx);
    }

    if (isGroup && !text.startsWith("/") && !shouldRespondInGroup(msg, session)) return;

    if (await isUserBlocked(session, from, env)) {
      if (!isGroup) {
        const blk = getBlockedMessage(session.language);
        await sendMessage(chat.id, blk.text, { reply_to_message_id: msg.message_id, reply_markup: JSON.stringify(blk.keyboard) });
      }
      return;
    }

    // ── Inline handoff (`https://t.me/<bot>?start=ih<token>`) ────────────────
    // Expanding the payload HERE — before routing, inside the normal turn — is
    // what keeps inline mode from growing a second brain: the recovered request
    // continues as an ordinary message, so the router, daily limits, progress
    // panel, cancel button and memory rules all apply unchanged.
    //
    // The token is single-use and bound to the user who created the inline
    // result: a link forwarded into another chat cannot be redeemed by somebody
    // else, and a refusal never reveals what the original request was.
    const startPayload = text.match(/^\/start(?:@\w+)?\s+(\S+)\s*$/);
    if (startPayload) {
      const token = parseInlinePayload(startPayload[1]);
      if (token) {
        const raw = await env.SESSIONS.get(`inline_handoff:${token}`, "text").catch(() => null);
        let recovered: InlineHandoff | null = null;
        try { recovered = raw ? JSON.parse(raw) as InlineHandoff : null; } catch { recovered = null; }
        const rtl = looksRtlScript(text) || (recovered?.lang ?? session.language) === "fa";
        if (!recovered?.prompt || Number(recovered.userId) !== Number(from.id)) {
          await sendMessage(chat.id, rtl
            ? "این لینک منقضی شده یا برای تو صادر نشده. درخواستت را همین‌جا بنویس تا انجامش دهم."
            : "That link has expired, or was not issued for you. Just write your request here and I'll run it.",
            { reply_to_message_id: msg.message_id });
          return;
        }
        // Single use: replaying the link must not replay a premium operation.
        await env.SESSIONS.delete(`inline_handoff:${token}`).catch(() => {});
        text = handoffRequestText(recovered.kind ?? "image", recovered.prompt, recovered.lang ?? session.language);
        msg = { ...msg, text };
        logger.info(`[inline] handoff redeemed kind=${recovered.kind} user=${from.id}`);
      } else if (startPayload[1] === "mydash") {
        // Discovery deep link from the dashboard entry button (groups and
        // keyboards rendered before an origin was known). It carries no token
        // and no payload — anyone landing here reaches only their own panel.
        await handleDashboardDeepLink(msg, env);
        return;
      }
    }

    // ── Deterministic intent routing ──────────────────────────────────────
    // One classifier decides what this message is *for*, before any model call
    // and before any of the specialised fast paths below. Everything
    // downstream — the persona gate, the rename fast path, the tool whitelist
    // and the routing directive in the system prompt — reads this single
    // decision, so an explicit command ("بلاکش کن") can no longer be
    // reinterpreted as a topical lookup by whichever subsystem saw it first.
    let routing: IntentDecision | undefined;
    if (!text.startsWith("/")) {
      let senderIsChatAdmin = from.id === cfg.BOT_OWNER_ID;
      if (isGroup && !senderIsChatAdmin && mayNeedPermissions(text)) {
        senderIsChatAdmin = await isUserAdminCached(from.id, chat.id);
      }
      const reply = msg.reply_to_message;
      const selfId = BOT_SELF_ID ?? BOT_INFO?.id;
      routing = classifyRequestIntent({
        text,
        isGroup,
        isReply: Boolean(reply),
        repliedUserId: reply?.from?.id ?? null,
        repliedUserName: reply?.from?.first_name ?? null,
        repliedToSelf: Boolean(selfId && reply?.from?.id === selfId),
        repliedHasImage: Boolean(reply?.photo?.length) ||
          Boolean(reply?.document?.mime_type?.startsWith("image/")),
        repliedHasMedia: Boolean(reply && (reply.video || reply.animation || reply.voice ||
          reply.audio || reply.document || reply.sticker)),
        hasAttachedImage: Boolean(msg.photo?.length),
        hasRecentImage: Boolean(getRecentPhoto(chat.id)),
        isOwner: from.id === cfg.BOT_OWNER_ID,
        isChatAdmin: senderIsChatAdmin,
        selfNames: novaSelfNames(session, from.id, isGroup),
        personaAliases: PERSONA_ALIASES,
        activePersonaId: getEffectivePersonaId(session, from.id, isGroup),
      });
      logger.info(`[intent] ${describeRoutingIntent(routing)}`);

      // A rename is applied here, deterministically, and never left to the
      // model: "اسم نوا رو بذار سحر" must take effect on this very message.
      if (routing.category === "name_switch" && routing.slots.newName !== undefined) {
        if (await applyCallNameChange(session, from, chat.id, isGroup, msg.message_id, routing.slots.newName, env)) return;
      }
    }

    // درخواست‌های مربوط به شخصیت پیش از فراخوانی مدل پاسخ داده می‌شوند (سریع و
    // بدون رفت‌وبرگشت به Gemini)، اما هیچ وضعیتی اینجا تغییر نمی‌کند: تعویض واقعی
    // فقط با تأیید صریح کاربر روی کارت شخصیت انجام می‌شود.
    //
    // Gated on the router now. Calling Nova by name is NOT a request to
    // reconfigure her: "نوا؟" / "نوا بیا" / "نوا اینو ببین" used to reach this
    // fast path (because "نوا" is also an alias of the default persona) and
    // burned the whole turn on a persona card instead of answering. Only an
    // actual persona intent gets in.
    if (await handlePersonaIntentMessage(session, from, text, chat.id, isGroup, msg.message_id, routing)) return;

    // Handle pending broadcast input from owner
    const broadcastState = broadcastStates.get(chat.id);
    if (broadcastState && from.id === cfg.BOT_OWNER_ID && !text.startsWith("/")) {
      await handleBroadcastMessage(msg, broadcastState, env);
      return;
    }

    if (from.id === cfg.BOT_OWNER_ID && !text.startsWith("/")) {
      const naturalConfigChanges = parseNaturalConfigChanges(text);
      if (naturalConfigChanges.length > 0) {
        const applied = await applyBotConfigChanges(naturalConfigChanges, env);
        if (applied.length > 0) {
          await sendMessage(chat.id, formatConfigChangeSummary(applied, lang), { reply_to_message_id: msg.message_id });
          return;
        }
      }
    }

    // Commands
    if (text.startsWith("/")) {
      const parts = text.split(" ");
      const rawCmd = parts[0].toLowerCase();
      const command = rawCmd.split("@")[0];
      const mention = rawCmd.includes("@") ? rawCmd.split("@")[1] : null;
      if (mention && BOT_INFO?.username && mention !== BOT_INFO.username.toLowerCase()) return;
      const args = parts.slice(1);

      const requireAdmin = async () => {
        if (!isGroup) return true;
        if (await isBotOwnerOrGroupCreator(from.id, chat.id)) return true;
        await sendMessage(chat.id, "🚫 فقط مالک ربات یا مالک گروه مجاز به اجرای این دستور است", { reply_to_message_id: msg.message_id });
        return false;
      };

      if (text === "/cancel" && broadcastStates.has(chat.id)) {
        broadcastStates.delete(chat.id);
        await sendMessage(chat.id, "✅ عملیات لغو شد.", { reply_to_message_id: msg.message_id });
        return;
      }

      switch (command) {
        case "/start": await handleStart(msg, env); break;
        case "/donate": {
          const donate = buildDonateMessage(session.language);
          await sendMessage(chat.id, donate.text, { reply_to_message_id: msg.message_id, parse_mode: "HTML" });
          break;
        }
        case "/new":
          await handleNew(msg, env);
          break;
        case "/img": await handleImg(msg, args, env); break;
        case "/findimg": await handleSearch(msg, args, env); break;
        case "/deepsearch":
        case "/deep": await handleSuperSearch(msg, args, env); break;
        case "/language":
          await sendMessage(chat.id,
            `🌐 *Language / انتخاب زبان*\n\nCurrent: **${session.language === "fa" ? "فارسی 🇮🇷" : session.language === "ar" ? "العربية 🇸🇦" : "English 🇺🇸"}**`,
            {
              reply_to_message_id: msg.message_id,
              reply_markup: JSON.stringify({ inline_keyboard: [
                [btn("🇮🇷  فارسی", "set_lang_fa"), btn("🇺🇸  English", "set_lang_en")],
                [btn("🇸🇦  العربية", "set_lang_ar")],
                [userDashboardButton(session.language, chat.type === "private")],
                [btn("🔙", "home:open")],
              ]}),
            }
          );
          break;
        case "/webapps":
        case "/apps":
          // Owner-facing web-app management is a dashboard tab now; /myapps below
          // still lists a user's own apps in-chat.
          if (from.id === cfg.BOT_OWNER_ID) {
            await sendAdminPanel(chat.id, chat.type, from.id, { tab: "deployments", replyTo: msg.message_id });
          }
          break;
        case "/myapps":
          await handleMyApps(msg, env);
          break;
        case "/assets": await handleMyAssets(msg, env); break;
        case "/get": await handleGetAsset(msg, args, env); break;
        case "/pdf": await handlePdfCommand(msg, args, env); break;
        case "/tr": await handleTranslate(msg, args, env); break;
        case "/tts": await handleTTS(msg, args, env); break;
        case "/ocr": await handleOCR(msg, env); break;
        case "/read": await handleReadURL(msg, args, env); break;
        case "/summarize": await handleSummarizeGroup(msg, env); break;
        case "/remember": await handleRemember(msg, args, env); break;
        case "/mymemory": await handleMyMemory(msg, env); break;
        case "/forget": await handleForgetMemory(msg, env); break;
        case "/stats": await handleStatsMe(msg, env); break;
        case "/dashboard":
        case "/my":
          // Discoverability: /my is the dashboard's own route; /dashboard reads
          // naturally in the help text. Both send the Mini App entry card in the
          // DM, and the group path politely redirects (web_app buttons are
          // private-only — putting one in a group keyboard would be rejected).
          if (isGroup) await sendMessage(chat.id, session.language === "fa"
            ? "🚀 داشبورد در پیوی در دسترسه — همین‌جا پیام بده تا لینکش رو بفرستم."
            : "🚀 The dashboard lives in the private chat — message me there and I'll send the link.",
            { reply_to_message_id: msg.message_id });
          else await handleDashboardDeepLink(msg, env);
          break;
        case "/id": await handleIdInfo(msg, args, env); break;
        case "/now": await handleNow(msg); break;
        case "/mood": await handleFunCommand(msg, "mood", args.join(" "), env); break;
        case "/joke": await handleFunCommand(msg, "joke", args.join(" "), env); break;
        case "/idea": await handleFunCommand(msg, "idea", args.join(" "), env); break;
        case "/plan": await handleFunCommand(msg, "plan", args.join(" "), env); break;
        case "/quote": await handleFunCommand(msg, "quote", args.join(" "), env); break;
        case "/help": await handleHelp(msg, env); break;
        case "/prompt": await handlePrompt(msg, env); break;
        case "/setprompt": await handleSetPrompt(msg, args, env); break;
        case "/showprompt":
          if (from.id === cfg.BOT_OWNER_ID) {
            await sendMessage(chat.id, cfg.SYSTEM_PROMPT
              ? `📋 **سیستم پرامپت سراسری فعلی:**\n\n\`\`\`\n${cfg.SYSTEM_PROMPT.slice(0, 3500)}\n\`\`\``
              : "📋 سیستم پرامپت سراسری تنظیم نشده — پیش‌فرض نوا استفاده می‌شود.",
              { reply_to_message_id: msg.message_id });
          }
          break;
        case "/admin":
          if (from.id === cfg.BOT_OWNER_ID) await handleAdmin(msg, env);
          break;

        case "/log":
          if (from.id === cfg.BOT_OWNER_ID) await handleLog(msg);
          break;
        case "/keys":
          if (from.id === cfg.BOT_OWNER_ID) await handleKeys(msg, env);
          break;
        case "/unlockkeys":
          if (from.id === cfg.BOT_OWNER_ID) {
          globalDisabledKeys = {};
            await env.SESSIONS.put("disabled_api_keys", "{}");
            await sendMessage(chat.id, "✅ تمام قفل‌های کلید API ریست شد.", { reply_to_message_id: msg.message_id });
          }
          break;
        case "/rebuild":
          if (from.id === cfg.BOT_OWNER_ID) await handleRebuild(msg, env);
          break;
        case "/seedstickers":
          if (from.id === cfg.BOT_OWNER_ID) {
            const r = await seedStickerLibrary(env);
            await sendMessage(chat.id, `✅ ${r.sets} پک بررسی شد، ${r.stickers} استیکر به کتابخانه اضافه شد.`, { reply_to_message_id: msg.message_id });
          }
          break;

        case "/bizmode":
          if (from.id === cfg.BOT_OWNER_ID) {
            const sub = (args[0] ?? "").toLowerCase();
            if (sub === "on" || sub === "off") {
              await setBusinessModeEnabled(sub === "on", env);
              await sendMessage(chat.id, sub === "on"
                ? "✅ پاسخ‌دهی خودکار Business برای همه (مالک + VIP) فعال شد."
                : "⛔️ پاسخ‌دهی خودکار Business برای همه غیرفعال شد.", { reply_to_message_id: msg.message_id });
            } else {
              const enabled = await getBusinessModeEnabled(env);
              await sendMessage(chat.id, `⚙️ وضعیت فعلی: ${enabled ? "فعال ✅" : "غیرفعال ❌"}\n\nاستفاده: \`/bizmode on\` یا \`/bizmode off\``, { reply_to_message_id: msg.message_id });
            }
          }
          break;

        case "/bizprompt": {
          if (!(await isAuthorizedForBusiness(from.id, env))) {
            await sendMessage(chat.id, "🚫 این قابلیت فقط برای مالک ربات و کاربران VIP فعاله.", { reply_to_message_id: msg.message_id });
            break;
          }
          const bizRecord = await getMyBusinessConnection(from.id, env);
          if (!bizRecord) {
            await sendMessage(chat.id, "❌ هنوز هیچ اکانتی از تنظیمات Chat Automation به این ربات وصل نکردی.", { reply_to_message_id: msg.message_id });
            break;
          }
          const bizRest = args.join(" ").trim();
          if (!bizRest) {
            const preview = bizRecord.defaultPrompt
              ? `\`${bizRecord.defaultPrompt.slice(0, 500)}\``
              : "_تنظیم نشده — از پرامپت پیش‌فرض عمومی استفاده می‌شه._";
            await sendMessage(chat.id, `✏️ **پرامپت پیش‌فرض Business شما:**\n\n${preview}\n\nبرای تغییر: \`/bizprompt متن جدید\`\nبرای ریست: \`/bizprompt reset\``, { reply_to_message_id: msg.message_id });
          } else if (bizRest.toLowerCase() === "reset") {
            bizRecord.defaultPrompt = "";
            await saveBusinessConnection(bizRecord, env);
            await sendMessage(chat.id, "✅ پرامپت پیش‌فرض ریست شد.", { reply_to_message_id: msg.message_id });
          } else {
            bizRecord.defaultPrompt = bizRest.slice(0, 4000);
            await saveBusinessConnection(bizRecord, env);
            await sendMessage(chat.id, "✅ پرامپت پیش‌فرض Business ذخیره شد.", { reply_to_message_id: msg.message_id });
          }
          break;
        }

        case "/bizcustomerprompt": {
          if (!(await isAuthorizedForBusiness(from.id, env))) {
            await sendMessage(chat.id, "🚫 این قابلیت فقط برای مالک ربات و کاربران VIP فعاله.", { reply_to_message_id: msg.message_id });
            break;
          }
          const bizRecord2 = await getMyBusinessConnection(from.id, env);
          if (!bizRecord2) {
            await sendMessage(chat.id, "❌ هنوز هیچ اکانتی به این ربات وصل نکردی.", { reply_to_message_id: msg.message_id });
            break;
          }
          const custId = args[0];
          const custRest = args.slice(1).join(" ").trim();
          if (!custId || !/^\d+$/.test(custId)) {
            await sendMessage(chat.id, "استفاده: `/bizcustomerprompt [شناسه عددی مشتری] متن`\nبرای ریست: `/bizcustomerprompt [شناسه] reset`", { reply_to_message_id: msg.message_id });
            break;
          }
          if (!custRest || custRest.toLowerCase() === "reset") {
            delete bizRecord2.customerPrompts[custId];
            await saveBusinessConnection(bizRecord2, env);
            await sendMessage(chat.id, `✅ پرامپت اختصاصی مشتری \`${custId}\` پاک شد.`, { reply_to_message_id: msg.message_id });
          } else {
            bizRecord2.customerPrompts[custId] = custRest.slice(0, 4000);
            await saveBusinessConnection(bizRecord2, env);
            await sendMessage(chat.id, `✅ پرامپت اختصاصی برای مشتری \`${custId}\` ذخیره شد.`, { reply_to_message_id: msg.message_id });
          }
          break;
        }

        case "/bizstatus": {
          if (!(await isAuthorizedForBusiness(from.id, env))) {
            await sendMessage(chat.id, "🚫 این قابلیت فقط برای مالک ربات و کاربران VIP فعاله.", { reply_to_message_id: msg.message_id });
            break;
          }
          const bizRecord3 = await getMyBusinessConnection(from.id, env);
          const globalOn = await getBusinessModeEnabled(env);
          if (!bizRecord3) {
            await sendMessage(chat.id, `❌ اتصالی پیدا نشد.\n\n⚙️ وضعیت کلی سیستم: ${globalOn ? "فعال ✅" : "غیرفعال ❌"}`, { reply_to_message_id: msg.message_id });
            break;
          }
          const custCount = Object.keys(bizRecord3.customerPrompts).length;
          await sendMessage(chat.id,
            `📊 **وضعیت اتصال Business**\n\n` +
            `🆔 Connection: \`${bizRecord3.connectionId}\`\n` +
            `🔌 وضعیت اتصال: ${bizRecord3.isEnabled ? "متصل ✅" : "قطع ❌"}\n` +
            `✍️ اجازه پاسخ: ${bizRecord3.canReply ? "بله ✅" : "خیر ❌"}\n` +
            `⚙️ وضعیت کلی سیستم (سوییچ مالک): ${globalOn ? "فعال ✅" : "غیرفعال ❌"}\n` +
            `✏️ پرامپت پیش‌فرض: ${bizRecord3.defaultPrompt ? "تنظیم شده" : "پیش‌فرض عمومی"}\n` +
            `👤 پرامپت‌های اختصاصی: ${custCount} مشتری`,
            { reply_to_message_id: msg.message_id }
          );
          break;
        }

        case "/bizdebug": {
          if (from.id !== cfg.BOT_OWNER_ID) break;
          const globalOn = await getBusinessModeEnabled(env);
          const bizConnId = await env.SESSIONS.get(`bizowner:${from.id}`);
          const record = bizConnId ? await getBusinessConnection(bizConnId, env) : null;
          
          let debugText = `🔍 **عیب‌یابی سیستم اتوماسیون چت بیزینس:**\n\n` +
            `👤 شناسه شما: \`${from.id}\`\n` +
            `👑 شناسه مالک در ربات: \`${cfg.BOT_OWNER_ID}\`\n` +
            `⚙️ وضعیت فعال بودن ماژول بیزینس: ${globalOn ? "فعال ✅" : "غیرفعال ❌"}\n` +
            `🔌 کلید اتصال شما در دیتابیس: \`${bizConnId ?? "یافت نشد ❌"}\`\n`;
            
          if (record) {
            debugText += `\n📝 **جزئیات اتصال ثبت شده:**\n` +
              `• نام اکانت متصل: \`${record.ownerName}\`\n` +
              `• وضعیت اتصال: \`${record.isEnabled ? "فعال" : "غیرفعال"}\`\n` +
              `• مجوز پاسخ‌دهی تلگرام: \`${record.canReply ? "دارد ✅" : "ندارد ❌"}\`\n`;
          } else {
            debugText += `\n⚠️ **مشکل شناسایی شد:** دیتابیس هنوز کلید اتصال شما را دریافت نکرده است.\n\n` +
              `💡 **راه‌حل رفع آنی:**\n` +
              `۱. یک‌بار ربات را در تنظیمات تلگرام بیزینس حذف و مجدداً وصل کنید.\n` +
              `۲. یا یک پیام آزمایشی به یکی از مخاطبین خود در اکانت بیزینس بفرستید تا سامانه خودترمیمی آن را درجا ست کند.`;
          }
          await sendMessage(chat.id, debugText, { reply_to_message_id: msg.message_id });
          break;
        }

        case "/setvip":
          if (from.id === cfg.BOT_OWNER_ID && isGroup) {
            session.vipStatus = true;
            await saveSession(session, env);
            await setGroupVIP(chat.id, true, env);
            await sendMessage(chat.id, "✅ گروه VIP شد! 👑", { reply_to_message_id: msg.message_id });
          }
          break;
        case "/unsetvip":
          if (from.id === cfg.BOT_OWNER_ID && isGroup) {
            session.vipStatus = false;
            await saveSession(session, env);
            await setGroupVIP(chat.id, false, env);
            await sendMessage(chat.id, "❌ VIP غیرفعال شد.", { reply_to_message_id: msg.message_id });
          }
          break;
        case "/del":
          if (from.id === cfg.BOT_OWNER_ID && msg.reply_to_message) {
            await deleteMessage(chat.id, msg.reply_to_message.message_id);
            await deleteMessage(chat.id, msg.message_id);
          }
          break;
        case "/eval":
          if (from.id === cfg.BOT_OWNER_ID) {
            const codeToEval = args.join(" ");
            if (!codeToEval) {
              await sendMessage(chat.id, "⚠️ Usage: `/eval [JS code]`", { reply_to_message_id: msg.message_id });
              break;
            }
            try {
              const result = await Promise.resolve((0, eval)(codeToEval));
              const resultStr = typeof result === "object" ? JSON.stringify(result, null, 2) : String(result);
              await sendMessage(chat.id, `✅ **Eval Result:**\n\`\`\`json\n${resultStr.substring(0, 4000)}\n\`\`\``, { reply_to_message_id: msg.message_id });
            } catch (e) {
              await sendMessage(chat.id, `❌ **Eval Error:**\n\`\`\`\n${e instanceof Error ? e.message : e}\n\`\`\``, { reply_to_message_id: msg.message_id });
            }
          }
          break;
        default:
          if (!isGroup) await sendMessage(chat.id, "❓ دستور ناشناخته. از /help استفاده کنید.", { reply_to_message_id: msg.message_id });
      }
      return;
    }

    // Dedup: اگر همان کاربر در چند ثانیه همان درخواست را (double-tap) ارسال کرد،
    // فقط یک‌بار پردازش می‌شود — از اجرای موازی و مصرف مضاعف D1/Gemini جلوگیری می‌کند.
    if (isDuplicateUserRequest(from.id, chat.id, text)) return;

    const bucket = getUserBucket(from.id, session.vipStatus);
    if (!bucket.tryConsume()) {
      bumpMetric("rateLimits");
      await sendMessage(chat.id, `⏳ ${lang === "fa" ? "لطفاً کمی صبر کنید" : "Please wait a moment"} (${bucket.availableTokens()} left)`, { reply_to_message_id: msg.message_id });
      return;
    }

    const limitCheck = await checkDailyLimitWithUser(session, from, "message", env);
      if (!limitCheck.allowed) {
        await sendMessage(chat.id, limitCheck.message!, { reply_to_message_id: msg.message_id, reply_markup: JSON.stringify(getVIPKeyboard()) });
        return;
      }

    if (!canProcessRequest(chat.id, reqId)) {
      bumpMetric("rateLimits");
      await sendMessage(chat.id, lang === "fa" ? "🚦 سرور شلوغ است. لطفاً 30 ثانیه صبر کنید." : "🚦 Server busy. Please wait 30s.", { reply_to_message_id: msg.message_id });
      return;
    }

    // Telegram can disconnect a slow webhook before a code generation finishes.
    // Reuse the existing D1/cron task runner for explicit long builds: persist
    // first, acknowledge promptly, and keep one progress message across retries.
    const backgroundResearch=routing?.category==="research"&&/\b(deep|comprehensive|exhaustive|detailed report)\b|عمیق|جامع|مفصل/i.test(text);
    if(cfg.GEMINI_KEYS.length&&(routing?.category==="web_app"||routing?.category==="game_create"||backgroundResearch)
      &&(!isGroup||backgroundResearch||(await getGroupConfig(chat.id,env)).allowHeavy)){
      if(await countUserAgentTasks(from.id,env)>=AGENT_TASK_MAX_PER_USER){
        await sendMessage(chat.id,lang==="fa"?"چند کار در صف داری؛ صبر کن یکی تمام شود.":"You already have several pending tasks. Please let one finish first.",{reply_to_message_id:msg.message_id});return;
      }
      const queued=await sendMessage(chat.id,lang==="fa"?"درخواست برای اجرا در پس‌زمینه در صف قرار می‌گیرد. نتیجه را همین‌جا می‌فرستم.":"The task is being queued for background execution. I’ll post the result here.",{reply_to_message_id:msg.message_id});
      try{
        const reference=msg.reply_to_message?.text?`\n\nReference message:\n${msg.reply_to_message.text.slice(0,2000)}`:"";
        const job=await createReminder({chatId:chat.id,userId:from.id,userName:from.first_name,isGroup,lang,personaId:getEffectivePersonaId(session,from.id,isGroup),
          message:text.slice(0,6000)+reference,kind:"agent_task",dueAt:Date.now(),queuedBuild:true,progressMessageId:queued.message_id},env);
        await editMessageText(chat.id,queued.message_id,lang==="fa"?"درخواست ذخیره شد؛ نتیجه را همین‌جا می‌فرستم.":"Task saved. I’ll post the result here.",
          {reply_markup:JSON.stringify({inline_keyboard:[[btn(lang==="fa"?"لغو کار":"Cancel task",`cancel_task_build_${job.id}`)]]})}).catch(()=>{});
        deferSessionSave(session);
      }catch(error){reqFailed=true;reqError="Build queue unavailable";logger.warn("Could not persist queued build",error);await editMessageText(chat.id,queued.message_id,lang==="fa"?"درخواست در صف ذخیره نشد. کمی بعد دوباره تلاش کن.":"The build could not be queued. Please try again shortly.").catch(()=>{});}
      return;
    }

    // تغییر این خط برای ساخت کانتکست هوشمند در صورت وجود ریپلای:
    markUserActivity(session, "chat");
    const { parts: finalParts, pendingImageBytes } = await buildPartsWithReplyContext(msg, env, lang);

    // "اون عکس قبلی رو ادیت کن" — an edit whose source is an earlier image in
    // the chat rather than a reply. The router already resolved *which* image is
    // meant; the bytes still have to be fetched, otherwise `edit_image` aborts
    // with "no image in this turn" even though the reference was understood.
    let editSourceBytes = pendingImageBytes;
    if (!editSourceBytes && routing?.category === "image_edit" && routing.slots.imageSource === "recent") {
      const recent = getRecentPhoto(chat.id);
      if (recent) {
        try {
          const url = await getFileUrl(recent.fileId);
          const res = await fetchWithTimeout(url, {}, 20_000);
          const buf = await res.arrayBuffer();
          editSourceBytes = buf;
          finalParts.unshift({ inline_data: { mime_type: "image/jpeg", data: arrayBufferToBase64(buf) } });
        } catch (e) {
          logger.warn(`Could not fetch the recent image for an edit request: ${e instanceof Error ? e.message : e}`);
        }
      }
    }

    await processAIRequest(session, from, finalParts, msg, env, requestOrigin, 0, undefined, editSourceBytes, routing);
  } catch (e) {
    reqFailed = true;
    reqError = e instanceof Error ? e.message.slice(0, 200) : String(e);
    logger.error("Error in handleTextMessage", e);
    // Reaching this catch means no answer was delivered: `processAIRequestUnlocked`
    // handles and reports its own failures without rethrowing, so anything landing
    // here escaped from outside it (session load, limits, reply-context build) and
    // previously ended the turn in complete silence.
    await notifyTurnFailure(chat.id, e, {
      replyToMessageId: msg.message_id,
      userId: from.id,
      reqId,
    });
  } finally {
    releaseRequest(chat.id, reqId);
    const durationMs = Date.now() - reqStart;
    bumpMetric("latencyTotal", durationMs);
    bumpMetric("latencyCount");
    const reqEntry = { reqId, ts: Date.now(), chatId: chat.id, userId: from.id, kind: "text", ok: !reqFailed, error: reqError, durationMs };
    logRequest(reqEntry);
    void persistRequestDiagnostic(reqEntry, env);
  }
}

function progressBar(current: number, total: number, size = 10): string {
  const filled = Math.round((current / total) * size);
  const bar = "█".repeat(filled) + "░".repeat(size - filled);
  const pct = Math.round((current / total) * 100);
  return `[${bar}] ${pct}%`;
}

async function sendProgress(
  chatId: number,
  replyTo: number,
  label: string,
  steps: string[],
  lang: Language,
): Promise<{
  msgId: number;
  update: (step: number, extra?: string) => Promise<void>;
  cleanup: () => Promise<void>;
  done: (text: string) => Promise<void>;
}> {
  const totalSteps = steps.length;
  const msg = await sendMessage(
    chatId,
    `⚙️ **${label}**\n\n${progressBar(0, totalSteps)}\n⏳ ${steps[0]}`,
    { reply_to_message_id: replyTo }
  ).catch(() => null);

  const msgId = msg?.message_id ?? 0;
  if (msgId) {
    activeProgressMessages.set(chatId, msgId);
  }
  let lastUpdate = 0;

  return {
    msgId,
    update: async (step: number, extra = "") => {
      if (!msgId) return;
      const now = Date.now();
      if (step > 0 && now - lastUpdate < 1500) return;
      lastUpdate = now;
      const stepText = steps[Math.min(step, steps.length - 1)];
      await editMessageText(
        chatId, msgId,
        `⚙️ **${label}**\n\n${progressBar(step, totalSteps)}\n⏳ ${stepText}${extra ? `\n${extra}` : ""}`
      ).catch(() => {});
    },
    cleanup: async () => {
      activeProgressMessages.delete(chatId);
      if (msgId) await deleteMessage(chatId, msgId).catch(() => {});
    },
    done: async (text: string) => {
      activeProgressMessages.delete(chatId);
      if (!msgId) {
        await sendMessage(chatId, text, { reply_to_message_id: replyTo });
      } else {
        await editMessageText(chatId, msgId, text).catch(() => {
          sendMessage(chatId, text, { reply_to_message_id: replyTo });
        });
      }
    },
  };
}

/** مصرف‌کننده‌ی ورودی متنیِ مالک برای پنل ادمین (جستجو/پرامپت/سقف/requestId). */
async function handleBroadcastMessage(
  msg: TgMessage,
  state: { mode: "all" | "vip" | "free" | "specific"; userId?: number },
  env: Env,
): Promise<void> {
  const { chat } = msg;
  const proc = await sendMessage(chat.id, "⏳ **Preparing list...**", { reply_to_message_id: msg.message_id });
  
  if (state.mode === "specific" && state.userId) {
    const sent = await sendMessage(state.userId, `📢 **پیام از مدیریت:**\n\n${msg.text}`).catch(() => null);
    if (sent) {
      await editMessageText(chat.id, proc.message_id, `✅ پیام با موفقیت به شناسه \`${state.userId}\` ارسال شد.`);
    } else {
      await editMessageText(chat.id, proc.message_id, `❌ ارسال پیام ناموفق بود (احتمالاً ربات از گروه خارج شده یا دسترسی ندارد).`);
    }
    broadcastStates.delete(chat.id);
    return;
  }
  
  const result = await createBroadcastJob(env, { message: msg.text!, audience: state.mode, adminChatId: chat.id, adminMessageId: proc.message_id });
  broadcastStates.delete(chat.id);
  if (!result.ok && "error" in result) {
    const errText = result.error === "ALREADY_RUNNING" ? "❌ برادکست دیگری در حال اجراست، صبر کن تمام بشه." : "❌ No users found";
    await editMessageText(chat.id, proc.message_id, errText);
    return;
  }
await editMessageText(chat.id, proc.message_id,
    `📋 **Job queued!**\n\n👥 Recipients: **${result.job.totalUsers}**\n⏳ Starting first batch...`,
    { reply_markup: broadcastProgressKeyboard(false) });
  await processBroadcastBatch(env);
}

async function handleVoiceMessage(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from, voice } = msg;
  if (!from || !voice) return;
  const isGroup = chat.type !== "private";
  if (chat.type !== "private") saveGroupInfo(chat, env).catch(() => {});

  // The prologue (session load, activation gate, block checks, slot acquisition)
  // used to sit OUTSIDE the try, so a transient D1 failure there ended the turn
  // with no reply and no diagnostic. `reqId`/`slotHeld` are declared up front so
  // the single `finally` can release exactly what was acquired.
  let reqId = "";
  let slotHeld = false;
  let loadingMsg: TgMessage | null = null;
  try {
    const [session, mc] = await Promise.all([
      getOrCreateSession(chat, from, env),
      checkMaintenance(env, from.id),
    ]);

    // ── Group activation gate: disabled groups are completely silent. ──
    if (isGroup && !await isGroupEnabled(chat.id, chat.type, env)) return;

    if (isGroup && !shouldRespondInGroup(msg, session)) return;
    if (mc.blocked) { await sendMessage(chat.id, mc.message!, { reply_to_message_id: msg.message_id }); return; }

    if (await isUserBlocked(session, from, env)) {
      if (!isGroup) {
        const blk = getBlockedMessage(session.language);
        await sendMessage(chat.id, blk.text, { reply_to_message_id: msg.message_id, reply_markup: JSON.stringify(blk.keyboard) });
      }
      return;
    }

    reqId = generateId();
    if (!canProcessRequest(chat.id, reqId)) {
      await sendMessage(chat.id, "🚦 Server busy. Try again in 30s.", { reply_to_message_id: msg.message_id }); return;
    }
    slotHeld = true;

    const lang = session.language;

    if (!cfg.GEMINI_KEYS.length) { await sendMessage(chat.id, "❌ Voice recognition unavailable.", { reply_to_message_id: msg.message_id }); return; }
    if (voice.file_size && voice.file_size > 10 * 1024 * 1024) { await sendMessage(chat.id, "⚠️ File too large (max 10MB).", { reply_to_message_id: msg.message_id }); return; }
    if (voice.duration && voice.duration > 120) { await sendMessage(chat.id, "⚠️ Voice too long (max 2 min).", { reply_to_message_id: msg.message_id }); return; }

    const limitCheck = await checkDailyLimitWithUser(session, from, "voice_sent", env);
    if (!limitCheck.allowed) { await sendMessage(chat.id, limitCheck.message!, { reply_to_message_id: msg.message_id }); return; }

    loadingMsg = await sendMessage(chat.id,
      lang === "fa" ? "> 🎤 **در حال دریافت صوت...**" : "> 🎤 **Fetching audio...**",
      { reply_to_message_id: msg.message_id },
    );

    const fileUrl = await getFileUrl(voice.file_id);
    await editMessageText(chat.id, loadingMsg.message_id,
      lang === "fa" ? "> 🔊 **در حال استخراج متن...**" : "> 🔊 **Transcribing...**");

    let transcript: string;
    try {
      transcript = await transcribeVoice(fileUrl);
    } catch (e) {
      const errMsg = e instanceof Error ? e.message : String(e);
      logger.error("Voice transcription failed", errMsg);
      const debugSuffix = from.id === cfg.BOT_OWNER_ID ? `\n\n🔧 **جزئیات کامل خطا:**\n\`\`\`\n${errMsg.slice(0, 900)}\n\`\`\`` : "";
      await editMessageText(chat.id, loadingMsg.message_id,
        (lang === "fa" ? "❌ **تشخیص صدا ناموفق**\n\n> 💡 واضح‌تر صحبت کنید" : "❌ **Transcription failed**\n\n> 💡 Please speak clearly") + debugSuffix);
      return;
    }

    if (transcript.length < 2) {
      await editMessageText(chat.id, loadingMsg.message_id, lang === "fa" ? "🔇 صدایی تشخیص داده نشد." : "🔇 No speech detected."); return;
    }

    await editMessageText(chat.id, loadingMsg.message_id,
      lang === "fa" ? `> 🎙️ **شما گفتید:**\n> _${transcript}_\n> ⏳ در حال بررسی...` : `> 🎙️ **You said:**\n> _${transcript}_\n> ⏳ Processing...`);

    await incrementUsageWithUser(session, from, "voice_sent", env);
    session.statistics.voicesReceived++;
    recordRequest(session);
    // Transcription is done; free the per-chat slot before the (much longer) AI
    // turn so a voice note does not hold a concurrency slot for its whole life.
    releaseRequest(chat.id, reqId);
    slotHeld = false;

    // Send both the transcript and the original audio. The transcript remains the
    // primary reliable text representation, while the binary audio preserves
    // tone, non-speech sounds, pronunciation and anything STT may have missed.
    //
    // Only the *attachment build* is guarded here. The original version also had
    // the `processAIRequest` call inside this try, so a failure anywhere in the AI
    // turn re-ran the entire turn transcript-only — duplicated model work and, when
    // the first attempt had already answered, two replies to one voice note.
    let voiceParts: Part[] | null = null;
    try {
      const audioRes = await fetchExternalSafe(fileUrl, {}, 20_000, 12 * 1024 * 1024);
      const audioBytes = await readResponseBytesLimited(audioRes, 12 * 1024 * 1024);
      const audioMime = String(voice.mime_type || "audio/ogg").toLowerCase();
      const safeAudioMime = audioMime.startsWith("audio/") ? audioMime : "audio/ogg";
      voiceParts = [
        { inline_data: { mime_type: safeAudioMime, data: arrayBufferToBase64(bytesToArrayBuffer(audioBytes)) } },
        { text: lang === "fa"
          ? `[ویس واقعی کاربر به‌صورت فایل صوتی پیوست شده است. خود صوت را بررسی کن و از متن استخراج‌شده برای دقت بیشتر کمک بگیر. درباره نام فایل یا نداشتن دسترسی به صوت حدس نزن.\n\n🎙️ متن استخراج‌شده: ${transcript}`
          : `[The user's actual voice note is attached as audio. Analyze the audio itself when possible and use the transcript as an additional aid. Do not infer from a filename or claim the audio is inaccessible.\n\n🎙️ Transcript: ${transcript}` }
      ];
    } catch (audioErr) {
      logger.warn(`Voice binary attachment failed; continuing with transcript only: ${audioErr instanceof Error ? audioErr.message : String(audioErr)}`);
    }
    await processAIRequest(session, from, voiceParts ?? [{ text: transcript }], loadingMsg, env, requestOrigin);
  } catch (e) {
    logger.error("Voice processing failed", e);
    const errMsg = e instanceof Error ? e.message : String(e);
    const debugSuffix = from.id === cfg.BOT_OWNER_ID ? `\n\n🔧 **جزئیات کامل خطا:**\n\`\`\`\n${errMsg.slice(0, 900)}\n\`\`\`` : "";
    if (loadingMsg) {
      await editMessageText(chat.id, loadingMsg.message_id, "> ❌ Voice processing failed." + debugSuffix).catch(() => {});
    } else {
      // Failed before the progress message existed (session load, limits, file
      // lookup). There is nothing to edit, so the user needs a fresh notice —
      // otherwise the voice note is answered by silence.
      await notifyTurnFailure(chat.id, e, { replyToMessageId: msg.message_id, userId: from.id, reqId });
    }
  } finally {
    if (slotHeld) releaseRequest(chat.id, reqId);
  }
}

async function handleMediaMessage(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from, caption, photo, document, animation, video } = msg;
  if (!from) return;
  const isGroup = chat.type !== "private";
  if (isGroup) saveGroupInfo(chat, env).catch(() => {});
  
  const [session, mc] = await Promise.all([
    getOrCreateSession(chat, from, env),
    checkMaintenance(env, from.id),
  ]);
  const lang = session.language;  // ── Group activation gate: disabled groups are completely silent. ──
  if (isGroup && !await isGroupEnabled(chat.id, chat.type, env)) return;

  if (isGroup && !shouldRespondInGroup(msg, session)) return;
  if (mc.blocked) { 
    await sendMessage(chat.id, mc.message!, { reply_to_message_id: msg.message_id }); 
    return; 
  }

  if (await isUserBlocked(session, from, env)) {
    if (!isGroup) {
      const blk = getBlockedMessage(session.language);
      await sendMessage(chat.id, blk.text, { reply_to_message_id: msg.message_id, reply_markup: JSON.stringify(blk.keyboard) });
    }
    return;
  }
  
  if (!cfg.GEMINI_KEYS.length) { 
    await sendMessage(chat.id, "❌ Media processing unavailable.", { reply_to_message_id: msg.message_id }); 
    return;
  }

  // A caption is a request like any other text: "این عکس رو کارتونی کن" sent
  // *with* the photo has to reach the edit pipeline, not a generic description.
  const mediaRouting: IntentDecision | undefined = caption?.trim()
    ? classifyRequestIntent({
        text: caption,
        isGroup,
        isReply: Boolean(msg.reply_to_message),
        repliedUserId: msg.reply_to_message?.from?.id ?? null,
        repliedToSelf: Boolean((BOT_SELF_ID ?? BOT_INFO?.id) && msg.reply_to_message?.from?.id === (BOT_SELF_ID ?? BOT_INFO?.id)),
        repliedHasImage: Boolean(msg.reply_to_message?.photo?.length),
        hasAttachedImage: Boolean(photo?.length),
        hasRecentImage: Boolean(getRecentPhoto(chat.id)),
        isOwner: from.id === cfg.BOT_OWNER_ID,
        isChatAdmin: from.id === cfg.BOT_OWNER_ID,
        selfNames: novaSelfNames(session, from.id, isGroup),
        personaAliases: PERSONA_ALIASES,
        activePersonaId: getEffectivePersonaId(session, from.id, isGroup),
      })
    : undefined;
  if (mediaRouting) logger.info(`[intent:media] ${describeRoutingIntent(mediaRouting)}`);

  let fileId = "", mimeType = "", fileName = "", category = "";

if (photo?.length) { fileId = photo[photo.length - 1].file_id; mimeType = "image/jpeg"; category = "image"; }
  else if (msg.audio) {
    if (msg.audio.file_size && msg.audio.file_size > 15 * 1024 * 1024) {
      await sendMessage(chat.id, lang === "fa" ? "⚠️ فایل صوتی خیلی بزرگ است (حداکثر ۱۵ مگابایت)." : "⚠️ Audio file too large (max 15MB).", { reply_to_message_id: msg.message_id });
      return;
    }
    fileId = msg.audio.file_id; mimeType = msg.audio.mime_type ?? "audio/mpeg"; category = "audio";
  }
  else if (video) {
    if (video.file_size && video.file_size > 8 * 1024 * 1024) { 
      await sendMessage(chat.id, "⚠️ Video too large (max 8MB).", { reply_to_message_id: msg.message_id }); 
      return; 
    }
    fileId = video.file_id; mimeType = video.mime_type ?? "video/mp4"; category = "video";
  } else if (animation) {
    if (animation.file_size && animation.file_size > 15 * 1024 * 1024) {
      await sendMessage(chat.id, lang === "fa" ? "⚠️ گیف خیلی بزرگ است (حداکثر ۱۵ مگابایت)." : "⚠️ GIF too large (max 15MB).", { reply_to_message_id: msg.message_id });
      return;
    }
    fileId = animation.file_id; mimeType = animation.mime_type ?? "video/mp4"; category = "gif";
  } else if (document) {
    fileId = document.file_id; mimeType = document.mime_type ?? ""; fileName = document.file_name ?? "";
    if (mimeType === "application/pdf" || fileName.endsWith(".pdf")) { category = "pdf"; mimeType = "application/pdf"; }
    else if (mimeType.startsWith("audio/") || /\.(mp3|wav|ogg|m4a|aac)$/i.test(fileName)) { category = "audio"; mimeType = mimeType || "audio/mpeg"; }
    else if (mimeType.startsWith("text/") || /\.(txt|json|js|py|ts|csv|md|html|css|php|c|cpp|rs|log|xml|yaml|yml|toml)$/i.test(fileName)) category = "text";
    else if (
      /\.(doc|docx|xls|xlsx|ppt|pptx|odt|ods|odp|rtf|epub)$/i.test(fileName) ||
      /^(application\/(msword|vnd\.openxmlformats-officedocument\.(wordprocessingml\.document|spreadsheetml\.sheet|presentationml\.presentation)|vnd\.ms-excel|vnd\.ms-powerpoint|rtf|epub\+zip)|text\/rtf)$/i.test(mimeType)
    ) category = "document";
    else { 
      await sendMessage(chat.id, "⚠️ فرمت فایل پشتیبانی نمی‌شود.", { reply_to_message_id: msg.message_id }); 
      return; 
    }
  }

  if (!category) return;

  try {
    const fileUrl = await getFileUrl(fileId);
    const maxDownloadBytes = 18 * 1024 * 1024;
    const fileRes = await fetchExternalSafe(fileUrl, {}, 30_000, maxDownloadBytes);
    const arrayBuf = bytesToArrayBuffer(await readResponseBytesLimited(fileRes, maxDownloadBytes));

    if (category === "text") {
      const realType = detectBinarySignature(arrayBuf);
      if (realType) {
        logger.warn(`Document mislabeled: claimed text but is actually ${realType} (filename: ${fileName})`);
        await sendMessage(chat.id,
          lang === "fa"
            ? `⚠️ این فایل در واقع یک فایل ${realType} است، نه متنی. لطفاً آن را به‌صورت عکس/فایل مناسب بفرستید.`
            : `⚠️ This file is actually ${realType}, not text. Please send it in the correct format.`,
          { reply_to_message_id: msg.message_id });
        return;
      }
    }

    const parts: Part[] = [];

    if (category === "image") {
      const b64 = arrayBufferToBase64(arrayBuf);
      // 💾 ذخیره‌ی عکس آپلودی کاربر (حداکثر ۷ روز) تا هم برای ویرایش در دسترس
      // باشد، هم به‌عنوان Asset در وب‌اپ‌ها/بازی‌ها قابل استفاده باشد.
      // Off the critical path: hosting is a blob write plus a serialized
      // read-modify-write of the media registry (three D1 round-trips on the D1
      // backend), and it used to be awaited *before* the model call for every
      // uploaded photo. The URL is deterministic, and nothing fetches it during
      // this turn, so the registration runs in the background while the answer
      // is generated and is still drained before the request returns.
      const upId = `img_${generateId()}`;
      // Do not advertise a URL for a blob the active backend would reject.
      const canHost = Boolean(requestOrigin) && arrayBuf.byteLength <= mediaSizeLimit(env);
      const hostedUrl = canHost ? `${requestOrigin}/app/${upId}.png` : "";
      runBackground(
        () => registerAndSaveMedia(upId, arrayBuf, from.id, from.first_name, env, caption?.trim() || undefined, "image", "upload"),
        6000,
        "upload-register",
      );
      const textPrompt = lang === "fa"
        ? `[تصویر ارسالی مستقیم از کاربر پیوست شده است. اگر کاربر خواسته چیزی در این تصویر تغییر/ویرایش/اصلاح شود، ابزار "edit_image" را با یک دستور دقیق انگلیسی صدا بزن. اگر فقط سوال یا توضیح درباره تصویر دارد، مستقیم پاسخ بده.${hostedUrl ? `\nاین تصویر به‌صورت موقت (۷ روز) در ${hostedUrl} میزبانی شده و در صورت نیاز به استفاده در وب‌اپ/بازی در دسترس است.` : ""}\nدرخواست کاربر: ${caption?.trim() || "این تصویر را بررسی کن."}]`
        : `[User directly uploaded this image. If the user wants something changed/edited/fixed about this image, call the "edit_image" tool with a precise English instruction. If they just have a question or want a description, answer directly.${hostedUrl ? `\nThis image is temporarily hosted (7 days) at ${hostedUrl} and is available for web-app/game use if needed.` : ""}\nUser request: ${caption?.trim() || "Analyze this image."}]`;

      parts.push({ inline_data: { mime_type: mimeType, data: b64 } });
      parts.push({ text: textPrompt });
    } else if (category === "gif") {
      // 🎞️ خودِ فایل GIF/MP4 به Gemini می‌رود؛ thumbnail فقط fallback است.
      parts.push(...await buildGifAnalysisParts(animation!, arrayBuf, mimeType, caption, lang));
    } else if (category === "video") {
      const videoMime = /^video\/(mp4|webm|mpeg|quicktime)$/i.test(mimeType) ? mimeType : "video/mp4";
      parts.push({ inline_data: { mime_type: videoMime, data: arrayBufferToBase64(arrayBuf) } });
      parts.push({ text: lang === "fa"
        ? `[این یک ویدیوی واقعی است و فایل آن پیوست شده. خود ویدیو را بررسی کن: افراد/اشیا، اتفاقات، ترتیب رویدادهای مهم، متن‌های قابل مشاهده و فضای کلی را فقط از محتوای واقعی ویدیو استخراج کن. اگر چیزی را نمی‌توانی تشخیص بدهی، صریح بگو. درباره نام فایل یا دسترسی فرضی صحبت نکن.]\nدرخواست کاربر: ${caption?.trim() || "این ویدیو را تحلیل کن."}`
        : `[This is a real video and the video file is attached. Analyze the actual video: people/objects, important events and sequence, visible text, and overall context. If something cannot be determined, say so explicitly. Never infer content from the filename.]\nUser request: ${caption?.trim() || "Analyze this video."}` });
    } else if (category === "text") {
      const text = new TextDecoder("utf-8", { fatal: false, ignoreBOM: false }).decode(arrayBuf).slice(0, 30_000);
      const ext = fileName.split(".").pop() ?? "txt";
      const textPrompt = lang === "fa"
        ? `[فایل متنی پیوست شده با نام «${fileName}»]:\n\n\`\`\`${ext}\n${text}\n\`\`\`\n\nدرخواست کاربر: ${caption?.trim() || "این فایل را تحلیل کن."}`
        : `[Attached text file: "${fileName}":]\n\n\`\`\`${ext}\n${text}\n\`\`\`\n\nUser request: ${caption?.trim() || "Analyze this file."}`;
      parts.push({ text: textPrompt });
    } else if (category === "audio") {
      const b64 = arrayBufferToBase64(arrayBuf);
      parts.push({ inline_data: { mime_type: mimeType, data: b64 } });
      parts.push({ text: caption?.trim() || (lang === "fa" ? "این فایل صوتی را گوش بده و تحلیل کن." : "Listen to and analyze this audio file.") });
    } else if (category === "pdf") {
      const b64 = arrayBufferToBase64(arrayBuf);
      parts.push({ inline_data: { mime_type: "application/pdf", data: b64 } });
      parts.push({ text: caption?.trim() || (lang === "fa" ? "این فایل PDF را دقیق بخوان و در صورت سؤال، پاسخ را فقط بر اساس محتوای واقعی سند بده." : "Read this PDF carefully and answer based on its actual contents.") });
    } else if (category === "document") {
      const b64 = arrayBufferToBase64(arrayBuf);
      parts.push({ inline_data: { mime_type: mimeType, data: b64 } });
      parts.push({ text: caption?.trim() || (lang === "fa" ? `این سند «${fileName || "فایل"}» را بررسی کن و پاسخ را فقط بر اساس محتوای واقعی آن بده.` : `Analyze the attached document "${fileName || "file"}" and answer only from its actual contents.`) });
    } else {
      const b64 = arrayBufferToBase64(arrayBuf);
      parts.push({ inline_data: { mime_type: mimeType, data: b64 } });
      parts.push({ text: caption?.trim() || (lang === "fa" ? "این رسانه را بررسی و تحلیل کن." : "Analyze this media.") });
    }

    // A user-uploaded GIF used to be learned into the reaction library here.
    // That library is global — one key per mood, shared across every chat — so
    // one person's upload became a reaction Nova could replay into someone
    // else's conversation. Stickers are still learned (they come from public
    // sticker sets, so they carry no private content); arbitrary uploaded
    // animations are not. `resend_last_media` still covers "send that one
    // again", and it is scoped to the chat the file came from.
    if (category === "gif") {
      recordRecentMedia(chat.id, { fileId, type: "animation", ts: Date.now() });
    } else if (category === "image") {
      recordRecentMedia(chat.id, { fileId, type: "photo", ts: Date.now() });
    }

    logger.info(`[handleMediaMessage] category=${category} bytes=${arrayBuf.byteLength} caption="${(caption ?? "").slice(0, 80)}"`);
    await processAIRequest(session, from, parts, msg, env, requestOrigin, 0, undefined, category === "image" ? arrayBuf : undefined, mediaRouting);
  } catch (e) {
    logger.error("handleMediaMessage failed", e);
    const errMsg = e instanceof Error ? e.message : String(e);
    const userErr = lang === "fa" ? "❌ پردازش فایل ارسالی ناموفق بود." : "❌ Failed to process the sent file.";
    const debugSuffix = from.id === cfg.BOT_OWNER_ID ? `\n\n🔧 **جزئیات کامل خطا:**\n\`\`\`\n${errMsg.slice(0, 900)}\n\`\`\`` : "";
    await sendMessage(chat.id, userErr + debugSuffix, { reply_to_message_id: msg.message_id }).catch(() => {});
  }
}
// SECTION: ADMIN NAVIGATION — ONE PANEL, ONE DESTINATION
//
// Nova used to carry two administrative interfaces. The web dashboard at /admin
// (adminDashboard.html over /api/admin/*) holds the real feature set: cursor-paged
// user search, VIP/block/language/persona actions, per-user prompt, limits, memory
// and reminder management, groups, web apps, media, broadcast, live config, key
// diagnostics, request tracing and logs. Beside it lived a Telegram-native
// "Control Center" — a `cc:` callback tree of hand-rendered panels covering a
// small subset of that, and partly rotted: `ccOverview`'s "👥 Users" button,
// `ccUserMemory`'s "📥 Download" and "🗑️ Wipe Memory" buttons, and every pager's
// page counter (`cc:noop`) had no branch in the dispatcher, so tapping them
// replaced the panel with "not available in this build" — destroying the panel
// the owner was reading.
//
// Two interfaces meant two sources of truth over the same rows and two places to
// fix every bug. The Telegram side is now navigation only: it opens the dashboard,
// optionally deep-linked to a tab. `handleRetiredControlCenterCallback` keeps the
// buttons already sitting in the owner's chat history working.

/**
 * Tabs the dashboard can be deep-linked to. Keep in sync with `TABS` in
 * src/adminDashboard.html — `routeFromHash` there falls back to "overview" for an
 * unknown hash, so drift degrades to the dashboard home rather than a blank panel.
 */
const ADMIN_DASHBOARD_TABS = [
  "overview", "runs", "jobs", "audit",
  "users", "groups", "broadcast",
  "deployments", "media", "stickers", "factory",
  "requests", "logs", "keys", "business", "system",
] as const;
type AdminDashboardTab = (typeof ADMIN_DASHBOARD_TABS)[number];

/**
 * Absolute https URL of the dashboard, or null when this isolate knows no usable
 * origin.
 *
 * `requestOrigin` is module state written by the fetch handler, so it is empty in
 * a cron-only isolate and `http://…` under `wrangler dev`. Telegram rejects a
 * `web_app` button whose url is not absolute https with BUTTON_TYPE_INVALID, and
 * that rejection fails the *whole* sendMessage — the owner got no reply at all
 * rather than a panel. Returning null lets callers degrade to plain text.
 */
function adminDashboardUrl(tab?: AdminDashboardTab, fallbackOrigin?: string): string | null {
  const origin = (requestOrigin || fallbackOrigin || "").trim().replace(/\/+$/, "");
  if (!origin.startsWith("https://")) return null;
  return `${origin}/admin${tab && tab !== "overview" ? `#${tab}` : ""}`;
}

/**
 * The single button that reaches the dashboard. In private chats it is a real
 * `web_app` button — one tap, and Telegram hands the Mini App signed initData
 * that /api/admin/* validates. Groups get a plain callback instead: `web_app`
 * buttons are private-chat only, and one inside a group keyboard makes Telegram
 * refuse the entire message.
 */
function adminPanelButton(label: string, isPrivate: boolean, tab?: AdminDashboardTab): InlineBtn {
  const url = isPrivate ? adminDashboardUrl(tab) : null;
  return url ? { text: label, web_app: { url } } : btn(label, "open_admin");
}

/**
 * The user dashboard's entry-point button — the user-side sibling of
 * `adminPanelButton`. `/my` is a Mini App: Telegram hands it signed initData
 * on open, and every `/api/webapp/*` route it calls is scoped by that initData
 * to the opener, so one button is the whole trust story. In groups (and in any
 * isolate that has not learned its https origin yet) a `web_app` button is
 * impossible or invalid, so the button degrades to a `t.me/<bot>?start=mydash`
 * deep link: `/start mydash` re-opens the panel as a fresh private-chat turn,
 * which still requires the user to have the bot's DM — the same access
 * Telegram itself enforces for Mini Apps.
 */
function userDashboardButton(lang: string, isPrivate: boolean): InlineBtn {
  const label = lang === "fa" ? "🚀 داشبورد من"
    : lang === "ar" ? "🚀 لوحة التحكم الخاصة بي"
    : "🚀 My Dashboard";
  const origin = (requestOrigin || "").trim().replace(/\/+$/, "");
  if (isPrivate && origin.startsWith("https://")) return { text: label, web_app: { url: `${origin}/my` } };
  const username = BOT_INFO?.username;
  return username
    ? urlBtn(label, `https://t.me/${username}?start=mydash`)
    : btn(label, "open_my_dashboard");
}

/**
 * `/start mydash` — the deep-link landing for the dashboard entry button.
 * It is a *discovery* deep link, not a data carrier: it holds no token and no
 * payload, so anyone tapping it in the DM only ever reaches their own panel
 * (the dashboard's initData scoping does the rest).
 */
async function handleDashboardDeepLink(msg: TgMessage, env: Env): Promise<void> {
  const { chat, from } = msg;
  if (!from) return;
  const session = await getOrCreateSession(chat, from, env);
  const lang = session.language;
  const fa = lang === "fa", ar = lang === "ar";
  const text = fa
    ? "🚀 <b>داشبورد من</b>\n\nمدیریت یادآورها، پروژه‌های میزبانی‌شده، فایل‌ها و حافظه‌ات — همه در یک‌جا."
    : ar
    ? "🚀 <b>لوحة التحكم الخاصة بي</b>\n\nإدارة التذكيرات والمشاريع المستضافة والملفات والذاكرة — كلها في مكان واحد."
    : "🚀 <b>My Dashboard</b>\n\nManage your reminders, hosted projects, files and memory — all in one place.";
  // The chat's real type decides the button shape: a web_app button inside a
  // group keyboard makes Telegram refuse the entire message.
  await sendMessage(chat.id, text, {
    parse_mode: "HTML",
    reply_markup: JSON.stringify(validateKeyboard({ inline_keyboard: [[userDashboardButton(lang, chat.type === "private")]] })),
    reply_to_message_id: msg.message_id,
  }).catch(e => logger.warn("[mydash] dashboard link message failed", e));
}

/**
 * `open_my_dashboard` — callback fallback for keyboards already sitting in chat
 * history (or isolates without an https origin yet). A `web_app` button is
 * sent only in private chats; elsewhere it degrades to the deep link, so a
 * group member tapping someone else's panel is never DM'd by surprise.
 */
async function handleOpenDashboardCb(chatId: number, isPrivate: boolean, cbId: string): Promise<void> {
  const origin = (requestOrigin || "").trim().replace(/\/+$/, "");
  const rows: InlineBtn[][] = origin.startsWith("https://") && isPrivate
    ? [[{ text: "🚀 My Dashboard / داشبورد من", web_app: { url: `${origin}/my` } }]]
    : BOT_INFO?.username
      ? [[urlBtn("🚀 My Dashboard / داشبورد من", `https://t.me/${BOT_INFO.username}?start=mydash`)]]
      : [];
  if (!rows.length) { await answerCb(cbId, "⏳ Try again in a moment", true); return; }
  await answerCb(cbId);
  await sendMessage(chatId, "🚀 My Dashboard / داشبورد من", {
    reply_markup: JSON.stringify({ inline_keyboard: rows }),
  }).catch(() => {});
}

/**
 * Owner-facing entry point for every "open the admin panel" path: /admin, the
 * show_admin_panel tool, and the retired `cc:` / `open_admin` buttons. One
 * implementation of the ownership check, the private-chat requirement and the
 * missing-origin fallback, so none of them can drift apart again.
 */
async function sendAdminPanel(
  chatId: number,
  chatType: string,
  userId: number,
  opts: {
    tab?: AdminDashboardTab;
    lang?: Language;
    replyTo?: number;
    editMessageId?: number;
    fallbackOrigin?: string;
  } = {},
): Promise<{ ok: boolean; url: string | null; reason?: "not_owner" | "not_private" | "no_origin" }> {
  if (userId !== cfg.BOT_OWNER_ID) return { ok: false, url: null, reason: "not_owner" };
  const isFa = (opts.lang ?? "fa") === "fa";

  // Deliver either as an edit (callback paths, keeps the chat tidy) or a new
  // message (commands and tool calls).
  const deliver = async (text: string, markup?: string): Promise<void> => {
    const shared: Record<string, unknown> = { parse_mode: "HTML" };
    if (markup) shared.reply_markup = markup;
    if (opts.editMessageId) await editMessageText(chatId, opts.editMessageId, text, shared);
    else await sendMessage(chatId, text, { ...shared, ...(opts.replyTo ? { reply_to_message_id: opts.replyTo } : {}) });
  };

  if (chatType !== "private") {
    await deliver(isFa
      ? "🔐 پنل مدیریت فقط در چت خصوصی نوا باز می‌شود. در پیوی <code>/admin</code> را بزن."
      : "🔐 The admin panel opens only in Nova's private chat. Send <code>/admin</code> there.");
    return { ok: false, url: null, reason: "not_private" };
  }

  const url = adminDashboardUrl(opts.tab, opts.fallbackOrigin);
  if (!url) {
    // Reachable when a cron-only isolate handles this, or under `wrangler dev`
    // over http. Saying so beats sending a keyboard Telegram will refuse.
    logger.warn("[admin] dashboard link unavailable — no https origin known in this isolate");
    await deliver(isFa
      ? "⚠️ آدرس پنل هنوز در این نمونه مشخص نیست. یک پیام دیگر بفرست و بعد دوباره <code>/admin</code> را بزن."
      : "⚠️ The panel URL isn't known in this isolate yet. Send any message, then try <code>/admin</code> again.");
    return { ok: false, url: null, reason: "no_origin" };
  }

  const body = isFa
    ? "👑 <b>Nova Control Center</b>\n\nهمهٔ مدیریت — کاربران، گروه‌ها، رسانه، پیام همگانی، کلیدها و تنظیمات — در پنل وب است:"
    : "👑 <b>Nova Control Center</b>\n\nEverything — users, groups, media, broadcast, keys and config — lives in the web panel:";
  await deliver(body, JSON.stringify({
    inline_keyboard: [[{ text: isFa ? "⚙️ باز کردن پنل مدیریت" : "⚙️ Open Admin Panel", web_app: { url } }]],
  }));
  return { ok: true, url };
}

async function handleAdmin(msg: TgMessage, env: Env): Promise<void> {
  if (!msg.from) return;
  void env; // routing needs no storage access — ownership comes from cfg
  await sendAdminPanel(msg.chat.id, msg.chat.type, msg.from.id, { replyTo: msg.message_id });
}

async function handleLog(msg: TgMessage): Promise<void> {
  if (!msg.from || msg.from.id !== cfg.BOT_OWNER_ID) return;
  const rows = requestLog.slice().reverse().slice(0, 20);
  const text = rows.length
    ? `🧾 <b>Recent request log</b>\n\n${rows.map(r => {
        const status = r.ok ? "🟢" : "🔴";
        const err = r.error ? `\n↳ <i>${escapeHTML(r.error.slice(0, 100))}</i>` : "";
        return `${status} <code>${escapeHTML(r.reqId)}</code> · ${escapeHTML(r.kind)} · <code>${r.durationMs}ms</code>${err}`;
      }).join("\n\n")}`
    : "🧾 <b>Recent request log</b>\n\n📭 No requests recorded yet.";
  await sendMessage(msg.chat.id, text, { reply_to_message_id: msg.message_id, parse_mode: "HTML" });
}

interface ElevenLabsKeyDiagnostic {
  index: number;
  configured: boolean;
  auth: "ok" | "invalid" | "forbidden" | "rate_limited" | "error";
  tts: "ok" | "invalid" | "forbidden" | "rate_limited" | "quota" | "error" | "not_tested";
  subscription?: {
    tier?: string;
    status?: string;
    characterCount?: number;
    characterLimit?: number;
  };
  error?: string;
}

async function diagnoseElevenLabsKey(
  apiKey: string | undefined,
  index: number,
  env: Env,
  opts: { testTts?: boolean } = {},
): Promise<ElevenLabsKeyDiagnostic> {
  if (!apiKey) {
    return {
      index,
      configured: false,
      auth: "error",
      tts: "not_tested",
    };
  }

  const result: ElevenLabsKeyDiagnostic = {
    index,
    configured: true,
    auth: "error",
    tts: "not_tested",
  };

  try {
    const authRes = await fetchWithTimeout(
      "https://api.elevenlabs.io/v1/user/subscription",
      {
        headers: {
          "xi-api-key": apiKey,
        },
      },
      10_000,
    );

    if (authRes.status === 401) {
      result.auth = "invalid";
      result.error = "Invalid API key";
      return result;
    }

    if (authRes.status === 403) {
      result.auth = "forbidden";
      result.error = "API key forbidden or restricted";
      return result;
    }

    if (authRes.status === 429) {
      result.auth = "rate_limited";
      result.error = "Rate limited";
      return result;
    }

    if (!authRes.ok) {
      result.error = `HTTP ${authRes.status}`;
      return result;
    }

    const subscription = await authRes.json() as {
      tier?: string;
      status?: string;
      character_count?: number;
      character_limit?: number;
    };

    result.auth = "ok";
    result.subscription = {
      tier: subscription.tier,
      status: subscription.status,
      characterCount: subscription.character_count,
      characterLimit: subscription.character_limit,
    };

    // Synthesis is the one ElevenLabs check that spends credits. The panel's
    // bulk test skips it so that refreshing a diagnostics page cannot quietly
    // bill the account once per configured key; `/keys` still runs it, which is
    // why the default is on rather than off.
    if (opts.testTts === false) return result;

    const ttsUrl =
      "https://api.elevenlabs.io/v1/text-to-speech/" +
      `${encodeURIComponent(env.ELEVENLABS_VOICE_ID ?? "21m00Tcm4TlvDq8ikWAM")}` +
      "?output_format=opus_48000_64";

    const ttsRes = await fetchWithTimeout(
      ttsUrl,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "xi-api-key": apiKey,
        },
        body: JSON.stringify({
          text: ".",
          model_id: env.ELEVENLABS_MODEL_ID ?? "eleven_v3",
        }),
      },
      15_000,
    );

    if (ttsRes.ok) {
      result.tts = "ok";
      return result;
    }

    const body = await ttsRes.text().catch(() => "");

    if (ttsRes.status === 401) {
      result.tts = "invalid";
    } else if (ttsRes.status === 403) {
      result.tts = "forbidden";
    } else if (ttsRes.status === 429) {
      result.tts = "rate_limited";
    } else if (
      ttsRes.status === 400 &&
      /quota|character_limit|credit/i.test(body)
    ) {
      result.tts = "quota";
    } else {
      result.tts = "error";
    }

    result.error = body.slice(0, 180);
    return result;
  } catch (e) {
    result.error =
      e instanceof Error ? e.message.slice(0, 180) : String(e).slice(0, 180);
    return result;
  }
}

/* ══════════════════════════════════════════════════════════════════════════
   CREDENTIAL PROBES

   The panel used to list Gemini keys as `masked` + `disabled` and offered no
   way to learn whether any of them still worked; `/keys` reported nothing about
   Gemini beyond how many were configured. Neither surface made a single
   upstream call, so a revoked key was indistinguishable from a healthy one
   until a user's request failed.

   Each probe performs a real request against the service Nova actually depends
   on and reports what the upstream said. Four rules hold for all of them:

   1. **Cheapest honest endpoint.** A probe validates a credential; it must not
      consume the quota it is reporting on. Gemini is checked by listing models
      rather than generating, Cloudflare by reading the Workers-AI catalogue
      rather than running inference, ElevenLabs by its subscription endpoint
      rather than synthesising. Where no free check exists — Google Custom
      Search bills per query — the result is flagged `billed` so the number is
      attributable instead of mysterious.
   2. **A probe never mutates routing state.** Probing must not bench a key, and
      a key this isolate has already benched must still be probeable: "benched
      locally, healthy upstream" is precisely what tells an operator the backoff
      has outlived the problem. `benchedUntil` is therefore reported alongside,
      never instead of, the live verdict.
   3. **No secret leaves this layer.** Results carry a mask, and upstream error
      text is both truncated and redacted, because several providers echo the
      credential back inside their own error messages.
   4. **A probe cannot fail the request.** Every one resolves to a verdict;
      `runProbe` converts a throw into `unreachable`. One dead provider must not
      blank the whole panel.
*/

type ProbeStatus =
  | "ok"
  | "invalid"
  | "forbidden"
  | "rate_limited"
  | "unreachable"
  | "not_configured";

type ProbeService =
  | "telegram"
  | "gemini"
  | "cloudflare"
  | "elevenlabs"
  | "google_search"
  | "database"
  | "media";

interface CredentialProbe {
  /** Stable per-credential id, e.g. `gemini:2`. Used by the panel as a row key. */
  id: string;
  service: ProbeService;
  /** The binding name, so a failure points at the secret that needs rotating. */
  label: string;
  masked: string | null;
  status: ProbeStatus;
  /** What the upstream actually said, truncated and redacted. */
  detail?: string;
  latencyMs?: number;
  /** Facts returned by the upstream. Never synthesised, absent when unknown. */
  info?: Record<string, string | number | boolean>;
  /** True when running this probe costs the account something. */
  billed?: boolean;
  /** Local rate-limit backoff, independent of the upstream verdict. */
  benchedUntil?: number | null;
}

/** The shape each probe body resolves to; `runProbe` adds identity and timing. */
type ProbeOutcome = Pick<CredentialProbe, "status" | "detail" | "info">;

const PROBE_TIMEOUT_MS = 8_000;
/** Headers arriving is not the body arriving, so body reads get their own deadline. */
const PROBE_BODY_TIMEOUT_MS = 4_000;

// `maskSecret` and `redactSecrets` live in core.ts: they are pure string
// functions, and the guarantee they carry — that no secret leaves this layer —
// deserves behavioural tests rather than a grep over this file.

async function probeJson<T>(res: Response): Promise<T | null> {
  try {
    return await withTimeout(res.json() as Promise<T>, PROBE_BODY_TIMEOUT_MS, "body timeout");
  } catch {
    return null;
  }
}

async function probeText(res: Response): Promise<string> {
  try {
    return await withTimeout(res.text(), PROBE_BODY_TIMEOUT_MS, "body timeout");
  } catch {
    return "";
  }
}

async function runProbe(
  base: Omit<CredentialProbe, "status" | "latencyMs">,
  fn: () => Promise<Pick<CredentialProbe, "status" | "detail" | "info">>,
): Promise<CredentialProbe> {
  const started = Date.now();
  try {
    const out = await fn();
    return { ...base, ...out, latencyMs: Date.now() - started };
  } catch (e) {
    const raw = e instanceof Error ? e.message : String(e);
    return {
      ...base,
      status: "unreachable",
      // A timeout surfaces as `AbortError`, which tells an operator nothing.
      detail: /abort/i.test(raw)
        ? "Timed out after " + PROBE_TIMEOUT_MS + "ms with no answer"
        : raw.slice(0, 160),
      latencyMs: Date.now() - started,
    };
  }
}

async function probeGeminiKey(key: string, index: number): Promise<CredentialProbe> {
  const benched = globalDisabledKeys[key];
  return await runProbe(
    {
      id: "gemini:" + index,
      service: "gemini",
      label: "GEMINI_KEY_" + index,
      masked: maskSecret(key),
      benchedUntil: benched && benched > Date.now() ? benched : null,
    },
    async (): Promise<ProbeOutcome> => {
      // models.list authenticates the key without spending generation quota. A
      // probe that burned a generation would make "test all keys" a
      // self-inflicted rate limit on exactly the pool it is reporting on.
      const res = await fetchWithTimeout(
        "https://generativelanguage.googleapis.com/v1beta/models?pageSize=1&key=" + encodeURIComponent(key),
        { headers: { accept: "application/json" } },
        PROBE_TIMEOUT_MS,
      );
      if (res.ok) {
        const body = await probeJson<{ models?: unknown[] }>(res);
        return {
          status: "ok",
          info: {
            check: "models.list",
            modelsVisible: Array.isArray(body?.models) ? body!.models!.length : 0,
          },
        };
      }
      const body = await probeJson<{ error?: { message?: string; status?: string } }>(res);
      const reason = redactSecrets(
        body?.error?.message || body?.error?.status || "HTTP " + res.status,
        key,
      ).slice(0, 160);
      const status: ProbeStatus =
        res.status === 400 || res.status === 401 ? "invalid"
        : res.status === 403 ? "forbidden"
        : res.status === 429 ? "rate_limited"
        : "unreachable";
      return { status, detail: reason };
    },
  );
}

async function probeCloudflareAccount(
  account: { id: string; token: string },
  index: number,
): Promise<CredentialProbe> {
  return await runProbe(
    {
      id: "cloudflare:" + index,
      service: "cloudflare",
      label: "CF_ID_" + index + " / CF_TOKEN_" + index,
      masked: maskSecret(account.token),
    },
    async (): Promise<ProbeOutcome> => {
      const headers = { authorization: "Bearer " + account.token, accept: "application/json" };
      // The Workers-AI catalogue is the narrowest read that proves all three
      // things Nova needs at once: the token is live, it is authorised on THIS
      // account, and it carries Workers AI access. Verifying the token alone
      // would pass a token that cannot reach this account's models.
      const res = await fetchWithTimeout(
        "https://api.cloudflare.com/client/v4/accounts/" + encodeURIComponent(account.id) + "/ai/models/search?per_page=1",
        { headers },
        PROBE_TIMEOUT_MS,
      );
      if (res.ok) {
        return {
          status: "ok",
          info: { check: "ai/models/search", account: maskSecret(account.id), scopeVerified: true },
        };
      }
      // 404/405 means this account cannot serve the catalogue route, which is
      // not the same as a bad credential. Fall back to verifying the token so a
      // healthy deployment is not reported as broken by an endpoint change.
      if (res.status === 404 || res.status === 405) {
        const vr = await fetchWithTimeout(
          "https://api.cloudflare.com/client/v4/user/tokens/verify",
          { headers },
          PROBE_TIMEOUT_MS,
        );
        if (vr.ok) {
          return {
            status: "ok",
            detail: "Token is valid. Workers AI access on this account could not be confirmed — the model catalogue returned HTTP " + res.status + ".",
            info: { check: "user/tokens/verify", account: maskSecret(account.id), scopeVerified: false },
          };
        }
        return {
          status: vr.status === 401 || vr.status === 400 ? "invalid" : vr.status === 403 ? "forbidden" : "unreachable",
          detail: redactSecrets(await probeText(vr), account.token).slice(0, 160) || "HTTP " + vr.status,
          info: { check: "user/tokens/verify", account: maskSecret(account.id), scopeVerified: false },
        };
      }
      const body = await probeText(res);
      const status: ProbeStatus =
        res.status === 401 || res.status === 400 ? "invalid"
        : res.status === 403 ? "forbidden"
        : res.status === 429 ? "rate_limited"
        : "unreachable";
      return {
        status,
        detail: redactSecrets(body, account.token).slice(0, 160) || "HTTP " + res.status,
        info: { account: maskSecret(account.id), scopeVerified: false },
      };
    },
  );
}

async function probeElevenLabsKey(
  key: string,
  index: number,
  env: Env,
  deep: boolean,
): Promise<CredentialProbe> {
  return await runProbe(
    {
      id: "elevenlabs:" + index,
      service: "elevenlabs",
      label: index === 0 ? "ELEVENLABS_API_KEY (legacy)" : "ELEVENLABS_KEY_" + index,
      masked: maskSecret(key),
      billed: deep,
    },
    async (): Promise<ProbeOutcome> => {
      // Reuses the diagnostic `/keys` has always used, so the two surfaces
      // cannot drift into disagreeing about the same key.
      const d = await diagnoseElevenLabsKey(key, index, env, { testTts: deep });
      const status: ProbeStatus =
        d.auth === "ok" ? "ok"
        : d.auth === "invalid" ? "invalid"
        : d.auth === "forbidden" ? "forbidden"
        : d.auth === "rate_limited" ? "rate_limited"
        : "unreachable";
      const info: Record<string, string | number | boolean> = { check: deep ? "subscription + synthesis" : "subscription" };
      if (d.subscription) {
        if (d.subscription.tier) info.tier = d.subscription.tier;
        if (d.subscription.status) info.subscriptionStatus = d.subscription.status;
        if (typeof d.subscription.characterCount === "number") info.charactersUsed = d.subscription.characterCount;
        if (typeof d.subscription.characterLimit === "number") info.characterLimit = d.subscription.characterLimit;
      }
      if (d.tts !== "not_tested") info.synthesis = d.tts;
      // Auth can pass while synthesis fails on quota; the key is then real but
      // useless for the one thing Nova wants it for, so it must not read "ok".
      const ttsBroken = deep && d.tts !== "ok" && d.tts !== "not_tested";
      return {
        status: status === "ok" && ttsBroken ? "forbidden" : status,
        detail: d.error ? redactSecrets(d.error, key).slice(0, 160) : undefined,
        info,
      };
    },
  );
}

async function probeGoogleSearch(key: string, cx: string): Promise<CredentialProbe> {
  return await runProbe(
    {
      id: "google_search:1",
      service: "google_search",
      label: "GOOGLE_SEARCH_API_KEY + ENGINE_ID",
      masked: maskSecret(key),
      // Custom Search has no free validation endpoint; the only way to know the
      // key and the engine id work *together* is to spend one of the 100 daily
      // queries. Flagged so the operator can attribute the usage.
      billed: true,
    },
    async (): Promise<ProbeOutcome> => {
      const url = new URL("https://www.googleapis.com/customsearch/v1");
      url.searchParams.set("key", key);
      url.searchParams.set("cx", cx);
      url.searchParams.set("q", "nova connectivity probe");
      url.searchParams.set("num", "1");
      const res = await fetchWithTimeout(url.toString(), { headers: { accept: "application/json" } }, PROBE_TIMEOUT_MS);
      if (res.ok) {
        const body = await probeJson<{ searchInformation?: { totalResults?: string } }>(res);
        return {
          status: "ok",
          info: {
            check: "customsearch.list (1 query billed)",
            totalResults: Number(body?.searchInformation?.totalResults ?? 0),
          },
        };
      }
      const body = await probeJson<{ error?: { message?: string; errors?: { reason?: string }[] } }>(res);
      const reason = body?.error?.errors?.[0]?.reason ?? "";
      const detail = redactSecrets(body?.error?.message || "HTTP " + res.status, key, cx).slice(0, 160);
      // A blown daily quota is a 403 with a specific reason, and it means the
      // credential is fine — reporting it as `forbidden` would send an operator
      // to rotate a working key.
      if (/limitExceeded|rateLimitExceeded|quota/i.test(reason)) {
        return { status: "rate_limited", detail: detail || "Daily query quota exhausted", info: { reason } };
      }
      const status: ProbeStatus =
        res.status === 400 ? "invalid"
        : res.status === 401 ? "invalid"
        : res.status === 403 ? "forbidden"
        : res.status === 429 ? "rate_limited"
        : "unreachable";
      return { status, detail, info: reason ? { reason } : undefined };
    },
  );
}

async function probeTelegramToken(token: string): Promise<CredentialProbe> {
  return await runProbe(
    { id: "telegram:1", service: "telegram", label: "TOKEN", masked: maskSecret(token) },
    async (): Promise<ProbeOutcome> => {
      const res = await fetchWithTimeout(
        "https://api.telegram.org/bot" + token + "/getMe",
        { headers: { accept: "application/json" } },
        PROBE_TIMEOUT_MS,
      );
      const body = await probeJson<{ ok?: boolean; description?: string; result?: { id?: number; username?: string; can_join_groups?: boolean; can_read_all_group_messages?: boolean } }>(res);
      if (res.ok && body?.ok && body.result) {
        return {
          status: "ok",
          info: {
            check: "getMe",
            username: body.result.username ? "@" + body.result.username : "(none)",
            botId: Number(body.result.id ?? 0),
            canJoinGroups: Boolean(body.result.can_join_groups),
            readsAllGroupMessages: Boolean(body.result.can_read_all_group_messages),
          },
        };
      }
      return {
        status: res.status === 401 || res.status === 404 ? "invalid" : res.status === 429 ? "rate_limited" : "unreachable",
        detail: redactSecrets(body?.description || "HTTP " + res.status, token).slice(0, 160),
      };
    },
  );
}

async function probeDatabase(env: Env): Promise<CredentialProbe> {
  return await runProbe(
    { id: "database:1", service: "database", label: "DB (D1)", masked: null },
    async (): Promise<ProbeOutcome> => {
      const row = await env.DB.prepare("SELECT COUNT(*) AS n FROM kv_store").first<{ n: number }>();
      return {
        status: "ok",
        info: { check: "SELECT COUNT(*) FROM kv_store", kvRows: Number(row?.n ?? 0) },
      };
    },
  );
}

async function probeMediaStorage(env: Env): Promise<CredentialProbe> {
  const backend = env.MEDIA ? "r2" : "d1";
  return await runProbe(
    { id: "media:1", service: "media", label: "Media blob store (" + backend + ")", masked: null },
    async (): Promise<ProbeOutcome> => {
      // A write/read/delete round trip, because "the binding exists" is not the
      // same claim as "media can be stored", and the binding is the only part
      // the old panel ever reported.
      const probeId = "probe_" + generateId();
      const payload = new TextEncoder().encode("nova-storage-probe");
      try {
        const put = await putMediaBlob(env, probeId, bytesToArrayBuffer(payload), "application/octet-stream");
        if (!put.ok) {
          return { status: "unreachable", detail: ("error" in put && put.error ? String(put.error) : "write rejected").slice(0, 160), info: { backend } };
        }
        const got = await getMediaBlob(env, probeId);
        if (!got) return { status: "unreachable", detail: "Wrote the probe object but could not read it back", info: { backend } };
        if (got.byteLength !== payload.byteLength) {
          return { status: "unreachable", detail: "Read back " + got.byteLength + " bytes, wrote " + payload.byteLength, info: { backend } };
        }
        return { status: "ok", info: { backend, check: "write + read + delete", bytes: payload.byteLength } };
      } finally {
        // Always runs: a probe that leaks its own object on the failure path
        // would slowly fill the store it is meant to be checking.
        await deleteMediaBlob(env, probeId).catch(() => false);
      }
    },
  );
}

/** The ElevenLabs pool, including the legacy single-key binding, de-duplicated. */
function collectElevenLabsKeys(env: Env): { key: string; index: number }[] {
  const pool = [
    env.ELEVENLABS_KEY_1, env.ELEVENLABS_KEY_2, env.ELEVENLABS_KEY_3,
    env.ELEVENLABS_KEY_4, env.ELEVENLABS_KEY_5, env.ELEVENLABS_KEY_6,
  ];
  const out: { key: string; index: number }[] = [];
  pool.forEach((key, i) => { if (key) out.push({ key, index: i + 1 }); });
  const legacy = env.ELEVENLABS_API_KEY;
  // Index 0 marks the legacy binding, and it is skipped when it duplicates a
  // pool entry so the panel does not report the same key twice.
  if (legacy && !out.some(e => e.key === legacy)) out.push({ key: legacy, index: 0 });
  return out;
}

/**
 * Every service `probeAllCredentials` knows how to test, in the order it
 * reports them.
 *
 * The inventory (free, instant, rendered on tab open) and the prober (real
 * upstream calls, on demand) are two views of this one list. They used to be
 * destined to drift — a panel listing a service it cannot test, or a probe for
 * a service the panel never shows — so a regression test asserts both cover
 * exactly these names.
 */
const PROBE_SERVICES: readonly ProbeService[] = [
  "telegram", "database", "media", "gemini", "cloudflare", "elevenlabs", "google_search",
] as const;

interface CredentialInventoryEntry {
  service: ProbeService;
  label: string;
  /** False means no secret is bound — rendered as "not set up", not as a failure. */
  configured: boolean;
  credentials: { id: string; label: string; masked: string | null; benchedUntil?: number | null }[];
  /** Operator-facing caveat, e.g. that testing this service costs a query. */
  note?: string;
}

/**
 * What is configured, without calling anything.
 *
 * Separated from probing so opening the tab is free and instant: the old panel
 * conflated the two by showing a `disabled` flag that came from this isolate's
 * own backoff map and looked like a verdict about the key.
 */
function buildCredentialInventory(env: Env): CredentialInventoryEntry[] {
  const now = Date.now();
  const eleven = collectElevenLabsKeys(env);
  return [
    {
      service: "telegram",
      label: "Telegram Bot API",
      configured: Boolean(cfg.TOKEN),
      credentials: cfg.TOKEN ? [{ id: "telegram:1", label: "TOKEN", masked: maskSecret(cfg.TOKEN) }] : [],
    },
    {
      service: "database",
      label: "D1 database",
      configured: Boolean(env.DB),
      credentials: env.DB ? [{ id: "database:1", label: "DB", masked: null }] : [],
    },
    {
      service: "media",
      label: "Media blob store",
      configured: true,
      credentials: [{ id: "media:1", label: env.MEDIA ? "MEDIA (R2)" : "kv_store (D1 fallback)", masked: null }],
      note: env.MEDIA ? undefined : "No R2 bucket is bound, so blobs live in D1 and are capped at 2 MB each.",
    },
    {
      service: "gemini",
      label: "Google Gemini",
      configured: cfg.GEMINI_KEYS.length > 0,
      credentials: cfg.GEMINI_KEYS.map((k, i) => {
        const until = globalDisabledKeys[k];
        return {
          id: "gemini:" + (i + 1),
          label: "GEMINI_KEY_" + (i + 1),
          masked: maskSecret(k),
          benchedUntil: until && until > now ? until : null,
        };
      }),
    },
    {
      service: "cloudflare",
      label: "Cloudflare Workers AI",
      configured: cfg.CF_ACCOUNTS.length > 0,
      credentials: cfg.CF_ACCOUNTS.map((a, i) => ({
        id: "cloudflare:" + (i + 1),
        label: "CF_ID_" + (i + 1) + " / CF_TOKEN_" + (i + 1),
        masked: maskSecret(a.token),
      })),
    },
    {
      service: "elevenlabs",
      label: "ElevenLabs TTS",
      configured: eleven.length > 0,
      credentials: eleven.map(e => ({
        id: "elevenlabs:" + e.index,
        label: e.index === 0 ? "ELEVENLABS_API_KEY (legacy)" : "ELEVENLABS_KEY_" + e.index,
        masked: maskSecret(e.key),
      })),
      note: "A deep test also synthesises one character, which spends credits.",
    },
    {
      service: "google_search",
      label: "Google Custom Search",
      configured: Boolean(cfg.GOOGLE_SEARCH_API_KEY && cfg.GOOGLE_SEARCH_ENGINE_ID),
      credentials: cfg.GOOGLE_SEARCH_API_KEY && cfg.GOOGLE_SEARCH_ENGINE_ID
        ? [{ id: "google_search:1", label: "GOOGLE_SEARCH_API_KEY + ENGINE_ID", masked: maskSecret(cfg.GOOGLE_SEARCH_API_KEY) }]
        : [],
      note: "Testing this spends one of the 100 free daily queries — there is no free validation endpoint.",
    },
  ];
}

interface CredentialProbeReport {
  probes: CredentialProbe[];
  summary: { total: number; ok: number; failing: number; notConfigured: number; billed: number };
  /** Which services have no credentials at all — distinct from "configured but broken". */
  missing: ProbeService[];
  deep: boolean;
  ranAt: number;
}

/**
 * Probes every configured service concurrently.
 *
 * Concurrency is unbounded on purpose: the worst case is ~20 requests, well
 * inside the free plan's 50-subrequest ceiling, and running them in series
 * would multiply the panel's wait by twenty. Each probe already contains its
 * own failure, so `Promise.all` cannot reject here.
 */
async function probeAllCredentials(env: Env, opts: { deep?: boolean } = {}): Promise<CredentialProbeReport> {
  const deep = opts.deep === true;
  const jobs: Promise<CredentialProbe>[] = [];
  const missing: ProbeService[] = [];

  jobs.push(probeTelegramToken(cfg.TOKEN));
  jobs.push(probeDatabase(env));
  jobs.push(probeMediaStorage(env));

  if (cfg.GEMINI_KEYS.length) cfg.GEMINI_KEYS.forEach((k, i) => jobs.push(probeGeminiKey(k, i + 1)));
  else missing.push("gemini");

  if (cfg.CF_ACCOUNTS.length) cfg.CF_ACCOUNTS.forEach((a, i) => jobs.push(probeCloudflareAccount(a, i + 1)));
  else missing.push("cloudflare");

  const eleven = collectElevenLabsKeys(env);
  if (eleven.length) eleven.forEach(e => jobs.push(probeElevenLabsKey(e.key, e.index, env, deep)));
  else missing.push("elevenlabs");

  if (cfg.GOOGLE_SEARCH_API_KEY && cfg.GOOGLE_SEARCH_ENGINE_ID) {
    jobs.push(probeGoogleSearch(cfg.GOOGLE_SEARCH_API_KEY, cfg.GOOGLE_SEARCH_ENGINE_ID));
  } else {
    missing.push("google_search");
  }

  const probes = await Promise.all(jobs);
  const ok = probes.filter(p => p.status === "ok").length;
  return {
    probes,
    summary: {
      total: probes.length,
      ok,
      failing: probes.length - ok,
      notConfigured: missing.length,
      billed: probes.filter(p => p.billed).length,
    },
    missing,
    deep,
    ranAt: Date.now(),
  };
}

async function handleKeys(msg: TgMessage, env: Env): Promise<void> {
  if (!msg.from || msg.from.id !== cfg.BOT_OWNER_ID) return;

  const now = Date.now();

  // The bench map is per-isolate and goes stale; without this the "benched"
  // count described this isolate's memory rather than the deployment.
  await refreshDisabledKeysFromKV(env, true);

  // Gemini diagnostics
  const disabled = Object.entries(globalDisabledKeys)
    .filter(([, until]) => Number(until) > now)
    .sort((a, b) => Number(a[1]) - Number(b[1]));

  // Counts alone cannot tell a healthy pool from one where every key has been
  // revoked — the single state this command exists to surface. Each key is now
  // actually checked against Google, using the same prober the dashboard uses
  // so the two surfaces cannot disagree about the same key.
  const geminiProbes = await Promise.all(cfg.GEMINI_KEYS.map((k, i) => probeGeminiKey(k, i + 1)));
  const geminiLines = geminiProbes.length
    ? geminiProbes.map(pr => {
        const icon =
          pr.status === "ok" ? "✅" :
          pr.status === "invalid" ? "❌" :
          pr.status === "forbidden" ? "🚫" :
          pr.status === "rate_limited" ? "⏳" :
          "⚠️";
        // "Benched here but OK upstream" is what tells the owner the local
        // backoff has outlived whatever caused it.
        const bench = pr.benchedUntil
          ? ` · benched ${Math.max(1, Math.round((pr.benchedUntil - now) / 60_000))}m`
          : "";
        return `• <code>${escapeHTML(pr.label)}</code> ${icon}${bench}` +
          (pr.detail ? `\n  ↳ <i>${escapeHTML(pr.detail)}</i>` : "");
      }).join("\n")
    : "• <i>none configured</i>";

  const geminiText =
    `🔷 <b>Gemini</b>\n` +
    `Configured: <b>${cfg.GEMINI_KEYS.length}</b> · Benched: <b>${disabled.length}</b>\n` +
    geminiLines;

  // ElevenLabs diagnostics
  const elevenKeys = [
    env.ELEVENLABS_KEY_1,
    env.ELEVENLABS_KEY_2,
    env.ELEVENLABS_KEY_3,
    env.ELEVENLABS_KEY_4,
    env.ELEVENLABS_KEY_5,
    env.ELEVENLABS_KEY_6,
  ];

  const diagnostics = await Promise.all(
    elevenKeys.map((key, i) =>
      diagnoseElevenLabsKey(key, i + 1, env)
    ),
  );

  const legacyKey = env.ELEVENLABS_API_KEY;

  if (legacyKey && !elevenKeys.some((k) => k === legacyKey)) {
    diagnostics.push(
      await diagnoseElevenLabsKey(legacyKey, 0, env)
    );
  }

  const elevenText = diagnostics
    .map((d) => {
      const label = d.index === 0
        ? "LEGACY"
        : `KEY_${d.index}`;

      if (!d.configured) {
        return `• <code>${label}</code> → ⚪ not configured`;
      }

      const authIcon =
        d.auth === "ok" ? "✅" :
        d.auth === "invalid" ? "❌" :
        d.auth === "forbidden" ? "🚫" :
        d.auth === "rate_limited" ? "⏳" :
        "⚠️";

      const ttsIcon =
        d.tts === "ok" ? "✅" :
        d.tts === "invalid" ? "❌" :
        d.tts === "forbidden" ? "🚫" :
        d.tts === "rate_limited" ? "⏳" :
        d.tts === "quota" ? "💳" :
        d.tts === "not_tested" ? "—" :
        "⚠️";

      const sub = d.subscription
        ? ` · ${d.subscription.tier ?? "?"} · ${d.subscription.characterCount ?? 0}/${d.subscription.characterLimit ?? "?"}`
        : "";

      return (
        `• <code>${label}</code> ` +
        `AUTH ${authIcon} · TTS ${ttsIcon}${escapeHTML(sub)}` +
        (d.error ? `\n  ↳ <i>${escapeHTML(d.error)}</i>` : "")
      );
    })
    .join("\n");

  const text =
    `🔑 <b>API Key Diagnostics</b>\n\n` +
    `${geminiText}\n\n` +
    `🟣 <b>ElevenLabs</b>\n` +
    `${elevenText}`;

  await sendMessage(msg.chat.id, text, {
    reply_to_message_id: msg.message_id,
    parse_mode: "HTML",
    disable_web_page_preview: true,
  });
}

/**
 * Compatibility shim for the retired Telegram-native Control Center.
 *
 * Inline keyboards live in chat history forever, so the owner still has `cc:*`
 * buttons sitting in old messages — and the retired dispatcher answered them by
 * editing the panel into an error string. Each retired area now maps onto the
 * dashboard tab that replaced it, so an old button still lands somewhere useful.
 *
 * `cc:noop` (the page counters) is answered and otherwise ignored: it was never
 * meant to navigate, and the old code turned a stray tap on it into a destroyed
 * panel.
 */
async function handleRetiredControlCenterCallback(cb: TgCallbackQuery, env: Env): Promise<void> {
  void env;
  if (!cb.message || !cb.data) { await answerCb(cb.id); return; }
  if (cb.from.id !== cfg.BOT_OWNER_ID) { await answerCb(cb.id, "🚫", true); return; }

  const area = cb.data.split(":")[1] ?? "";
  if (area === "noop") { await answerCb(cb.id); return; }

  const TAB_FOR_AREA: Record<string, AdminDashboardTab> = {
    ov: "overview", users: "users", user: "users", mem: "users",
    apps: "deployments", req: "requests", keys: "keys",
  };
  await answerCb(cb.id);
  await sendAdminPanel(cb.message.chat.id, cb.message.chat.type, cb.from.id, {
    tab: TAB_FOR_AREA[area] ?? "overview",
    editMessageId: cb.message.message_id,
  });
}

/** Thin horizontal rule shared by the progress panel and other card layouts. */
function panelDivider(): string {
  return `┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈┈\n`;
}
/** نوار پیشرفت ریزدونه (گرانولاریتی یک‌هشتم بلوک) — حرکت نرم به‌جای پرش پله‌ای */
function fineProgressBar(pct: number, size = 12): string {
  const eighths = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉"];
  const clamped = Math.min(100, Math.max(0, pct));
  const totalEighths = Math.round((clamped / 100) * size * 8);
  const fullBlocks = Math.min(size, Math.floor(totalEighths / 8));
  const remainderIdx = fullBlocks < size ? totalEighths % 8 : 0;
  const partial = fullBlocks < size ? eighths[remainderIdx] : "";
  const emptyCount = Math.max(0, size - fullBlocks - (partial ? 1 : 0));
  return "█".repeat(fullBlocks) + partial + "░".repeat(emptyCount);
}
// SECTION: CALLBACK QUERY HANDLER
async function handleCallback(cb: TgCallbackQuery, env: Env): Promise<void> {
  if (!cb.message || !cb.data) { await answerCb(cb.id); return; }

  const { from, message, data } = cb;
  const chat = message.chat;

  // Rate limiting for callbacks
  const now = Date.now();
  const cbLimits = callbackRateLimits.get(from.id) ?? [];
  const recent = cbLimits.filter(t => now - t < 10_000);
  if (recent.length >= 15 && from.id !== cfg.BOT_OWNER_ID) { await answerCb(cb.id, "⏳ Too fast! Wait.", true); return; }
  recent.push(now);
  callbackRateLimits.set(from.id, recent);

  // Maintenance check (skip for admin callbacks)
  if (!data.startsWith("admin_") && !data.startsWith("log_") && !data.startsWith("db_")) {
    const mc = await checkMaintenance(env, from.id);
    if (mc.blocked) { await answerCb(cb.id, "🛠️ Maintenance mode", true); return; }
  }

  // Inert label buttons (page counters). Answering keeps Telegram's spinner from
  // hanging; falling through would let a stray tap reach a real handler.
  if (data === "noop") { await answerCb(cb.id); return; }

  // Live broadcast controls (own namespace — see handleBroadcastControlCallback).
  if (data.startsWith("bcast:")) {
    await handleBroadcastControlCallback(cb, env);
    return;
  }

  // Buttons from the retired Telegram-native Control Center, still present in the
  // owner's chat history. Mapped onto the dashboard tab that replaced each area.
  if (data.startsWith("cc:")) {
    await handleRetiredControlCenterCallback(cb, env);
    return;
  }

  // Language setting (no session needed)
  if (data.startsWith("set_lang_")) {
    const newLang = data.replace("set_lang_", "") as Language;
    const session = await getOrCreateSession(chat, from, env);
    session.language = newLang;
    session.settings.languageSet = true;

    // Update system prompts in all engines
    const ts = Date.now();
    const isGroup = chat.type !== "private";
    for (const eng of ["gemini"] as const) {
      const hist = session.engines[eng].history;
      if (hist.length > 0 && hist[0].parts.length > 0) {
        hist[0].parts[0].text = buildSystemPrompt(eng, from.first_name, isGroup, newLang, from.id, session.userMemories.get(from.id));
        hist[0].timestamp = ts;
      }
    }

    // تغییر زبان یک انتخاب صریح و کم‌تکرار است؛ مثل سوییچ پرسونا باید فوراً و بدون
    // کوالسینگ نوشته شود تا روی ایزوله‌ی بعدی برنگردد به مقدار قبلی.
    await saveSession(session, env, { force: true });
    await saveLanguageSnapshot(chat.id, newLang, env);
    const successMsg = newLang === "fa" ? "✅ زبان به **فارسی** تغییر یافت." : "✅ Language changed to **English**.";
    await answerCb(cb.id, successMsg.replace(/\*\*/g, ""), false);

    const welcomeKey: LangKey = isGroup ? "welcome_group" : "welcome_private";
    const welcomeText = t(newLang, welcomeKey, { name: from.first_name });
    const kb: InlineKeyboard = isGroup
      ? { inline_keyboard: [[btn(t(newLang, "btn_settings"), "group_settings")]] }
      : { inline_keyboard: [[btn(t(newLang, "btn_select_model"), "model_settings")], [btn(t(newLang, "btn_help"), "open_help")], [userDashboardButton(newLang, true)]] };

    await editMessageText(chat.id, message.message_id, welcomeText, { reply_markup: JSON.stringify(validateKeyboard(kb)) });
    return;
  }

  // Load session for most callbacks
  const session = await getOrCreateSession(chat, from, env);

  // ── ROUTER: HOME NAMESPACE ──
  const [ns, action] = data.split(":");

  if (chat.type !== "private") {
    const _pk = `${chat.id}:${message.message_id}`;
    const _excluded = data.startsWith("admin_") || data.startsWith("broadcast_") ||
      data.startsWith("log_") || data.startsWith("db_") || data.startsWith("group_settings") ||
       data.startsWith("gset_");
    if (!_excluded) {
      const _own = panelOwners.get(_pk);
      if (_own) {
        // مالکیت قبلاً در همین ایزوله تأیید شده — دیگر نیازی به خواندن/نوشتن
        // D1 نیست. این تک تغییر، بیشترِ تاخیر حس‌شده روی کلیک‌های پشت‌سرهم
        // منوی شخصیت/پرامپت داخل گروه‌ها را حذف می‌کند (ریشه‌ی اصلی کندی).
        if (_own.u !== from.id && Date.now() - _own.ts < 60 * 60 * 1000) {
          await answerCb(cb.id, session.language === "fa" ? "🔒 این منو برای کاربر دیگری باز شده است." : "🔒 This menu was opened by another user.", true);
          return;
        }
        _own.ts = Date.now();
      } else {
        if (!await claimPanelOwner(chat.id, message.message_id, from.id, env)) {
          await answerCb(cb.id, session.language === "fa" ? "🔒 این منو برای کاربر دیگری باز شده است." : "🔒 This menu was opened by another user.", true);
          return;
        }
        panelOwners.set(_pk, { u: from.id, ts: Date.now() });
      }
      if (panelOwners.size > 3000) {
        const _now = Date.now();
        for (const [k, v] of panelOwners) if (_now - v.ts > 60 * 60 * 1000) panelOwners.delete(k);
      }
    }
  }

  if (ns === "home") {
    if (action === "close") {
      await answerCb(cb.id);
      await deleteMessage(chat.id, message.message_id);
      return;
    }
    if (action === "personas") {
      await answerCb(cb.id);
      const isGrp = chat.type !== "private";
      await editMessageText(chat.id, message.message_id, buildPersonaText(session, from.id, isGrp), {
        reply_markup: JSON.stringify(buildPersonaKeyboard(getEffectivePersonaId(session, from.id, isGrp), session.language, personaAutoAdaptEnabled(session)))
      });
      return;
    }
    if (action === "new_confirm") {
      await answerCb(cb.id);
      await editMessageText(chat.id, message.message_id,
        session.language === "fa" ? "🗑️ *حافظه پاک بشه؟*\n\nتمام تاریخچه گفتگو حذف میشه." : "🗑️ *Clear memory?*\n\nAll chat history will be deleted.",
        { reply_markup: JSON.stringify({ inline_keyboard: [
          [btn(session.language === "fa" ? "✅ بله، پاک کن" : "✅ Yes, clear", "home:new_do"), btn(session.language === "fa" ? "❌ نه" : "❌ No", "home:open")],
        ]})}
      );
      return;
    }
    if (action === "new_do") {
      const isGroup = chat.type !== "private";
      const report = await performCompleteMemoryReset(session, from.id, from, isGroup, env);
      await answerCb(cb.id, session.language === "fa" ? "✅ حافظه کاملاً ریست شد" : "✅ Memory completely reset");
      // The panel edit alone is too subtle to notice, so the itemised receipt is
      // posted as a real message as well.
      await sendMessage(chat.id, buildMemoryResetReceipt(report, session.language, engineDisplayName(session.activeEngine, session.language)), { parse_mode: "HTML" });
      await showHomePanel(chat.id, from, session, env, message.message_id);
      return;
    }
    if (action === "prompt") {
      await answerCb(cb.id);
      await showPromptMenu(chat.id, message.message_id, session, from.id, chat.type !== "private");
      return;
    }
    if (action === "language") {
      await answerCb(cb.id);
      await editMessageText(chat.id, message.message_id,
        `🌐 *Language / انتخاب زبان*\n\nCurrent: **${session.language === "fa" ? "فارسی 🇮🇷" : "English 🇺🇸"}**`,
        { reply_markup: JSON.stringify({ inline_keyboard: [
          [btn("🇮🇷  فارسی", "home:lang_fa"), btn("🇺🇸  English", "home:lang_en")],
          [btn("🇸🇦  العربية", "home:lang_ar")],
          [btn("🔙", "home:open")],
        ]})}
      );
      return;
    }
    if (action === "lang_fa" || action === "lang_en" || action === "lang_ar") {
      const targetLang = action.replace("lang_", "") as Language;
      session.language = targetLang;
      await saveSession(session, env, { force: true });
      await saveLanguageSnapshot(chat.id, targetLang, env);
      await answerCb(cb.id, targetLang === "fa" ? "فارسی" : targetLang === "ar" ? "العربية" : "English");
      await showHomePanel(chat.id, from, session, env, message.message_id);
      return;
    }
    if (action === "help") {
      await answerCb(cb.id);
      await handleHelp(message, env, message.message_id);
      return;
    }
    if (action === "vip") {
      await answerCb(cb.id);
      const contact = cfg.VIP_CONTACT.trim();
      const url = contact.startsWith("http") ? contact : `https://t.me/${contact.replace(/^@/, "")}`;
      const text = session.language === "fa"
        ? `👑 *دسترسی VIP*\n\n` +
          `با ارتقا به VIP سقف‌های روزانه‌ی شما به این مقدار افزایش پیدا می‌کند:\n\n` +
          `💬 پیام: **${cfg.VIP_MESSAGE_LIMIT}** در روز (به‌جای ${cfg.MESSAGE_LIMIT})\n` +
          `🎨 ساخت تصویر: **${cfg.VIP_IMAGE_LIMIT}** در روز (به‌جای ${cfg.IMAGE_LIMIT})\n` +
          `🖌️ ویرایش تصویر: **${cfg.VIP_EDIT_LIMIT}** در روز (به‌جای ${cfg.EDIT_LIMIT})\n` +
          `🎤 ویس: **${cfg.VIP_VOICE_LIMIT}** در روز (به‌جای ${cfg.VOICE_LIMIT})\n` +
          `🌐 وب‌اپ: **${cfg.VIP_WEBAPP_LIMIT}** در روز (به‌جای ${cfg.WEBAPP_LIMIT})\n` +
          `✅ تحلیل فایل و عکس در گروه‌ها\n` +
          `✅ اولویت در صف پردازش\n\n` +
          `_توجه: این سقف‌ها هر شبانه‌روز ریست می‌شوند؛ VIP یعنی ظرفیت خیلی بالاتر، نه مصرف بی‌نهایت._\n\n` +
          `برای خرید تماس بگیر:`
        : `👑 *VIP Access*\n\n` +
          `Upgrading to VIP raises your daily limits to:\n\n` +
          `💬 Messages: **${cfg.VIP_MESSAGE_LIMIT}**/day (vs ${cfg.MESSAGE_LIMIT})\n` +
          `🎨 Image generation: **${cfg.VIP_IMAGE_LIMIT}**/day (vs ${cfg.IMAGE_LIMIT})\n` +
          `🖌️ Image editing: **${cfg.VIP_EDIT_LIMIT}**/day (vs ${cfg.EDIT_LIMIT})\n` +
          `🎤 Voice: **${cfg.VIP_VOICE_LIMIT}**/day (vs ${cfg.VOICE_LIMIT})\n` +
          `🌐 Web apps: **${cfg.VIP_WEBAPP_LIMIT}**/day (vs ${cfg.WEBAPP_LIMIT})\n` +
          `✅ File & image analysis in groups\n` +
          `✅ Priority processing\n\n` +
          `_Note: limits reset every 24h; VIP means much higher capacity, not infinite usage._\n\n` +
          `Contact to upgrade:`;
      await editMessageText(chat.id, message.message_id, text, {
        reply_markup: JSON.stringify({ inline_keyboard: [
          [urlBtn("💳 خرید / Purchase", url)],
          [btn("🔙", "home:open")],
        ]})
      });
      return;
    }
    if (action === "open") {
      await answerCb(cb.id);
      await showHomePanel(chat.id, from, session, env, message.message_id);
      return;
    }
  }

  // Group admin check for settings actions
  const isSettingsAction = ["group_settings", "gset_"].some(p => data.startsWith(p));
  if (chat.type !== "private" && isSettingsAction) {
    if (!await isUserAdmin(from.id, chat.id)) {
      await answerCb(cb.id, "🚫 فقط مالک ربات یا مالک گروه مجاز است.", true); return;
    }
  }

  if (data.startsWith("cancel_task_")) {
    const cancelToken = data.replace("cancel_task_", "");
    if(cancelToken.startsWith("build_")){
      const job=await env.DB.prepare("SELECT user_id,chat_id FROM scheduled_jobs WHERE id=?").bind(cancelToken.slice(6)).first<{user_id:number;chat_id:number}>();
      if(!job){await answerCb(cb.id,"This build is no longer queued.",true);return;}
      if(job.chat_id!==chat.id||(job.user_id!==from.id&&from.id!==cfg.BOT_OWNER_ID)){await answerCb(cb.id,"Only the requester can cancel this build.",true);return;}
    }

    // ذخیره وضعیت لغو برای ۵ دقیقه — این کلید مستقل از msgId است، پس حتی اگر پیام
    // حین اجرا عوض شده باشد (حالت گیف انیمیشنی) باز هم به‌درستی شناسایی می‌شود.
    await env.SESSIONS.put(`cancelled_task:${cancelToken}`, "true", { expirationTtl: 300 });
    cancellationReads.set(cancelToken,{until:Date.now()+300000,value:true});
    if(cancellationReads.size>500)cancellationReads.delete(cancellationReads.keys().next().value!);
    if(cancelToken.startsWith("build_"))await env.DB.prepare("DELETE FROM scheduled_jobs WHERE id=?").bind(cancelToken.slice(6)).run();
    await answerCb(cb.id, session.language === "fa" ? "🛑 عملیات لغو شد." : "🛑 Task cancelled.", true);

    // پیام پیشرفت (چه متنی، چه گیف/کپشن‌دار) به‌طور کامل حذف می‌شود — بدون
    // نوشتن هیچ متن «لغو شد» جایگزین، تا چت تمیز بماند. deleteMessage روی هر
    // دو نوع پیام (متنی یا مدیا با کپشن) یکسان کار می‌کند.
    await deleteMessage(chat.id, message.message_id).catch(() => {});

    activeProgressMessages.delete(chat.id);
    return;
  }

  // ── Model selection ──
  if (data.startsWith("set_model_")) {
    // Nova is the only agent — no backend switching
    await answerCb(cb.id, "✅ Nova is your AI agent");
    return;
  }

  // ── 🌐 Web Search Source ──

  if (data === "retry_last_msg") {
    const originalMsg = message.reply_to_message;
    if (!originalMsg) {
      await answerCb(cb.id, session.language === "fa" ? "❌ پیام اصلی یافت نشد." : "❌ Original message not found.", true);
      return;
    }
    await answerCb(cb.id, session.language === "fa" ? "🔄 در حال تلاش مجدد..." : "🔄 Retrying...");
    
    // پاک کردن پیام خطا جهت حفظ تمیزی چت
    await deleteMessage(chat.id, message.message_id).catch(() => {});
    
    // فعال‌سازی مجدد لوله پردازش بر اساس نوع پیام ورودی قبلی
    if (originalMsg.voice) {
      await handleVoiceMessage(originalMsg, env);
    } else if (originalMsg.photo || originalMsg.document || originalMsg.animation || originalMsg.video) {
      await handleMediaMessage(originalMsg, env);
    } else if (originalMsg.sticker) {
      await handleStickerMessage(originalMsg, env);
    } else if (originalMsg.text) {
      await handleTextMessage(originalMsg, env);
    }
    return;
  }

  // ── 📎 ارسال عکس بصورت فایل (بدون فشرده‌سازی) ──
if (data.startsWith("img_asfile_")) {
    const imgRef = data.replace("img_asfile_", "");
    const imgBuffer = await getMediaBlob(env, imgRef);
    if (imgBuffer) {
        const form = new FormData();
        form.append("chat_id", String(chat.id));
        form.append("document", new Blob([imgBuffer], { type: "image/png" }), `nova_${generateId()}.png`);
        form.append("caption", session.language === "fa"
            ? "📎 نسخه فایل (بدون فشرده‌سازی)"
            : "📎 File version (uncompressed)");
        form.append("reply_to_message_id", String(message.message_id));
        await fetchWithTimeout(`${API_URL}/sendDocument`, { method: "POST", body: form }, 30_000);
        await answerCb(cb.id, session.language === "fa" ? "📎 ارسال شد" : "📎 Sent");
    } else {
        await answerCb(cb.id, session.language === "fa" ? "❌ عکس منقضی شده" : "❌ Image expired", true);
    }
    return;
}

// ── 🔄 ساخت دوباره عکس ──
if (data.startsWith("img_regen_")) {
    const imgRef = data.replace("img_regen_", "");
    const savedPrompt = await env.SESSIONS.get(`media_prompt:${imgRef}`, "text");
    if (!savedPrompt) {
        await answerCb(cb.id, session.language === "fa" ? "❌ پرامپت منقضی شده" : "❌ Prompt expired", true);
        return;
    }
    await answerCb(cb.id, session.language === "fa" ? "🔄 در حال ساخت..." : "🔄 Generating...");

    const limitCheck = await checkDailyLimitWithUser(session, from, "image", env);
    if (!limitCheck.allowed) {
        await sendMessage(chat.id, limitCheck.message!, { reply_to_message_id: message.message_id });
        return;
    }

    const procMsg = await sendMessage(chat.id,
        session.language === "fa" ? "⏳ در حال رندر تصویر..." : "⏳ Rendering...",
        { reply_to_message_id: message.message_id });
    try {
        const img = await withTimeout(
            generateImageCF(savedPrompt, cfg.AI_IMAGE_MODELS[0], env),
            105_000, "Timeout"
        );
        if (img) {
            await incrementUsageWithUser(session, from, "image", env);
            const newRef = `novaimg_${generateId()}`;
            if ((await putMediaBlob(env, newRef, bytesToArrayBuffer(img), "image/png")).ok) {
              await env.SESSIONS.put(`media_prompt:${newRef}`, savedPrompt, { expirationTtl: 7200 });
            }
            const modelName = getShortModelName(cfg.AI_IMAGE_MODELS[0]);
            const caption = `<blockquote expandable>${savedPrompt}</blockquote>\n<b>Model:</b> <code>${modelName}</code>`;
            const resendKb: InlineKeyboard = {
                inline_keyboard: [[
                    btn(session.language === "fa" ? "🔄 ساخت دوباره" : "🔄 Regenerate", `img_regen_${newRef}`),
                    btn(session.language === "fa" ? "📎 ارسال بصورت فایل" : "📎 Send as File", `img_asfile_${newRef}`),
                ]]
            };
            await sendPhoto(chat.id, img, caption, {
                reply_to_message_id: message.message_id,
                parse_mode: "HTML",
                reply_markup: JSON.stringify(resendKb),
            });
            await deleteMessage(chat.id, procMsg.message_id).catch(() => {});
        }
    } catch (e) {
        logger.warn(`img_regen failed: ${e instanceof Error ? e.message : e}`);
        await editMessageText(chat.id, procMsg.message_id,
            session.language === "fa" ? "❌ ساخت دوباره ناموفق بود." : "❌ Regeneration failed."
        ).catch(() => {});
    }
    return;
}

if (data === "open_language") {
    await answerCb(cb.id);
    await editMessageText(chat.id, message.message_id,
      `🌐 *Language / انتخاب زبان*\n\nCurrent: **${session.language === "fa" ? "فارسی 🇮🇷" : session.language === "ar" ? "العربية 🇸🇦" : "English 🇺🇸"}**`,
      { reply_markup: JSON.stringify({ inline_keyboard: [
        [btn("🇮🇷  فارسی", "set_lang_fa"), btn("🇺🇸  English", "set_lang_en")],
        [btn("🇸🇦  العربية", "set_lang_ar")],
        [userDashboardButton(session.language, chat.type === "private")],
        [btn("🔙", "home:open")],
      ]})}
    );
    return;
  }

  if (data === "new_chat_confirm") {
    await answerCb(cb.id);
    await editMessageText(chat.id, message.message_id,
      session.language === "fa" ? "🗑️ *حافظه پاک بشه؟*\n\nتمام تاریخچه گفتگو حذف میشه." : "🗑️ *Clear memory?*\n\nAll chat history will be deleted.",
      { reply_markup: JSON.stringify({ inline_keyboard: [
        [btn(session.language === "fa" ? "✅ بله، پاک کن" : "✅ Yes, clear", "do_new_chat"), btn(session.language === "fa" ? "❌ نه" : "❌ No", "home:open")],
      ]})}
    );
    return;
  }

  if (data === "do_new_chat") {
    const isGroup = chat.type !== "private";
    const report = await performCompleteMemoryReset(session, from.id, from, isGroup, env);
    await answerCb(cb.id, session.language === "fa" ? "✅ حافظه کاملاً ریست شد" : "✅ Memory completely reset");
    await sendMessage(chat.id, buildMemoryResetReceipt(report, session.language, engineDisplayName(session.activeEngine, session.language)), { parse_mode: "HTML" });
    await showHomePanel(chat.id, from, session, env, message.message_id);
    return;
  }

  if (data === "show_vip_info") {
    await answerCb(cb.id);
    const contact = cfg.VIP_CONTACT.trim();
    const url = contact.startsWith("http") ? contact : `https://t.me/${contact.replace(/^@/, "")}`;
    const text = session.language === "fa"
        ? `👑 *دسترسی VIP*\n\n` +
          `با ارتقا به VIP سقف‌های روزانه‌ی شما به این مقدار افزایش پیدا می‌کند:\n\n` +
          `💬 پیام: **${cfg.VIP_MESSAGE_LIMIT}** در روز (به‌جای ${cfg.MESSAGE_LIMIT})\n` +
          `🎨 ساخت تصویر: **${cfg.VIP_IMAGE_LIMIT}** در روز (به‌جای ${cfg.IMAGE_LIMIT})\n` +
          `🖌️ ویرایش تصویر: **${cfg.VIP_EDIT_LIMIT}** در روز (به‌جای ${cfg.EDIT_LIMIT})\n` +
          `🎤 ویس: **${cfg.VIP_VOICE_LIMIT}** در روز (به‌جای ${cfg.VOICE_LIMIT})\n` +
          `🌐 وب‌اپ: **${cfg.VIP_WEBAPP_LIMIT}** در روز (به‌جای ${cfg.WEBAPP_LIMIT})\n` +
          `✅ تحلیل فایل و عکس در گروه‌ها\n` +
          `✅ اولویت در صف پردازش\n\n` +
          `_توجه: این سقف‌ها هر شبانه‌روز ریست می‌شوند؛ VIP یعنی ظرفیت خیلی بالاتر، نه مصرف بی‌نهایت._\n\n` +
          `برای خرید تماس بگیر:`
        : `👑 *VIP Access*\n\n` +
          `Upgrading to VIP raises your daily limits to:\n\n` +
          `💬 Messages: **${cfg.VIP_MESSAGE_LIMIT}**/day (vs ${cfg.MESSAGE_LIMIT})\n` +
          `🎨 Image generation: **${cfg.VIP_IMAGE_LIMIT}**/day (vs ${cfg.IMAGE_LIMIT})\n` +
          `🖌️ Image editing: **${cfg.VIP_EDIT_LIMIT}**/day (vs ${cfg.EDIT_LIMIT})\n` +
          `🎤 Voice: **${cfg.VIP_VOICE_LIMIT}**/day (vs ${cfg.VOICE_LIMIT})\n` +
          `🌐 Web apps: **${cfg.VIP_WEBAPP_LIMIT}**/day (vs ${cfg.WEBAPP_LIMIT})\n` +
          `✅ File & image analysis in groups\n` +
          `✅ Priority processing\n\n` +
          `_Note: limits reset every 24h; VIP means much higher capacity, not infinite usage._\n\n` +
          `Contact to upgrade:`;
    await editMessageText(chat.id, message.message_id, text, {
      reply_markup: JSON.stringify({ inline_keyboard: [
        [urlBtn("💳 خرید / Purchase", url)],
        [btn("🔙", "home:open")],
      ]})
    });
    return;
  }

  if (data === "model_settings" || data === "active_model_settings") {
    await answerCb(cb.id);
    await showHomePanel(chat.id, from, session, env, message.message_id);
    return;
  }

  // ── Custom prompt menu ──
  if (data === "custom_prompt_menu") {
    await answerCb(cb.id);
    await showPromptMenu(chat.id, message.message_id, session, from.id, chat.type !== "private");
    return;
  }

  // Tapping a persona (or the legacy `ℹ️` button on an older message) only opens
  // its detail card — nothing is switched here. `persona_info_` is kept as an
  // alias so inline keyboards already sitting in users' chat histories still work.
  if (data.startsWith("persona_select_") || data.startsWith("persona_info_")) {
    const personaId = data.replace(/^persona_(select|info)_/, "");
    if (!PERSONAS[personaId]) { await answerCb(cb.id, "❌", true); return; }
    await answerCb(cb.id);
    await showPersonaCard(chat.id, message.message_id, personaId, session, from.id, chat.type !== "private");
    return;
  }

  if (data.startsWith("persona_confirm_")) {
    const personaId = data.replace("persona_confirm_", "");
    const persona = PERSONAS[personaId];
    if (!persona) { await answerCb(cb.id, "❌", true); return; }

    const isGroup = chat.type !== "private";
    // A confirm tap is the user's explicit choice, so it pins the persona: agentic
    // adaptation must not quietly undo what someone just deliberately selected.
    const applied = await applyPersona(session, personaId, from, isGroup, env, { pin: true });

    if (!applied) {
      await answerCb(cb.id, session.language === "fa" ? "⚠️ این شخصیت هنوز فعال نشده" : "⚠️ Persona not configured yet", true);
      return;
    }

    await answerCb(cb.id, session.language === "fa"
      ? (isGroup ? "✅ شخصیت (فقط برای شما) تغییر کرد" : "✅ شخصیت تغییر کرد")
      : (isGroup ? "✅ Your persona changed" : "✅ Persona changed"));

    await editMessageText(
      chat.id, message.message_id,
      buildPersonaText(session, from.id, isGroup),
      { reply_markup: JSON.stringify(buildPersonaKeyboard(personaId, session.language, personaAutoAdaptEnabled(session))) }
    );
    return;
  }

  if (data === "open_personas") {
    await answerCb(cb.id);
    const isGrp3 = chat.type !== "private";
    await editMessageText(
      chat.id, message.message_id,
      buildPersonaText(session, from.id, isGrp3),
      { reply_markup: JSON.stringify(buildPersonaKeyboard(getEffectivePersonaId(session, from.id, isGrp3), session.language, personaAutoAdaptEnabled(session))) }
    );
    return;
  }

  // Switches between the two persona modes. Manual (default) means only a confirm
  // tap can change persona; auto-adapt lets Nova adjust on its own under the
  // cooldown/streak brakes.
  //
  // Enabling it clears the pin a previous confirmation left behind. Without that,
  // `personaSwitchNeedsConfirmation` would keep routing this chat down the manual
  // path forever and the toggle would look broken. Opting into adaptation is a
  // newer and more explicit instruction than the earlier pin, so it wins. Turning
  // it back off needs no cleanup — manual mode asks for confirmation regardless.
  if (data === "persona_auto_toggle") {
    const isGrpT = chat.type !== "private";
    const next = !personaAutoAdaptEnabled(session);
    session.settings = session.settings ?? {
      autoCleanHistory: true, typingIndicator: true, groupResponseMode: "mention_only",
      personalizedResponses: true, contextAwareness: true, languageSet: false,
    };
    session.settings.personaAutoAdapt = next;
    if (next) {
      const scope = getPersonaScopeState(session, from.id, isGrpT);
      if (scope.pinned) setPersonaScopeState(session, from.id, isGrpT, { ...scope, pinned: false });
    }
    await saveSession(session, env, { force: true });

    await answerCb(cb.id, session.language === "fa"
      ? (next ? "🤖 تطبیق خودکار روشن شد" : "🔒 تطبیق خودکار خاموش شد")
      : (next ? "🤖 Auto-adapt enabled" : "🔒 Auto-adapt disabled"));

    await editMessageText(
      chat.id, message.message_id,
      buildPersonaText(session, from.id, isGrpT),
      { reply_markup: JSON.stringify(buildPersonaKeyboard(getEffectivePersonaId(session, from.id, isGrpT), session.language, next)) }
    );
    return;
  }

  if (data.startsWith("reset_prompt_")) {
    const isGroup = chat.type !== "private";
    if (isGroup) {
      session.userCustomPrompts?.delete(from.id);
      session.userCustomPromptSource?.delete(from.id);
    } else {
      session.customPrompts.gemini = null;
      session.customPromptSource = undefined;
    }
    await saveSession(session, env, { force: true }); // تنظیم عمدی — فوری ذخیره شود
    await saveIdentitySnapshot(session, from.id, isGroup, env);
    await answerCb(cb.id, session.language === "fa" ? "پرامپت دستی ریست شد" : "Custom prompt reset");
    await showPromptMenu(chat.id, message.message_id, session, from.id, chat.type !== "private");
    return;
  }

  if (data === "show_prompts") {
    const sLang = session.language;
    const def = t(sLang, "prompt_default");
    const isGroup = chat.type !== "private";
    const source = isGroup ? session.userCustomPromptSource?.get(from.id) : session.customPromptSource;
    const userCustom = isGroup ? session.userCustomPrompts?.get(from.id) : session.customPrompts.gemini;
    const persona = getPersona(session.currentPersonaId);
    const personaName = sLang === "fa" ? persona.nameFA : persona.nameEN;
    const personaTag = sLang === "fa" ? persona.tagFA : persona.tagEN;

    let text: string;
    if (userCustom && source === "manual") {
      text = `📋 **${sLang === "fa" ? "پرامپت شخصی شما" : "Your Custom Prompt"}:**\n\n\`${userCustom}\``;
    } else if (userCustom) {
      text = sLang === "fa"
        ? `🎭 **شخصیت فعال:** ${persona.emoji} ${personaName}\n_${personaTag}_\n\n🔒 پرامپت داخلی شخصیت‌های از پیش تعریف‌شده به دلایل امنیتی نمایش داده نمی‌شود.\n\nبرای تنظیم پرامپت دستی خودتان از دستور زیر استفاده کنید:\n\`/setprompt nova [متن شما]\``
        : `🎭 **Active persona:** ${persona.emoji} ${personaName}\n_${personaTag}_\n\n🔒 Preset persona prompts are not shown for security reasons.\n\nTo set your own custom prompt, use:\n\`/setprompt nova [your text]\``;
    } else {
      text = `📋 **${sLang === "fa" ? "پرامپت شخصی شما" : "Your Custom Prompt"}:**\n\n\`${def}\``;
    }

    await answerCb(cb.id);
    await editMessageText(chat.id, message.message_id, text, { reply_markup: JSON.stringify({ inline_keyboard: [[btn(t(sLang, "btn_back"), "custom_prompt_menu")]] }) });
    return;
  }

  // ── Group settings ──
  if (data === "group_settings") {
    await answerCb(cb.id);
    await showGroupSettings(chat.id, message.message_id, session, env);
    return;
  }

  if (data === "gset_enabled") {
    if (chat.type === "private" || !await isUserAdmin(from.id, chat.id)) {
      await answerCb(cb.id, session.language === "fa" ? "🚫 فقط مدیران گروه مجاز هستند." : "🚫 Only group administrators can change this.", true);
      return;
    }
    const cur = await getGroupConfig(chat.id, env);
    const next = await setGroupConfig(chat.id, { enabled: !cur.enabled }, env);
    if(next.enabled)await clearDeliveryFailure(env.DB,chat.id);
    await answerCb(cb.id, session.language === "fa" ? (next.enabled ? "✅ پاسخ‌گویی روشن شد" : "⛔️ پاسخ‌گویی متوقف شد") : (next.enabled ? "✅ Replies enabled" : "⛔️ Replies disabled"), true);
    await showGroupSettings(chat.id, message.message_id, session, env);
    return;
  }

  if (data === "gset_heavy") {
    if (chat.type === "private" || !await isUserAdmin(from.id, chat.id)) {
      await answerCb(cb.id, session.language === "fa" ? "🚫 فقط مدیران گروه مجاز هستند." : "🚫 Only group administrators can change this.", true);
      return;
    }
    const cur = await getGroupConfig(chat.id, env);
    const next = await setGroupConfig(chat.id, { allowHeavy: !cur.allowHeavy }, env);
    await answerCb(cb.id, session.language === "fa" ? (next.allowHeavy ? "✅ کارهای سنگین مجاز شد" : "⛔️ کارهای سنگین غیرمجاز شد") : (next.allowHeavy ? "✅ Heavy tasks on" : "⛔️ Heavy tasks off"), true);
    await showGroupSettings(chat.id, message.message_id, session, env);
    return;
  }

  // ── Help sections ──
  if (data === "open_help") {
    await answerCb(cb.id);
    await handleHelp(message, env, message.message_id);
    return;
  }

  if (data === "close_help") {
    await answerCb(cb.id);
    await deleteMessage(chat.id, message.message_id);
    return;
  }

  if (data === "help_back") {
    await answerCb(cb.id);
    await handleHelp(message, env, message.message_id);
    return;
  }

  // `open_admin` is the callback fallback emitted by `adminPanelButton` in groups
  // (where Telegram forbids `web_app` buttons) and by keyboards already sitting in
  // chat history. `admin_back_to_main` is the retired Control Center's home button.
  if (data === "admin_back_to_main" || data === "open_admin") {
    if (from.id !== cfg.BOT_OWNER_ID) { await answerCb(cb.id, "🚫", true); return; }
    await answerCb(cb.id);
    void env;
    await sendAdminPanel(chat.id, chat.type, from.id, { editMessageId: message.message_id });
    return;
  }

  if (data === "open_my_dashboard") {
    // Degraded shape of the dashboard button (keyboards from before the isolate
    // learned its origin). Re-resolves the best current shape instead of
    // assuming why the fallback was sent.
    await handleOpenDashboardCb(chat.id, chat.type === "private", cb.id);
    return;
  }

  // ── Hosted deployment controls ──────────────────────────────────────────
  // "Run on Server" is how hosting starts: the source is delivered first, and
  // the deployment (with its expiry) is created only when the owner asks for it.
  if (data.startsWith("deploy:") || data.startsWith("appext:") || data.startsWith("appdel:")) {
    const [action, ...rest] = data.split(":");
    const appName = rest.join(":").replace(/[^a-z0-9_-]/g, "");
    const isOwner = from.id === cfg.BOT_OWNER_ID;
    const session = await getOrCreateSession(chat, from, env);
    const isPro = Boolean(session.vipStatus) || isOwner;
    const lang = session.language;
    const fa = lang === "fa";
    if (!appName) { await answerCb(cb.id, "🚫", true); return; }
    const record = await readDeploymentRow(env, appName).catch(() => null);
    // Ownership is checked from the stored row, never from the callback payload.
    if (!record || (!canManage(record, from.id) && !isOwner)) {
      await answerCb(cb.id, fa ? "🚫 دسترسی نداری" : "🚫 Not your project", true);
      return;
    }
    try {
      if (action === "deploy") {
        const result = await activateDeployment(env, appName, record.ownerId, isPro);
        if (!result.ok) {
          await answerCb(cb.id, fa ? "❌ اجرا نشد" : "❌ Could not deploy", true);
          await sendMessage(chat.id, fa
            ? `❌ میزبانی اجرا نشد (${result.reason}). سورس پروژه در فایل ارسالی موجود است.`
            : `❌ Deployment failed (${result.reason}). The source is still in the file already sent.`,
            { reply_to_message_id: message.message_id }).catch(() => {});
          return;
        }
        const facts = factsFromMeta(result.meta);
        await answerCb(cb.id, fa ? "✅ اجرا شد" : "✅ Live");
        await sendMessage(chat.id, [
          fa ? "🚀 **میزبانی فعال شد.**" : "🚀 **Hosting is live.**",
          `🔗 ${result.url}`,
          fa ? `⏰ انقضا: ${new Date(facts.expiresAt!).toLocaleString("fa-IR")}` : `⏰ Expires: ${new Date(facts.expiresAt!).toLocaleString("en-US")}`,
          fa ? `⌛️ باقی‌مانده: ${formatRemaining(facts.remainingMs, lang)}` : `⌛️ Remaining: ${formatRemaining(facts.remainingMs, lang)}`,
          fa ? `ℹ️ میزبانی موقت است؛ بعد از انقضا لینک حذف می‌شود.` : `ℹ️ Hosting is temporary; the link disappears when it expires.`,
        ].join("\n"), {
          reply_to_message_id: message.message_id,
          reply_markup: JSON.stringify({ inline_keyboard: [[
            chat.type === "private" ? { text: fa ? "▶️ باز کردن" : "▶️ Open", web_app: { url: result.url } } : { text: fa ? "▶️ باز کردن" : "▶️ Open", url: result.url },
            btn(fa ? "🗑 حذف میزبانی" : "🗑 Delete hosting", `appdel:${appName}`),
            ...(facts.canExtend ? [btn(fa ? "⏳ تمدید" : "⏳ Extend", `appext:${appName}`)] : []),
          ]] }),
        }).catch(() => {});
        return;
      }
      if (action === "appext") {
        const result = await extendWebApp(env, appName, record.ownerId);
        if (!result.ok) {
          const why = result.reason === "plan"
            ? (fa ? "تمدید فقط برای پلن Pro است." : "Extension is a Pro feature.")
            : result.reason === "exhausted"
              ? (fa ? "سقف تمدیدها پر شده." : "The extension limit is reached.")
              : (fa ? "این میزبانی فعال نیست." : "This deployment is not live.");
          await answerCb(cb.id, why, true);
          return;
        }
        const facts = factsFromMeta(result.meta!);
        await answerCb(cb.id, fa ? "⏳ تمدید شد" : "⏳ Extended");
        await sendMessage(chat.id, fa
          ? `⏳ تمدید شد. اکنون ${formatRemaining(facts.remainingMs, lang)} باقی مانده (${facts.extensionsLeft} تمدید دیگر).`
          : `⏳ Extended. ${formatRemaining(facts.remainingMs, lang)} remaining (${facts.extensionsLeft} extension(s) left).`,
          { reply_to_message_id: message.message_id }).catch(() => {});
        return;
      }
      // appdel — ownership was already proven above; pass the row's owner so an
      // owner-initiated delete is what the store checks.
      await deleteWebApp(appName, isOwner ? record.ownerId : from.id, env);
      await answerCb(cb.id, fa ? "🗑 حذف شد" : "🗑 Deleted");
      await sendMessage(chat.id, fa
        ? `🗑 میزبانی «${appName}» حذف شد و لینک عمومی از کار افتاد. سورس پروژه نزد توست.`
        : `🗑 Hosting for "${appName}" was deleted and the public link no longer resolves. Your source is untouched.`,
        { reply_to_message_id: message.message_id }).catch(() => {});
      return;
    } catch (e) {
      logger.error("Deployment callback failed", e);
      await answerCb(cb.id, fa ? "❌ خطا" : "❌ Failed", true);
      return;
    }
  }

  if (data.startsWith("myapp_del_")) {
  const rest = data.replace("myapp_del_", "");
  const lastUnderscore = rest.lastIndexOf("_");
  const appName = rest.slice(0, lastUnderscore);
  const page = parseInt(rest.slice(lastUnderscore + 1), 10) || 0;
  const meta = (await listWebApps(env)).find(a => a.name === appName);
  if (!meta || (meta.createdBy !== from.id && from.id !== cfg.BOT_OWNER_ID)) {
    await answerCb(cb.id, "🚫", true); return;
  }
  await deleteWebApp(appName, from.id, env);
  await answerCb(cb.id, "🗑️ Deleted");
  await handleMyApps(message, env, page, message.message_id);
  return;
}
if (data.startsWith("myapps_page_")) {
  const page = parseInt(data.replace("myapps_page_", ""), 10) || 0;
  await answerCb(cb.id);
  await handleMyApps(message, env, page, message.message_id);
  return;
}

  // ── DB callbacks ──
  if (data.startsWith("db_")) {
    if (from.id !== cfg.BOT_OWNER_ID) { await answerCb(cb.id, "🚫", true); return; }
    if (data === "db_cancel_delete") { await answerCb(cb.id, "Cancelled"); await deleteMessage(chat.id, message.message_id); return; }
    if (data.startsWith("db_confirm_delete_")) {
      const uid = parseInt(data.replace("db_confirm_delete_", ""));
      await env.SESSIONS.delete(`session:${uid}`);
      dropSessionMemory(uid);
      await answerCb(cb.id, "✅ Deleted");
      await editMessageText(chat.id, message.message_id, `✅ Session for \`${uid}\` deleted.`);
    }
    return;
  }

  if (data.startsWith("imgnext_")) {
    const searchId = data.replace("imgnext_", "");
    const raw = await env.SESSIONS.get(`imgsearch:${searchId}`, "json") as { query: string; images: string[]; index: number } | null;
    if (!raw) { await answerCb(cb.id, session.language === "fa" ? "⏱️ این جستجو منقضی شده." : "⏱️ Search expired.", true); return; }
    raw.index++;
    let nextUrl: string;
    if (raw.index < raw.images.length) {
      nextUrl = raw.images[raw.index];
    } else {
      try {
        const fresh = await searchGoogleImages(raw.query, 6);
        raw.images = fresh;
        raw.index = 0;
        nextUrl = fresh[0];
      } catch {
        await answerCb(cb.id, session.language === "fa" ? "❌ نتیجه بیشتری پیدا نشد." : "❌ No more results.", true);
        return;
      }
    }
    await env.SESSIONS.put(`imgsearch:${searchId}`, JSON.stringify(raw), { expirationTtl: 600 });
    await answerCb(cb.id, "🔄");
    const isGif = nextUrl.toLowerCase().includes(".gif");
    const kb: InlineKeyboard = { inline_keyboard: [[
      btn(session.language === "fa" ? "🔄 جستجوی دوباره" : "🔄 Search Again", `imgnext_${searchId}`)
    ]] };
    try {
      if (isGif) await sendAnimation(chat.id, nextUrl, raw.query, { reply_markup: JSON.stringify(kb) });
      else await sendPhoto(chat.id, nextUrl, raw.query, { reply_markup: JSON.stringify(kb) });
    } catch {
      await sendMessage(chat.id, session.language === "fa" ? `⚠️ لینک: ${nextUrl}` : `⚠️ Link: ${nextUrl}`);
    }
    return;
  }
  
  await answerCb(cb.id, "Unknown action", true);
}

async function showHomePanel(
  chatId: number,
  user: TgUser,
  session: ChatSession,
  env: Env,
  editMsgId?: number
): Promise<void> {
  const lang = session.language;
  const isOwner = user.id === cfg.BOT_OWNER_ID;
  const persona = getPersona(getEffectivePersonaId(session, user.id, session.type !== "private"));
  
  const limSession = session.type !== "private" && !session.vipStatus
    ? await getOrCreateSession({ id: user.id, type: "private" }, user, env)
    : session;
  
  const used = limSession.dailyLimits;
  const lim = { msg: cfg.MESSAGE_LIMIT, img: cfg.IMAGE_LIMIT, voice: cfg.VOICE_LIMIT };
  const isVip = session.vipStatus || isOwner;
  
  const renderBar = (u: number, l: number) => {
    if (isVip) return "<code>[▰▰▰▰▰▰▰▰]</code> 💎 VIP";
    const ratio = l > 0 ? Math.min(u / l, 1) : 0;
    const filled = Math.round(ratio * 8);
    return `<code>[${"▰".repeat(filled)}${"▱".repeat(8 - filled)}]</code> ${u}/${l}`;
  };

  const personaName = lang === "fa" ? persona.nameFA : lang === "ar" ? persona.nameFA : persona.nameEN;
  const personaTag = lang === "fa" ? persona.tagFA : lang === "ar" ? persona.tagFA : persona.tagEN;

  const tier = isOwner 
    ? (lang === "fa" ? "👑 مدیر کل" : lang === "ar" ? "👑 المسؤول" : "👑 Owner") 
    : isVip 
    ? (lang === "fa" ? "💎 اشتراک ویژه" : lang === "ar" ? "💎 اشتراك VIP" : "💎 VIP Member") 
    : (lang === "fa" ? "🆓 کاربر رایگان" : lang === "ar" ? "🆓 مستخدم مجاني" : "🆓 Free User");

  let text = "";
  if (lang === "fa") {
    text = `╭━━━━━━━━━━━━━━━━━━━━━╮\n` +
           `┃ 🌌 <b>مرکز فرماندهی نوا</b>\n` +
           `┃ <i>نسخه ${BOT_VERSION} · هسته هوشمند</i>\n` +
           `╰━━━━━━━━━━━━━━━━━━━━━╯\n\n` +
           `👤 <b>کاربر:</b> <code>${escapeHTML(user.first_name)}</code> (${tier})\n` +
           `${persona.emoji} <b>شخصیت فعال:</b> <b>${personaName}</b> — <i>${personaTag}</i>\n\n` +
           `📊 <b>سهمیه و مصرف روزانه شما:</b>\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n` +
           `💬 <b>پیام‌ها:</b>   ${renderBar(used.messages, lim.msg)}\n` +
           `🎨 <b>تصاویر:</b>   ${renderBar(used.imagesGenerated, lim.img)}\n` +
           `🎤 <b>ویس‌ها:</b>    ${renderBar(used.voicesSent, lim.voice)}\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n\n` +
           `💡 <i>یکی از گزینه‌های زیر را انتخاب کنید:</i>`;
  } else if (lang === "ar") {
    text = `╭━━━━━━━━━━━━━━━━━━━━━╮\n` +
           `┃ 🌌 <b>لوحة تحكم نوفا</b>\n` +
           `┃ <i>الإصدار ${BOT_VERSION} · المحرك الذكي</i>\n` +
           `╰━━━━━━━━━━━━━━━━━━━━━╯\n\n` +
           `👤 <b>المستخدم:</b> <code>${escapeHTML(user.first_name)}</code> (${tier})\n` +
           `${persona.emoji} <b>الشخصية النشطة:</b> <b>${personaName}</b> — <i>${personaTag}</i>\n\n` +
           `📊 <b>استخدامك اليومي:</b>\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n` +
           `💬 <b>الرسائل:</b>   ${renderBar(used.messages, lim.msg)}\n` +
           `🎨 <b>الصور:</b>     ${renderBar(used.imagesGenerated, lim.img)}\n` +
           `🎤 <b>الصوتيات:</b>  ${renderBar(used.voicesSent, lim.voice)}\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n\n` +
           `💡 <i>اختر أحد الخيارات أدناه:</i>`;
  } else {
    text = `╭━━━━━━━━━━━━━━━━━━━━━╮\n` +
           `┃ 🌌 <b>Nova Command Center</b>\n` +
           `┃ <i>Version ${BOT_VERSION} · AI Core</i>\n` +
           `╰━━━━━━━━━━━━━━━━━━━━━╯\n\n` +
           `👤 <b>User:</b> <code>${escapeHTML(user.first_name)}</code> (${tier})\n` +
           `${persona.emoji} <b>Active Persona:</b> <b>${personaName}</b> — <i>${personaTag}</i>\n\n` +
           `📊 <b>Daily Usage Quota:</b>\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n` +
           `💬 <b>Messages:</b> ${renderBar(used.messages, lim.msg)}\n` +
           `🎨 <b>Images:</b>   ${renderBar(used.imagesGenerated, lim.img)}\n` +
           `🎤 <b>Voices:</b>   ${renderBar(used.voicesSent, lim.voice)}\n` +
           `┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n\n` +
           `💡 <i>Select an option from below:</i>`;
  }
  
  const kb = buildHomeKeyboard(session, user.id);
  const opts = { 
    reply_markup: JSON.stringify(validateKeyboard(kb)),
    parse_mode: "HTML" as const
  };
  
  if (editMsgId) {
    await editMessageText(chatId, editMsgId, text, opts);
  } else {
    await sendMessage(chatId, text, opts);
  }
}

function buildHomeKeyboard(session: ChatSession, userId: number): InlineKeyboard {
  const lang = session.language;
  const isOwner = userId === cfg.BOT_OWNER_ID;
  const isFa = lang === "fa";
  const isAr = lang === "ar";

  const rows: InlineBtn[][] = [
    [
      btn(isFa ? "🎭 تغییر شخصیت" : isAr ? "🎭 تغییر الشخصية" : "🎭 Personas", "home:personas"),
      btn(isFa ? "🆕 گفتگوی جدید" : isAr ? "🆕 محادثة جديدة" : "🆕 New Chat", "home:new_confirm"),
    ],
    [
      btn(isFa ? "✏️ پرامپت سفارشی" : isAr ? "✏️ موجه مخصص" : "✏️ Custom Prompt", "home:prompt"),
      btn(isFa ? "🌐 تغییر زبان" : isAr ? "🌐 تغییر اللغة" : "🌐 Language", "home:language"),
    ],
  ];

  if (!session.vipStatus && !isOwner) {
    rows.push([
      btn(isFa ? "❓ راهنما" : isAr ? "❓ المساعدة" : "❓ Help", "home:help"),
      btn(isFa ? "💎 ارتقا به VIP" : isAr ? "💎 ترقية إلى VIP" : "💎 Go VIP", "home:vip"),
    ]);
  } else {
    rows.push([ btn(isFa ? "❓ راهنما" : isAr ? "❓ المساعدة" : "❓ Help", "home:help") ]);
  }

  if (isOwner) {
    rows.push([
      adminPanelButton(isFa ? "👑 پنل مدیریت ارشد" : isAr ? "👑 لوحة التحكم" : "👑 Admin Dashboard", session.type === "private"),
    ]);
  } else if (session.type === "private") {
    // Normal users get their own dashboard here — the admin button stays
    // owner-only so the two surfaces never blur.
    rows.push([userDashboardButton(lang, session.type === "private")]);
  }

  if (session.type !== "private") {
    rows.push([btn(isFa ? "👥 تنظیمات گروه" : isAr ? "👥 إعدادات المجموعة" : "👥 Group Settings", "group_settings")]);
  }
  rows.push([btn(isFa ? "✖️ بستن منو" : isAr ? "✖️ إغلاق" : "✖️ Close", "home:close")]);
  return { inline_keyboard: rows };
}

async function showPromptMenu(chatId: number, msgId: number, session: ChatSession, userId: number, isGroup = false): Promise<void> {
  const lang = session.language;
  const current = getPersona(getEffectivePersonaId(session, userId, isGroup));
  const currentName = lang === "fa" ? current.nameFA : current.nameEN;
  const hasCustom = Boolean(session.customPrompts.gemini);
  const isManualPrompt = session.customPromptSource === "manual";
  const customPreview = !hasCustom
    ? (lang === "fa" ? "_پرامپت پیش‌فرض_" : "_Default prompt_")
    : isManualPrompt
      ? `_${session.customPrompts.gemini!.slice(0, 60)}${session.customPrompts.gemini!.length > 60 ? "..." : ""}_`
      : (lang === "fa" ? "_🔒 پرامپت شخصیت (محرمانه)_" : "_🔒 persona prompt (hidden)_");

  const text = lang === "fa"
    ? `✏️ *مدیریت پرامپت*\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `🎭 شخصیت فعال: *${current.emoji} ${currentName}*\n\n` +
      `📝 پرامپت: ${customPreview}\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `برای تنظیم پرامپت دستی:\n\`/setprompt nova [متن]\``
    : `✏️ *Prompt Management*\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `🎭 Active persona: *${current.emoji} ${currentName}*\n\n` +
      `📝 Prompt: ${customPreview}\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `To set custom prompt:\n\`/setprompt nova [text]\``;

  const kb: InlineKeyboard = { inline_keyboard: [
    [btn(lang === "fa" ? "🎭 تغییر شخصیت" : "🎭 Change Persona", "open_personas")],
    ...(hasCustom ? [[btn(lang === "fa" ? "🗑️ پاک کردن پرامپت دستی" : "🗑️ Clear custom prompt", "reset_prompt_gemini")]] : []),
    [btn(lang === "fa" ? "👁️ نمایش کامل پرامپت" : "👁️ View full prompt", "show_prompts")],
    [btn(lang === "fa" ? "🔙 بازگشت" : "🔙 Back", "home:open")],
  ]};

  await editMessageText(chatId, msgId, text, { reply_markup: JSON.stringify(validateKeyboard(kb)) });
}

async function showGroupSettings(chatId: number, msgId: number, session: ChatSession, env: Env): Promise<void> {
  const lang = session.language;
  const fa = lang === "fa";
  const gcfg = await getGroupConfig(chatId, env);

  const onTxt = (b: boolean) => b ? (fa ? "فعال ✅" : "On ✅") : (fa ? "غیرفعال ❌" : "Off ❌");
  
  const text = fa
    ? `👥 *تنظیمات گروه*\n\n` +
      `🟢 پاسخ‌گویی ربات: *${onTxt(gcfg.enabled)}*\n` +
      `🛠️ کارهای سنگین (وب‌اپ/کد طولانی): *${onTxt(gcfg.allowHeavy)}*\n` +
      `📢 حالت پاسخ: *فقط منشن (دائمی)*\n\n` +
      `_گروه‌ها به‌صورت پیش‌فرض فعال‌اند. مدیران گروه می‌توانند پاسخ‌گویی را متوقف کنند._`
    : `👥 *Group Settings*\n\n` +
      `🟢 Bot replies: *${onTxt(gcfg.enabled)}*\n` +
      `🛠️ Heavy tasks (web apps/long code): *${onTxt(gcfg.allowHeavy)}*\n` +
      `📢 Reply mode: *Mention only (Permanent)*\n\n` +
      `_Groups are enabled by default. Group administrators can disable replies._`;

  const kb: InlineKeyboard = { inline_keyboard: [
    [btn(`🟢 ${fa ? "پاسخ‌گویی ربات" : "Bot replies"}: ${gcfg.enabled ? (fa ? "فعال" : "On") : (fa ? "غیرفعال" : "Off")}`, "gset_enabled")],
    [btn(`🛠️ ${fa ? "کارهای سنگین" : "Heavy Tasks"}: ${gcfg.allowHeavy ? (fa ? "مجاز" : "On") : (fa ? "غیرمجاز" : "Off")}`, "gset_heavy")],
    [btn(fa ? "🔙 بازگشت" : "🔙 Back", "home:open")]
  ]};
  await editMessageText(chatId, msgId, text, { reply_markup: JSON.stringify(validateKeyboard(kb)) });
}
// SECTION: MEMORY PRUNING (نگه‌داشتن کش‌های درون‌حافظه در محدوده)
/**
 * پاکسازی دوره‌ای همه‌ی ساختارهای درون‌حافظه‌ای ایزوله: هر Map/کش که ورودی
 * کهنه دارد اینجا محدود می‌شود تا Worker Free هرگز Memory Leak نگیرد.
 * از هر دو مسیر صدا زده می‌شود: (۱) به‌صورت تصادفی هنگام پردازش آپدیت‌ها،
 * (۲) در Cron هر ۵ دقیقه.
 */
function pruneMemoryCaches(): void {
  const now = Date.now();

  // ۱. کش گروه‌ها — فقط چت‌های فعالِ کمتر از ۱ ساعت نگه داشته می‌شوند
  for (const [id, ctx] of groupContextCache) {
    if (now - ctx.lastCleanup > 60 * 60 * 1000) groupContextCache.delete(id);
  }

  // ۲. ری‌اکشن‌های اخیر (استیکر/گیف) — بعد از ۳ ساعت بی‌استفاده حذف
  if (lastReactionSent.size > 100) {
    for (const [k, mem] of lastReactionSent) if (now - mem.ts > 3 * 60 * 60 * 1000) lastReactionSent.delete(k);
  }

  // ۳. Rate-limit کال‌بک‌ها — فقط پنجره‌ی ۶۰ ثانیه‌ای
  for (const [id, ts] of callbackRateLimits) {
    const filtered = ts.filter(t => now - t < 60_000);
    if (!filtered.length) callbackRateLimits.delete(id);
    else callbackRateLimits.set(id, filtered);
  }

  // ۳b. Inline rate-limit + daily counter — same window, plus the day stamp so a
  // counter from yesterday cannot cap today.
  for (const [id, ts] of inlineRateLimits) {
    const filtered = ts.filter(t => now - t < 60_000);
    if (!filtered.length) inlineRateLimits.delete(id);
    else inlineRateLimits.set(id, filtered);
  }
  const today = new Date(now).toISOString().slice(0, 10);
  for (const [id, entry] of _inlineDaily) if (entry.day !== today) _inlineDaily.delete(id);
  capMapSize(_inlineDaily, 5_000);

  // ۴. وضعیت تایپینگ — سقف ۵۰۰
  if (lastTypingSent.size > 500) {
    const keysArray = Array.from(lastTypingSent.keys());
    for (let i = 0; i < 100; i++) lastTypingSent.delete(keysArray[i]);
  }

  // ۵. کش اتصال‌های بیزینس — TTL ۵ دقیقه
  if (_bizConnCache.size > 200) {
    for (const [k, v] of _bizConnCache) if (now - v.ts > BIZ_CONN_CACHE_TTL_MS) _bizConnCache.delete(k);
  }

  // ۶. کش گروه‌اینفو — فقط گروه‌های فعال کمتر از ۲۴ ساعت
  if (_groupInfoCache.size > 2000) {
    const nowSec = Math.floor(now / 1000);
    let dropped = 0;
    for (const [id, info] of _groupInfoCache) {
      if (nowSec - (info.lastActivity ?? 0) > 24 * 60 * 60) {
        _groupInfoCache.delete(id);
        _groupInfoLastPersistTs.delete(id);
        if (++dropped >= 300) break;
      }
    }
  }

  // ۷. درخواست‌های فعال — رکوردهای مرده‌تر از ۱۰ دقیقه
  for (const [chatId, set] of activeRequests) {
    for (const r of set) if (now - r.ts > 10 * 60 * 1000) set.delete(r);
    if (set.size === 0) activeRequests.delete(chatId);
  }

  // ۸. قفل‌های بارگذاری سشن — ورودی‌های بیش از ۵ دقیقه (مرده)
  if (sessionLoadLocks.size > 500) {
    // فقط اندازه را محدود کن — خودِ promiseها همیشه با finally پاک می‌شوند
    let dropped = 0;
    for (const k of sessionLoadLocks.keys()) { sessionLoadLocks.delete(k); if (++dropped >= 100) break; }
  }

  // ۹. پنل‌های کنترل‌سنتر (مالکیت پیام) — قدیمی‌تر از ۱ ساعت
  if (panelOwners.size > 3000) {
    for (const [k, v] of panelOwners) if (now - v.ts > 60 * 60 * 1000) panelOwners.delete(k);
  }

  // ۱۰. کش‌های جستجو — انقضای TTL
  for (const [k, v] of _searchCache) if (now - v.ts >= SEARCH_CACHE_TTL_MS[v.data.effort]) _searchCache.delete(k);

  // ۱۱. وضعیت‌های صفحه‌بندی
  if (modelListStates.size > 100) modelListStates.clear();

  // ۱۱b. Dedup درخواست‌ها — ورودی‌های منقضی
  if (_recentRequestKeys.size > 1000) {
    for (const [k, exp] of _recentRequestKeys) if (exp <= now) _recentRequestKeys.delete(k);
  }

  // ۱۱d. Request log — قبلاً با MAX_REQUEST_LOG محدود شده است؛ اینجا فقط روزها را
  // در صورت نشت احتمالی کوتاه می‌کنیم.
  if (requestLog.length > MAX_REQUEST_LOG) requestLog.splice(0, requestLog.length - MAX_REQUEST_LOG);

  // ۱۲. بافر فلاش سشن — اگر بیش از حد بزرگ شد، فوراً خالی کن (داده قبلاً در
  // saveSession بدون کوآلسینگ نوشته شده یا در حافظه است؛ خالی کردن فقط از
  // انباشتگی در ایزوله‌های طولانی‌عمر جلوگیری می‌کند)
  if (_pendingSessionFlush.size > 500) _pendingSessionFlush.clear();
  if (_lastSessionFlushTs.size > 500) {
    let dropped = 0;
    for (const k of _lastSessionFlushTs.keys()) { _lastSessionFlushTs.delete(k); if (++dropped >= 100) break; }
  }

  // ۱۳. پنجره‌ی ضدِ سیلِ اطلاع‌رسانی خطا — ورودی‌های منقضی‌شده
  for (const [chatId, ts] of _lastTurnFailureNotice) {
    if (now - ts > TURN_FAILURE_NOTICE_MIN_INTERVAL_MS * 4) _lastTurnFailureNotice.delete(chatId);
  }

  // ۱۴. ساختارهایی که تخلیه‌ی موضعی ندارند یا تخلیه‌شان به یک مسیر موفق وابسته است.
  // اگر آن مسیر رد شود (استثنا، ری‌استارت، کاربری که فرم را نیمه‌کاره رها می‌کند)
  // ورودی برای همیشه می‌ماند. اینجا فقط سقف اندازه اعمال می‌شود — نه پاکسازیِ
  // معناداری که رفتار را عوض کند.
  capMapSize(_groupCfgCache, GROUP_CFG_CACHE_MAX);
  capMapSize(_fileUrlCache, FILE_URL_CACHE_MAX);
  capMapSize(_sharedMemCache, SHARED_MEM_CACHE_MAX);
  // activeProgressMessages فقط در مسیرِ «پیام پیشرفت را پاک کن» حذف می‌شود؛ یک
  // استثنای میانی، ورودی را جا می‌گذاشت.
  capMapSize(activeProgressMessages, 500);
  // broadcastStates تا زمانی که ادمین ارسال را کامل یا لغو کند زنده می‌ماند.
  capMapSize(broadcastStates, 100);
  // یک تلاشِ تعمیرِ اتصال بیزینس به ازای هر connId، بدون هیچ انقضایی.
  capMapSize(_bizConnRepairAttempted, 500);
  capMapSize(_searchCache, 60);
  capMapSize(lastReactionSent, 5000);
  capMapSize(panelOwners, 3000);
  capMapSize(_bizConnCache, 200);
  capMapSize(_groupInfoCache, 2000);
  capMapSize(_groupInfoLastPersistTs, 2000);
  capMapSize(_recentRequestKeys, 1000);
}
// SECTION: MAIN UPDATE DISPATCHER
async function handleUpdate(update: TgUpdate, env: Env): Promise<void> {
  const chatId =
    update.message?.chat.id ??
    update.callback_query?.message?.chat.id ??
    update.callback_query?.from.id ??
    update.business_message?.chat.id ??
    update.edited_business_message?.chat.id ??
    update.business_connection?.user_chat_id ??
    0;

  // قفل سراسری قبلی که کل پردازش هر پیام (تماس مدل + اجرای ابزارها + ذخیره سشن)
  // را به ازای هر چت کاملاً سریال می‌کرد، عمداً حذف شد تا پیام‌ها واقعاً موازی
  // پردازش شوند. جلوگیری از رگبار درخواست هم‌چنان با canProcessRequest/activeRequests
  // (سقف ۳ درخواست هم‌زمان به ازای هر چت) انجام می‌شود، و ترتیب نوشتن سشن روی KV
  // هم در saveSession با یک صف سبک per-session محافظت شده (تغییر بعدی).
  const prevChatId = _currentProcessingChatId;
  _currentProcessingChatId = chatId;
  try {
    await dispatchUpdate(update, env);
  } catch (e) {
    logger.error("Unhandled update error", e);
  } finally {
    _currentProcessingChatId = prevChatId;
  }
}

async function dispatchUpdate(update: TgUpdate, env: Env): Promise<void> {
  try {
    // Periodic lightweight cleanup (1% chance per request)
    if (Math.random() < 0.01) {
      pruneMemoryCaches();
    }

    if(update.my_chat_member){
      const {chat,new_chat_member:member}=update.my_chat_member;
      const present=["member","administrator","creator"].includes(member.status)||(member.status==="restricted"&&member.is_member!==false);
      if(present&&member.can_send_messages!==false){await clearDeliveryFailure(env.DB,chat.id);if(chat.type!=="private")await saveGroupInfo(chat,env);}
      else await noteDeliveryFailure(env.DB,chat.id,present?"not enough rights to send text messages":"bot was kicked");
      return;
    }
    if (update.callback_query) {
      const cb = update.callback_query;
      try {
        await handleCallback(cb, env);
      } catch (e) {
        // `handleCallback` had no error handling of its own, so any throw left the
        // callback query unanswered — the button kept spinning until Telegram
        // expired the query and the tap looked simply ignored.
        logger.error("Unhandled callback failure", e);
        await answerCb(cb.id, "⚠️ خطا در اجرای این دکمه. دوباره تلاش کن.", true).catch(() => {});
      }
    } else if (update.inline_query) {
      // Inline Mode: @ربات در هر چت — پاسخ سریع با بودجه‌ی زمانی سخت
      await withTimeout(handleInlineQuery(update.inline_query, env), 12_000, "inline query timeout").catch(e => {
        logger.warn(`Inline query error: ${e instanceof Error ? e.message : e}`);
      });
    } else if (update.chosen_inline_result) {
      // بدون پردازش سنگین — فقط برای آمار (اختیاری)
      //
      // A chosen result is the only honest signal about which inline kinds are
      // worth keeping, and the result id carries the kind (`ink:<kind>:<page>`).
      // In-memory only: no write per sent result, and nothing keyed by user.
      const chosen = update.chosen_inline_result;
      const kind = kindFromResultId(chosen.result_id) ?? "unknown";
      bumpMetric("inlineChosen");
      _inlineChosenByKind.set(kind, (_inlineChosenByKind.get(kind) ?? 0) + 1);
      logger.info(`[inline] chosen kind=${kind}`);
    } else if (update.business_connection) {
      await handleBusinessConnection(update.business_connection, env);
    } else if (update.business_message || update.edited_business_message) {
      await handleBusinessMessage(update.business_message ?? update.edited_business_message!, env);
    } else if (update.message) {
      const msg = update.message;
      if (!msg.from || msg.from.is_bot) return;
      if (!cfg.ALLOWED_CHAT_TYPES.includes(msg.chat.type)) return;

      // Every message handler is entered through `runMessageHandler` so a throw in
      // a handler *prologue* — session load, activation gate, block lookup, slot
      // acquisition, all of which sit outside those handlers' own try blocks —
      // still produces a user-visible outcome instead of silence.
      if (msg.voice) {
        await runMessageHandler("voice", msg, env, handleVoiceMessage);
      } else if (msg.photo || msg.document || msg.animation || msg.video || msg.audio) {
        await runMessageHandler("media", msg, env, handleMediaMessage);
      } else if (msg.sticker) {
        await runMessageHandler("sticker", msg, env, handleStickerMessage);
      } else if (msg.text) {
        await runMessageHandler("text", msg, env, handleTextMessage);
      }
    }
  } catch (e) {
    logger.error("Unhandled update error", e);
  }
}

/**
 * Outermost safety net for a single message update.
 *
 * The handlers each have their own error handling, but only around their *main*
 * body; their prologues (session load, group-activation gate, ban lookup, request
 * slot) run unguarded, and `handleStickerMessage` had no try/catch at all. A
 * failure there used to unwind straight into `dispatchUpdate`'s silent catch, so
 * the user saw nothing — the exact reported symptom. `notifyTurnFailure` is
 * rate-limited per chat, so layering it here on top of a handler that already
 * reported cannot produce a duplicate apology.
 */
async function runMessageHandler(
  kind: string,
  msg: TgMessage,
  env: Env,
  handler: (m: TgMessage, e: Env) => Promise<void>,
): Promise<void> {
  try {
    const canReceive=await withinDeadline(async()=>{
      if(msg.chat.type==="private")await clearDeliveryFailure(env.DB,msg.chat.id);else await noteGroupMessage(env.DB,msg.chat.id);
      return chatCanReceive(env.DB,msg.chat.id);
    },3000);
    if(!canReceive)return;
    await handler(msg, env);
  } catch (e) {
    logger.error(`Unhandled ${kind} handler failure`, e);
    bumpMetric("errors");
    await notifyTurnFailure(msg.chat.id, e, {
      replyToMessageId: msg.message_id,
      userId: msg.from?.id,
    });
  }
}
// SECTION: INITIALIZATION & HEALTH CHECK
async function initBot(env: Env): Promise<void> {
  const botInfo = await tg("getMe", {}) as TgUser;
  BOT_INFO = botInfo;
  BOT_SELF_ID = botInfo.id;
  env.SESSIONS.put("bot:self_id", String(botInfo.id)).catch(() => {});
  logger.info(`✅ Bot ready: ${botInfo.first_name} (@${botInfo.username}) v${BOT_VERSION}`);

  const maintenance = await env.SESSIONS.get("maintenance_mode", "text");
  cfg.MAINTENANCE_MODE = maintenance === "true";

  // Telegram menu button → the user dashboard. This is the one surface visible
  // in EVERY chat without any typing, so it is the strongest discovery path
  // for /my. Web App menu buttons work for all users (the Mini App authenticates
  // them via initData on open); they need an https origin, which a cron-only or
  // cold isolate may not have learned yet — in that case the next isolate with
  // one sets it (the KV guard makes this a no-op afterwards, one write per
  // origin change, never per request).
  try {
    const origin = (requestOrigin || "").trim().replace(/\/+$/, "");
    if (origin.startsWith("https://")) {
      const menuUrl = "https://nova.hsoofi1382.workers.dev/dashboard";
      const lastMenuUrl = await env.SESSIONS.get("menu_button:url", "text").catch(() => null);
      if (lastMenuUrl !== menuUrl) {
        await tg("setChatMenuButton", { menu_button: { type: "web_app", text: "𝗠𝗜𝗡𝗜 𝗔𝗣𝗣✨", web_app: { url: menuUrl } } }, { timeoutMs: 8000 });
        await env.SESSIONS.put("menu_button:url", menuUrl).catch(() => {});
        logger.info(`[menu] chat menu button → ${menuUrl}`);
      }
    }
  } catch (e) {
    // Cosmetic surface: a failure here must never delay or fail init.
    logger.warn("[menu] setChatMenuButton failed", e);
  }
}

function createHealthResponse(): Response {
  const total = Array.from(activeRequests.values()).reduce((s, set) => s + set.size, 0);
  return new Response(JSON.stringify({
    status: "healthy",
    version: BOT_VERSION,
    bot: BOT_INFO ? { name: BOT_INFO.first_name, username: BOT_INFO.username } : null,
    active_requests: total,
    max_requests: cfg.MAX_CONCURRENT_REQUESTS,
    agent: "Nova",
  }, null, 2), { headers: { "Content-Type": "application/json" }, status: 200 });
}

let _cachedBotConfig: BotConfig | null = null;
let _configCacheTs = 0;

/** Returns the bot config from KV, memoized in-isolate for 30s to cut KV reads. */
async function getBotConfigCached(env: Env): Promise<BotConfig> {
  if (_cachedBotConfig && Date.now() - _configCacheTs < 30_000) {
    return _cachedBotConfig;
  }
  _cachedBotConfig = await getBotConfig(env);
  _configCacheTs = Date.now();
  return _cachedBotConfig;
}
// SECTION: HOUSEKEEPING (Automatic Recovery / Smart Cleanup — Cron)
// هیچ Task نباید برای همیشه در وضعیت گیرکرده بماند:
//  ۱. ردیف‌های منقضی kv_store (claimها، پنل‌ها، رسانه‌ها، ددپ‌ها) پاک می‌شوند — محدود.
//  ۲. برادکستِ گیرکرده در حالت running به pending برمی‌گردد تا تیک بعدی ادامه دهد.
//  ۳. ردیف‌های users بدون سشنِ واقعی (کاربرهای پاک‌شده) هم‌گام می‌شوند — محدود.
// همگی باند هستند (LIMIT) تا هرگز Full Scan سنگین یا CPU کرون را منفجر نکنند.
async function runHousekeeping(env: Env): Promise<void> {
  const nowSec = Math.floor(Date.now() / 1000);
  if ((env.APP_BUILDS || env.MEDIA) && env.APP_BUILD_RUNNER_TOKEN) {
    await getAppFactory(env,requestOrigin).deps.store.cleanup().catch(e=>logger.warn("Application retention cleanup failed",e));
  }
  await cleanupOperations(env.DB).catch(e => logger.warn("housekeeping: operations cleanup failed", e));

  // ۱. پاکسازی ردیف‌های منقضی (هر تیک حداکثر ۳۰۰ ردیف)
  // NOTE: `DELETE ... LIMIT n` requires SQLITE_ENABLE_UPDATE_DELETE_LIMIT, which
  // D1 does not enable — the old statement always failed with a syntax error
  // that the .catch() swallowed, so expired rows were NEVER physically removed
  // and kv_store grew without bound. The subselect form is portable.
  await env.DB.prepare(
    `DELETE FROM kv_store WHERE key IN (
       SELECT key FROM kv_store
       WHERE expires_at IS NOT NULL AND expires_at <= ?
       LIMIT 300
     )`
  ).bind(nowSec).run().catch((e) => logger.warn("housekeeping: expired-row sweep failed", e));

  // ۱b. پاکسازی تشخیص درخواست‌های قدیمی — محدود و فقط در Cron، نه hot path.
  await env.DB.prepare(
    `DELETE FROM request_diagnostics WHERE request_id IN (
       SELECT request_id FROM request_diagnostics WHERE ts < ? LIMIT 200
     )`
  ).bind(Date.now() - 7 * 24 * 60 * 60 * 1000).run().catch((e) => logger.warn("housekeeping: request diagnostics cleanup failed", e));

  // ۱c. زامبی‌های زمان‌بند: ردیف‌هایی که پنجره‌ی اجرایشان کامل گذشته است.
  // The due sweep already retires expired rows it selects and reclaims stale
  // leases, so this only catches rows that can never be selected again (a
  // hand-edited or legacy row whose expiry precedes its next run). Bounded.
  await env.DB.prepare(
    `DELETE FROM scheduled_jobs WHERE id IN (
       SELECT id FROM scheduled_jobs
       WHERE expires_at IS NOT NULL AND expires_at <= ?
       LIMIT 100
     )`
  ).bind(Date.now()).run().catch(() => { /* table may not exist yet on a cold DB */ });

  // ۲. بازیابی برادکستِ گیرکرده
  try {
    const job = await env.SESSIONS.get("broadcast_job:current", "json") as BroadcastJob | null;
    if (job && job.status === "running" && Date.now() - job.createdAt > 20 * 60 * 1000) {
      job.status = "pending";
      await safeKvPut(env, "broadcast_job:current", JSON.stringify(job));
      logger.info("[housekeeping] recovered stale broadcast job");
    }
  } catch (e) {
    logger.warn("housekeeping: broadcast recovery failed", e);
  }

  // ۳. همگام‌سازی ساده‌ی جدول users: ردیف‌هایی که سشنِ واقعی ندارند حذف می‌شوند.
  // (فقط هر ۱ ساعت و با نمونه‌ی بسیار محدود تا کرون سبک بماند.)
  if (Date.now() - _lastUsersSyncTs > 60 * 60 * 1000) {
    _lastUsersSyncTs = Date.now();
    try {
      // Was an N+1: up to 60 sequential env.SESSIONS.get() round-trips inside a
      // cron invocation that only has ~10ms CPU on the Free plan. One anti-join
      // finds the orphans directly, and the delete is bounded the same way.
      await env.DB.prepare(
        `DELETE FROM users WHERE user_id IN (
           SELECT u.user_id FROM users u
           WHERE NOT EXISTS (
             SELECT 1 FROM kv_store k
             WHERE k.key = 'session:' || u.user_id
               AND (k.expires_at IS NULL OR k.expires_at > ?)
           )
           LIMIT 20
         )`
      ).bind(nowSec).run();
    } catch (e) {
      logger.warn("housekeeping: users sync failed", e);
    }
  }
}

let _lastUsersSyncTs = 0;
// SECTION: WORKER EXPORT
export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    if (!env.TOKEN || !env.DB) {
      return new Response("Service temporarily unavailable", { status: 503 });
    }
    // Reject unauthenticated updates before schema/backfill work or any claim
    // write. Sender ids in a JSON body are not authentication.
    if(request.method==="POST"&&new URL(request.url).pathname==="/webhook"){
      const secret=env.WEBHOOK_SECRET?.trim();
      if(!secret)return new Response("Webhook unavailable",{status:503});
      if(!timingSafeEqualStr(request.headers.get("X-Telegram-Bot-Api-Secret-Token")??"",secret))return new Response("Unauthorized",{status:401});
    }
    if (!env.SESSIONS) {
      env.DB = governDatabase(env.DB);
      (env as Env).SESSIONS = new D1KVNamespace(env.DB);
    }

    // The KV shim is backed by the `kv_store` D1 table. It must exist before
    // ANY state read/write, otherwise every get() returns null (looking like a
    // brand-new user) and update claiming throws. Cheap after the first call:
    // one memoized promise per isolate.
    try {
      await ensureCoreSchema(env);
    } catch (e) {
      logger.error("Core schema unavailable; refusing to serve", e);
      return new Response("Storage unavailable", { status: 503 });
    }

    const botConfig = await getBotConfigCached(env);
    cfg = createConfig(env, botConfig);
    env_ref = env;
    API_URL = `https://api.telegram.org/bot${cfg.TOKEN}`;

    const url = new URL(request.url);
    if (url.pathname === "/factory" || url.pathname === "/factory/") return new Response(FACTORY_DASHBOARD_HTML,{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff",
      "Content-Security-Policy":"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'"}});
    // Schema migration and the legacy user-summary backfill are relevant to
    // webhook/admin traffic only. Running them behind *every* request made
    // dashboard, hosted-app and static-asset fetches compete with the bot for
    // D1 capacity. The warm-up itself is shared while in flight and processes
    // one resumable page at a time.
    requestOrigin = url.origin;

    // Record the origin so a cron-only isolate (which never sees a request)
    // can still build absolute media links. Guarded so it costs one write per
    // isolate at most, and http:// under `wrangler dev` is never persisted.
    // The guard latches only after the write lands: `drainBackgroundTasks` runs
    // in the webhook tail alone, so a put fired from a non-webhook request may
    // never flush, and latching first would mean never retrying it.
    if (requestOrigin.startsWith("https://") && _persistedOrigin !== requestOrigin) {
      const learned = requestOrigin;
      runBackground(async () => {
        await env.SESSIONS.put(WORKER_ORIGIN_KEY, learned);
        _persistedOrigin = learned;
      }, 2000, "origin");
    }
    globalCtx = ctx;
    if (url.pathname.startsWith("/api/apps/") || url.pathname.startsWith("/api/app-runner/")) {
      try {
        if(!nativeFactoryConfigured(env)){
          const read=request.method==="GET"&&!url.pathname.includes("/download/");
          return new Response(JSON.stringify({ok:read,available:false,status:"disabled",targets:[],message:nativeUnavailableMessage(),
            availability:{available:false,status:"disabled",targets:[],message:nativeUnavailableMessage()},projects:[],builds:[],...(read?{}:{error:nativeUnavailableMessage()})}),
            {status:read?200:503,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}});
        }
        const factory = getAppFactory(env,url.origin);
        if (url.pathname.startsWith("/api/app-runner/")) return await factory.runnerAPI(request);
        if (url.pathname.startsWith("/api/apps/download/")) return await factory.download(request);
        const owner = await validateTelegramInitData(request.headers.get("X-Telegram-Init-Data") ?? "",cfg.TOKEN);
        if (!owner) return new Response(JSON.stringify({ok:false,error:"forbidden"}),{status:403,headers:{"Content-Type":"application/json"}});
        const personal = await getOrCreateSession({id:owner.id,type:"private"},owner,env);
        if (personal.blocked || await isInMaintenance(env)) return new Response(JSON.stringify({ok:false,error:"unavailable"}),{status:403,headers:{"Content-Type":"application/json"}});
        return await factory.userAPI(request,owner.id);
      } catch(e) { logger.warn("Application factory request failed",e); return factoryError(e); }
    }

    const declaredBodyBytes = Number.parseInt(request.headers.get("content-length") ?? "0", 10);
    if ((request.method === "POST" || request.method === "PUT" || request.method === "PATCH")
      && Number.isFinite(declaredBodyBytes)
      && declaredBodyBytes > cfg.MAX_FILE_SIZE + 512 * 1024) {
      return new Response("Request body too large", { status: 413 });
    }

    if (url.pathname.startsWith("/app/api/storage/")) {
      const corsHeaders: Record<string, string> = {
        "Access-Control-Allow-Origin": request.headers.get("Origin") === "null" ? "*" : url.origin,
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, X-Telegram-Init-Data",
        "Cache-Control": "no-store",
      };
      const jsonResponse = (body: unknown, status = 200): Response =>
        new Response(JSON.stringify(body), {
          status,
          headers: { "Content-Type": "application/json; charset=utf-8", ...corsHeaders },
        });

      if (request.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: corsHeaders });
      }

      const storageUser = await validateTelegramInitData(
        request.headers.get("X-Telegram-Init-Data") ?? "",
        cfg.TOKEN,
      );
      if (!storageUser) return jsonResponse({ ok: false, error: "unauthorized" }, 401);

      const rawKey = url.pathname.replace("/app/api/storage/", "").trim().toLowerCase();
      const stateKey = rawKey;
      if (!/^[a-z0-9_-]{1,80}$/.test(stateKey)) return jsonResponse({ ok: false, error: "Invalid filename" }, 400);
      const kvKey = `appstate:${storageUser.id}:${stateKey}`;
      const MAX_STATE_BYTES = 256 * 1024; // 256 KB hard cap per mini-app state blob

      try {
        if (request.method === "GET") {
          const stored = await env.SESSIONS.get(kvKey, "text");
          if (!stored) return jsonResponse({ ok: true, data: null });
          return jsonResponse({ ok: true, data: JSON.parse(stored) as unknown });
        }
        if (request.method === "POST") {
          const parsed = await readJsonObject(request, MAX_STATE_BYTES);
          const bodyText = JSON.stringify(parsed);
          // 90-day TTL keeps the free-tier KV footprint bounded.
          await env.SESSIONS.put(kvKey, JSON.stringify(parsed), { expirationTtl: 90 * 24 * 60 * 60 });
          return jsonResponse({ ok: true, saved: true, bytes: utf8ByteLength(bodyText) });
        }
        return jsonResponse({ ok: false, error: "Method not allowed" }, 405);
      } catch (e) {
        if (e instanceof RequestBodyError) return jsonResponse({ ok: false, error: e.message }, e.status);
        logger.error("Mini-app storage API error", e);
        return jsonResponse({ ok: false, error: "Internal storage error" }, 500);
      }
    }
    
    if (url.pathname.startsWith("/app/api/assets")) {
      // ── Asset API: دسترسی وب‌اپ‌ها و بازی‌ها به Assetهای کاربر ──
      // تصاویر آپلودشده/تولیدشده/جستجو-شده‌ی کاربر را برای استفاده در
      // وب‌اپ‌ها و بازی‌ها در دسترس قرار می‌دهد (با احراز هویت Telegram).
      const corsHeaders: Record<string, string> = {
        "Access-Control-Allow-Origin": request.headers.get("Origin") === "null" ? "*" : url.origin,
        "Access-Control-Allow-Methods": "GET, DELETE, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, X-Telegram-Init-Data",
        "Cache-Control": "no-store",
      };
      const jsonResponse = (body: unknown, status = 200): Response =>
        new Response(JSON.stringify(body), {
          status,
          headers: { "Content-Type": "application/json; charset=utf-8", ...corsHeaders },
        });

      if (request.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: corsHeaders });
      }

      const assetUser = await validateTelegramInitData(
        request.headers.get("X-Telegram-Init-Data") ?? "",
        cfg.TOKEN,
      );
      if (!assetUser) return jsonResponse({ ok: false, error: "unauthorized" }, 401);

      const assetPath = url.pathname.replace("/app/api/assets", "").replace(/^\//, "").trim();
      try {
        if (request.method === "GET") {
          const assets = await listUserAssets(env, assetUser.id);
          return jsonResponse({ ok: true, assets });
        }
        if (request.method === "DELETE" && assetPath) {
          const ok = await deleteAssetRecord(env, assetPath, assetUser.id);
          return jsonResponse({ ok, deleted: ok });
        }
        return jsonResponse({ ok: false, error: "Method not allowed" }, 405);
      } catch (e) {
        logger.error("Asset API error", e);
        return jsonResponse({ ok: false, error: "Internal asset error" }, 500);
      }
    }

    if (url.pathname === "/admin" || url.pathname === "/admin/") {
      return new Response(ADMIN_DASHBOARD_HTML, {
        status: 200,
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self' https:; img-src 'self' data: https: blob:; frame-ancestors 'none'",
          "X-Content-Type-Options": "nosniff",
          "Cache-Control": "no-store",
          "Referrer-Policy": "no-referrer",
        },
      });
    }
    if (url.pathname.startsWith("/api/admin/")) {
      try { return await handleAdminAPI(request, env, url, ctx); } catch (e) {
        logger.error("handleAdminAPI fatal error", e);
        return new Response(JSON.stringify({ ok: false, error: "fatal" }), { status: 500, headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });
      }
    }

    if (url.pathname.startsWith("/api/webapp/")) {
      try {
        return await handleWebAppAPI(request, env, url);
      } catch (e) {
        logger.error("handleWebAppAPI fatal error", e);
        // Same origin as the success path. A wildcard here would have made the
        // *error* response — the one an attacker can provoke at will — readable
        // from any page, which is the widening `handleWebAppAPI` itself refuses.
        return new Response(JSON.stringify({ ok: false, error: "fatal" }), {
          status: 500,
          headers: {
            "Content-Type": "application/json; charset=utf-8",
            "Cache-Control": "no-store",
            "Access-Control-Allow-Origin": url.origin,
            "Access-Control-Allow-Headers": "Content-Type, X-Telegram-Init-Data",
            "Vary": "Origin",
          },
        });
      }
    }

    if (url.pathname.startsWith("/app/")) {
      const rawPath = url.pathname.replace("/app/", "").trim().toLowerCase();
      // Media blobs live exactly MEDIA_TTL_SECONDS, so the cache must not claim
      // longer: `max-age=31536000` told browsers and the CDN to hold a URL for a
      // year that stops resolving after a week.
      const mediaCache = `public, max-age=${MEDIA_TTL_SECONDS}`;

      // تشخیص و هاست مستقیم تصاویر باینری تولید شده توسط کلودفلر
      if (rawPath.endsWith(".png") || rawPath.startsWith("img_")) {
        const imgName = rawPath.replace(".png", "");
        const imgBuffer = await getMediaBlob(env, imgName);
        if (imgBuffer) {
          return new Response(imgBuffer, {
            headers: {
              "Content-Type": "image/png",
              "Cache-Control": mediaCache
            }
          });
        }
      } else if (rawPath.endsWith(".ogg") || rawPath.startsWith("voice_")) {
        // Checked before the HTML branch: audio used to fall through it first and
        // pay a pointless `app:` lookup on every single voice fetch.
        const voiceName = rawPath.replace(".ogg", "").trim();
        const voiceBuffer = await getMediaBlob(env, voiceName);
        if (voiceBuffer) {
          return new Response(voiceBuffer, {
            headers: {
              "Content-Type": "audio/ogg",
              "Cache-Control": mediaCache
            }
          });
        }
      } else {
        // ── Hosted application ───────────────────────────────────────────────
        // The deployment row is the authority, not the presence of a KV blob.
        // A project that was never activated (draft), was deleted, or has passed
        // its expiry is NOT served — and an expired one is torn down right here
        // as well as by the cron sweep, so the URL stops resolving at the
        // moment it expires rather than whenever a sweep happens to run.
        const appName = rawPath.replace(".html", "").replace(/[^a-z0-9_-]/g, "");
        const now = Date.now();
        // An expired entry must be re-read fresh, otherwise a cached "live" row
        // could keep serving a slug for up to the cache window past expiry.
        const cachedDeployment = _deploymentRowCache.get(appName)?.record ?? null;
        const forceFresh = Boolean(cachedDeployment && !isServable(cachedDeployment, now));
        let deployment = await readDeploymentRow(env, appName, forceFresh).catch(() => null);
        if (!deployment) {
          // A project created before the deployment table existed: migrate it on
          // first touch so existing links keep resolving (or expire correctly),
          // instead of 404-ing every app that predates this change.
          const legacy = await getAppMeta(env, appName).catch(() => null);
          if (legacy) deployment = await readDeploymentRow(env, appName).catch(() => null);
        }
        if (deployment && !isServable(deployment, now)) {
          // Expired (or never activated) but not yet swept: tear it down now so
          // the URL stops resolving at the moment it expires, not whenever the
          // next cron tick happens to run. A live-but-expired row is purged; a
          // draft is simply not served and is left for its owner to deploy.
          if (deployment.status === "live") {
            await purgeDeployment(env, deployment, "expired").catch(e => logger.warn("[deploy] inline expiry cleanup failed", e));
            return htmlPage(renderGonePage(true), 410);
          }
          return htmlPage(renderGonePage(false), 404);
        }
        const htmlContent = deployment && isServable(deployment, now)
          ? await env.SESSIONS.get(`app:${appName}`, "text")
          : null;
        if (htmlContent) {
          // Static-hosting path returns immediately. View counting is now an
          // in-memory increment (zero KV); we only flush the accumulated buffer
          // once it grows past a threshold, so popular apps cost ~1 KV write per
          // batch of views instead of one write per view.
          incrementWebAppView(appName, env);
          if (_webAppViewBuffer.size >= 25 || (_webAppViewBuffer.get(appName) ?? 0) >= 50) {
            ctx.waitUntil(Promise.race([flushWebAppViews(env).catch(() => {}), sleep(2000)]));
          }
          return new Response(htmlContent, {
            headers: {
              "Content-Type": "text/html; charset=utf-8",
              "Content-Security-Policy": "sandbox allow-scripts allow-forms allow-modals; default-src 'self' https: data: blob:; script-src 'unsafe-inline' https:; style-src 'unsafe-inline' https:; img-src 'self' https: data: blob:; font-src 'self' https: data:; connect-src 'self' https:; frame-ancestors 'none'",
              "X-Content-Type-Options": "nosniff",
              "Referrer-Policy": "no-referrer",
              "Cache-Control": "no-store",
            }
          });
        }
      }

      return htmlPage(renderGonePage(false), 404);
    }

    if (!isInitialized) {
      isInitialized = true;
      if (!BOT_SELF_ID) {
        // بدون await: این مقدار فقط برای تشخیص ریپلای در گروه لازم است و نباید
        // مسیر بحرانیِ هر پیام (حتی پیوی) را با یک خواندن D1 کند کند.
        env.SESSIONS.get("bot:self_id").then(cached => {
          if (cached) BOT_SELF_ID = parseInt(cached as string, 10);
        }).catch(() => {});
      }
      initBot(env).catch(e => { logger.error("Init failed", e); isInitialized = false; });
    } else if (!BOT_SELF_ID) {
      env.SESSIONS.get("bot:self_id").then(cached => {
        if (cached) BOT_SELF_ID = parseInt(cached as string, 10);
      }).catch(() => {});
    }

    if (url.pathname === "/health") return createHealthResponse();

    if (url.pathname === "/dashboard") {
      // Same hardening as /admin: the user dashboard previously shipped with
      // only a Content-Type, so it had no CSP, was sniffable, framable and
      // cacheable. It is a Telegram Mini App, so it must stay embeddable by
      // Telegram — hence frame-ancestors allows telegram.org rather than 'none'.
      return new Response(DASHBOARD_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self' https:; img-src 'self' data: https: blob:; media-src 'self' data: https: blob:; font-src 'self' https: data:; frame-ancestors https://web.telegram.org https://*.telegram.org",
          "X-Content-Type-Options": "nosniff",
          "Referrer-Policy": "no-referrer",
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname === "/my" || url.pathname === "/my/") {
      // USER dashboard. Deliberately a separate document from /admin: it holds
      // no global statistics, no other users, no provider data and no admin
      // controls, and every API it calls is scoped by the validated initData.
      return new Response(USER_DASHBOARD_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data: https: blob:; media-src 'self' data: https: blob:; font-src 'self' https: data:; frame-ancestors https://web.telegram.org https://*.telegram.org",
          "X-Content-Type-Options": "nosniff",
          "Referrer-Policy": "no-referrer",
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname === "/tg-webapp.js") {
      return new Response(TG_WEBAPP_JS, {
        headers: {
          "Content-Type": "application/javascript; charset=utf-8",
          "Cache-Control": "public, max-age=86400",
        },
      });
    }

    if (request.method === "POST" && url.pathname === "/webhook") {
      // Authentication already ran before any database work at fetch entry.
      try {
        ctx.waitUntil(warmUserSummaryInfrastructure(env));
        const update = await readJsonObject(request,256_000) as unknown as TgUpdate;
        if (typeof update.update_id !== "number" || !Number.isInteger(update.update_id) || update.update_id < 0) {
          return new Response("Invalid", { status: 400 });
        }

          if (isDuplicateUpdate(update.update_id)) {
          // اگر پیام تکراری بود، بدون پردازش مجدد، سریعاً به تلگرام پاسخ OK بده تا ریتری متوقف شود
          return new Response("OK", { status: 200 });
        }
        // The claim is a D1 INSERT and the session load is a D1 SELECT, and they
        // do not depend on each other — running them back to back put two full
        // round-trips in front of the very first byte of work. Warming the
        // session cache here means the load has usually already resolved by the
        // time the handler asks for it. Fire-and-forget: `getOrCreateSession`
        // coalesces concurrent loads for the same chat, so the handler's own
        // call either hits the cache or joins this in-flight read.
        prewarmSessionForUpdate(update, env);
        // MERGE (from B): skip the claim write for updates nothing will handle.
        const claimKind = await classifyUpdateClaim(update, env);
        if (claimKind === "drop") {
          return new Response("OK", { status: 200 });
        }
        try {
          if (claimKind === "claim" && !await claimUpdateForProcessing(env, update.update_id)) {
            return new Response("OK", { status: 200 });
          }
        } catch (e) {
          forgetUpdateId(update.update_id);
          logger.error("Update claim unavailable; asking Telegram to retry", e);
          return new Response("Retry", { status: 503 });
        }
        try {
          await withTimeout(handleUpdate(update, env), 180_000, "update processing timeout");
        } catch (e) {
          logger.error("Update error", e);
          const isTimeout = e instanceof Error && e.message.includes("update processing timeout");
          if (!isTimeout) forgetUpdateId(update.update_id);
        }

        ctx.waitUntil((async () => {
          // هر مرحله باید مستقل باشد. قبلاً سه await پشت‌سرهم و بدون گارد بودند،
          // پس یک throw در drainBackgroundTasks (یا در فلاش وب‌اپ) باعث می‌شد
          // flushPendingSessions هرگز اجرا نشود → وضعیت نهاییِ همان نوبت فقط در
          // حافظه می‌ماند و با بازیافت ایزوله از دست می‌رفت. رد شدن این rejection
          // به waitUntil هم می‌توانست بقیه‌ی کار پس‌زمینه را لغو کند.
          try {
            await drainBackgroundTasks(8000);
          } catch (e) {
            logger.warn(`[drain] background tasks failed: ${e instanceof Error ? e.message : String(e)}`);
          }
          try {
            // force=true: with force=false `saveSession` re-checks the throttle and
            // a session written moments ago simply re-buffers itself, so the final
            // state of the turn stayed in memory only and was lost whenever the
            // isolate was recycled before the next message. This runs after the
            // response is already returned, and the write-hash check above still
            // suppresses no-op writes, so the cost is at most one D1 write per
            // update that actually changed something.
            await flushPendingSessions(env, true);
          } catch (e) {
            logger.error(`[drain] session flush failed: ${e instanceof Error ? e.message : String(e)}`);
          }
          try {
            await flushWebAppViews(env);
          } catch (e) {
            logger.warn(`[drain] view flush failed: ${e instanceof Error ? e.message : String(e)}`);
          }
        })());

        return new Response("OK", { status: 200 });
      } catch {
        return new Response("Bad Request", { status: 400 });
      }
    }

    return new Response("Not Found", { status: 404 });
  },

  async scheduled(_event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
    try {
      // Cron باید روی Free بسیار سبک بماند.
      // Free Plan = فقط 10ms CPU برای هر Cron invocation.
      if (!env.TOKEN || !env.DB) {
        return;
      }

      // D1-backed KV
      if (!env.SESSIONS) {
        env.DB = governDatabase(env.DB);
        (env as Env).SESSIONS = new D1KVNamespace(env.DB);
      }

      // Same precondition as the fetch path: no KV table, no useful cron work.
      try {
        await ensureCoreSchema(env);
      } catch (e) {
        logger.warn(`cron aborted: core schema unavailable: ${e instanceof Error ? e.message : e}`);
        return;
      }

      globalCtx = _ctx;

      // Cron shares module state with the fetch path, but none of fetch's
      // initialization has run here. `cfg` is declared without an initializer,
      // so an agent job that reached `cfg.*` from cron threw TypeError before
      // doing any work; `env_ref` stayed null and `requestOrigin` stayed empty,
      // which turned every generated media link into "undefined/app/...".
      env_ref = env;
      try {
        cfg = createConfig(env, await getBotConfigCached(env));
        API_URL = `https://api.telegram.org/bot${cfg.TOKEN}`;
      } catch (e) {
        // Keep the tick alive. Reminders and the sweeps below do not need `cfg`,
        // and taking them down over a config problem is strictly worse than
        // letting individual agent jobs fail.
        logger.warn(`cron config init failed: ${e instanceof Error ? e.message : e}`);
        API_URL = `https://api.telegram.org/bot${env.TOKEN}`;
      }

      // A worker only learns its own public origin from a real request, so the
      // fetch path records it and cron restores it here. Without this, media
      // produced by a cron-run agent job is uploaded but linked from nowhere.
      if (!requestOrigin) {
        try {
          const saved = await env.SESSIONS.get(WORKER_ORIGIN_KEY, "text") as string | null;
          if (saved && saved.startsWith("https://")) requestOrigin = saved;
        } catch { /* links degrade; never fail the whole tick over this */ }
      }

      // اطمینان از وجود جدول خلاصه‌ی users (خودمهاجر — idempotent)
      await ensureUserSchemaOnce(env).catch((e) => {
        logger.warn(
          `[schema] initialization failed: ${
            e instanceof Error ? e.message : String(e)
          }`
        );
      });
      // ⚙️ Automation Tick — deliberately tiered.
      //
      // The cron fires every minute but the Free plan allows only ~10ms CPU per
      // invocation, so running reminders + media cleanup + view flush +
      // housekeeping together on EVERY tick blew the budget and could get the
      // whole tick cancelled (taking reminders down with it). Only the
      // minute-sensitive job runs unconditionally; the sweeps rotate.
      const tickMinute = Math.floor(Date.now() / 60_000);

      // Every tick: due reminders are the only genuinely time-sensitive job.
      await processDueReminders(env)
        .catch(e => logger.warn(`cron reminders failed: ${e instanceof Error ? e.message : e}`));

      // Every tick, but cheap and self-bounded: pending broadcast batch.
      await processBroadcastBatch(env)
        .catch(e => logger.warn(`cron broadcast failed: ${e instanceof Error ? e.message : e}`));

      // Every tick: drain any session write the coalescer deferred. The buffer is
      // per-isolate, so this only helps when the cron shares an isolate with a
      // recent request — the authoritative flush is the forced one in the
      // webhook's waitUntil tail. Bounded so it cannot eat the tick.
      await flushPendingSessions(env, true, 2500)
        .catch(e => logger.warn(`cron session flush failed: ${e instanceof Error ? e.message : e}`));

      // Every 5 minutes: flush buffered web-app view counters.
      if (tickMinute % 5 === 0) {
        await flushWebAppViews(env, 3000).catch(() => {});
      }

      // Every 5 minutes (offset): enforce hosted-deployment expiry.
      //
      // This is the authoritative cleanup. It reads only persisted rows, so it
      // is correct on a cron isolate that has never seen the deployment, and it
      // is bounded per tick. The `/app/` route also refuses an expired slug and
      // tears it down inline, so a deployment stops resolving at its expiry even
      // if this sweep is delayed.
      if (tickMinute % 5 === 2) {
        await sweepExpiredDeployments(env)
          .catch(e => logger.warn(`cron deployment sweep failed: ${e instanceof Error ? e.message : e}`));
      }

      // Every 10 minutes (offset): expired-row / diagnostics / users sweep.
      if (tickMinute % 10 === 3) {
        await runHousekeeping(env)
          .catch(e => logger.warn(`cron housekeeping failed: ${e instanceof Error ? e.message : e}`));
      }

      // Every 30 minutes (offset): expired media blobs.
      if (tickMinute % 30 === 7) {
        await cleanupExpiredMedia(env)
          .catch(e => logger.warn(`cron media cleanup failed: ${e instanceof Error ? e.message : e}`));
      }

      // In-memory only; negligible cost.
      pruneMemoryCaches();

    } catch (e) {
      logger.warn(
        `Scheduled automation tick failed: ${e instanceof Error ? e.message : String(e)}`
      );
    }
  },
};
